LN_DEPENDENCIES = ['PyQt6>=6.6,<6.11', 'aiohttp>=3.11.0', 'requests>=2.32.0', 'charset-normalizer>=3.3.0', 'orjson>=3.10.0', 'py3langid>=0.2.0', 'openai>=1.14.0', 'google-genai>=1.0.0', 'unrpa>=2.3.0', 'rich>=13.7.0', 'PyYAML>=6.0.1', 'fonttools>=4.38.0']

