import ntpath as LN_start__ntpath

LN_start__QT_DLL_SUFFIX = r'Lib\site-packages\PyQt6\Qt6\qml\QtQuick\Controls\Material\impl\qtquickcontrols2materialstyleimplplugin.dll'


def LN_start__environment_path(root, fingerprint):
    """Keep Windows Qt binaries outside the downloaded project's long path."""
    if LN_start__os.name != 'nt':
        return str(LN_start__Path(root) / '.venv_prueba_155')
    interpreter = getattr(LN_start__sys, '_base_executable', None) or LN_start__sys.executable
    identity = LN_start__json.dumps([
        LN_start__ntpath.normcase(str(root)),
        LN_start__ntpath.normcase(str(interpreter)),
        list(LN_start__sys.version_info[:3]),
        64 if LN_start__sys.maxsize > 2**32 else 32,
        fingerprint,
    ], ensure_ascii=True).encode('ascii')
    token = LN_start__hashlib.sha256(identity).hexdigest()[:10]
    tag = 'p' + str(LN_start__sys.version_info[0]) + str(LN_start__sys.version_info[1]) + '-' + token
    env = LN_start__os.environ
    bases = []
    if env.get('LOCALAPPDATA'):
        bases.append(LN_start__ntpath.join(env['LOCALAPPDATA'], 'LN', 'v'))
    if env.get('USERPROFILE'):
        bases.append(LN_start__ntpath.join(env['USERPROFILE'], '.ln', 'v'))
    temporary = env.get('TEMP') or env.get('TMP') or LN_start__tempfile.gettempdir()
    bases.append(LN_start__ntpath.join(temporary, 'LN', 'v'))
    for base in bases:
        candidate = LN_start__ntpath.normpath(LN_start__ntpath.join(base, tag))
        dll = LN_start__ntpath.join(candidate, LN_start__QT_DLL_SUFFIX)
        # Leave headroom for Qt's loader and its longer plugin filenames.
        if LN_start__ntpath.isabs(candidate) and len(dll.encode('utf-16-le')) // 2 <= 200:
            return candidate
    raise RuntimeError('No se encontró una ruta corta para el entorno de Qt. Revisa LOCALAPPDATA, USERPROFILE y TEMP. No se modificó la instalación anterior.')


def LN_start__qt_environment():
    env = LN_start__os.environ.copy()
    # Other Qt installations must not inject plugins into this isolated runtime.
    for key in ('QT_PLUGIN_PATH', 'QT_QPA_PLATFORM_PLUGIN_PATH', 'QML_IMPORT_PATH', 'QML2_IMPORT_PATH'):
        env.pop(key, None)
    return env


def LN_start__check_qt(python, log):
    """Load the actual Material Dialog plugin; importing PyQt6 alone is insufficient."""
    probe = r"""
import sys
import os
os.environ['QT_QUICK_CONTROLS_STYLE'] = 'Material'
from PyQt6.QtCore import QUrl
from PyQt6.QtGui import QGuiApplication
from PyQt6.QtQml import QQmlComponent, QQmlEngine
app = QGuiApplication([])
engine = QQmlEngine()
component = QQmlComponent(engine)
component.setData(b'import QtQuick\nimport QtQuick.Controls\nimport QtQuick.Controls.Material\nItem { Dialog {} }', QUrl())
item = component.create()
if item is None:
    for error in component.errors():
        print(error.toString(), file=sys.stderr)
    raise SystemExit(1)
"""
    try:
        result = LN_start__subprocess.run(
            [str(python), '-c', probe], env=LN_start__qt_environment(),
            stdout=LN_start__subprocess.PIPE, stderr=LN_start__subprocess.STDOUT,
            text=True, encoding='utf-8', errors='replace', timeout=45,
        )
    except (OSError, LN_start__subprocess.SubprocessError) as exc:
        with LN_start__Path(log).open('a', encoding='utf-8') as stream:
            stream.write('\n[Qt] No se pudo comprobar Dialog Material: ' + str(exc) + '\n')
        raise RuntimeError('No se pudo comprobar Qt antes del arranque. Consulta ' + str(log)) from exc
    with LN_start__Path(log).open('a', encoding='utf-8') as stream:
        stream.write('\n[Qt] Python: ' + str(python) + '\n' + result.stdout)
        stream.write('[Qt] Dialog Material: ' + ('correcto' if result.returncode == 0 else 'ERROR') + '\n')
    if result.returncode:
        raise RuntimeError('Qt no pudo cargar Dialog Material. Consulta el motivo y la ruta de la DLL en ' + str(log))

def LN_start__prepare(root, *, environment=None, requirements=None):
    root = LN_start__Path(root).resolve()
    # ==============================================================================
    # INICIO: Bloque If de prepare — LN_start__sys.version_info < LN_start__MINIMUM_PYTHON
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_start__sys.version_info < LN_start__MINIMUM_PYTHON. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if LN_start__sys.version_info < LN_start__MINIMUM_PYTHON:
        raise RuntimeError('LinguaNova requiere Python 3.10 o superior. No se exige una versión menor concreta.')
    # ==============================================================================
    # FIN: Bloque If de prepare — LN_start__sys.version_info < LN_start__MINIMUM_PYTHON
    # ==============================================================================
    requirements = LN_start__Path(requirements) if requirements else None
    fingerprint = LN_start__hashlib.sha256(requirements.read_bytes() if requirements else LN_start__json.dumps(LN_DEPENDENCIES).encode('utf-8')).hexdigest()
    environment = LN_start__Path(environment or LN_start__environment_path(root, fingerprint))
    python = environment / ('Scripts/python.exe' if LN_start__os.name == 'nt' else 'bin/python')
    log = root / 'inicio_error.log'
    # ==============================================================================
    # INICIO: Bloque If de prepare — not LN_start__works(python, 'import sys; raise SystemExit(0 if sys.version_info >= (3,10) else 1)')
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not LN_start__works(python, 'import sys; raise SystemExit(0 if sys.version_info >= (3,10) else 1)'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if not LN_start__works(python, 'import sys; raise SystemExit(0 if sys.version_info >= (3,10) else 1)'):
        print('Preparando LinguaNova con Python ' + LN_start__sys.version.split()[0] + '…', flush=True)
        LN_start__venv.EnvBuilder(with_pip=False).create(environment)
    # ==============================================================================
    # FIN: Bloque If de prepare — not LN_start__works(python, 'import sys; raise SystemExit(0 if sys.version_info >= (3,10) else 1)')
    # ==============================================================================
    LN_start__ensure_pip(python, log)
    marker = environment / 'linguanova-requirements.sha256'
    installed = marker.read_text().strip() if marker.is_file() else ''
    smoke = 'import PyQt6,aiohttp,requests,charset_normalizer,orjson,py3langid,openai,google.genai,unrpa,rich,yaml,fontTools'
    # ==============================================================================
    # INICIO: Bloque If de prepare — installed != fingerprint or not LN_start__works(python, smoke)
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: installed != fingerprint or not LN_start__works(python, smoke). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if installed != fingerprint or not LN_start__works(python, smoke):
        print('Preparando las dependencias de la aplicación principal. Se necesita Internet…', flush=True)
        install = [str(python), '-m', 'pip', 'install', '--retries', '5', '--default-timeout', '60']
        # ==============================================================================
        # INICIO: Bloque Try de prepare — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            LN_start__checked(install + (['-r', str(requirements)] if requirements else LN_DEPENDENCIES), log, cwd=root)
        except RuntimeError:
            LN_start__checked(install + ['--prefer-binary'] + (['-r', str(requirements)] if requirements else LN_DEPENDENCIES), log, cwd=root)
        # ==============================================================================
        # FIN: Bloque Try de prepare — gestión de excepciones
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de prepare — not LN_start__works(python, smoke)
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not LN_start__works(python, smoke). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not LN_start__works(python, smoke):
            raise RuntimeError('Una dependencia no pudo cargarse. Consulta ' + str(log))
        # ==============================================================================
        # FIN: Bloque If de prepare — not LN_start__works(python, smoke)
        # ==============================================================================
        marker.write_text(fingerprint, encoding='ascii')
    # ==============================================================================
    # FIN: Bloque If de prepare — installed != fingerprint or not LN_start__works(python, smoke)
    # ==============================================================================
    LN_start__ensure_optional(python, log, environment)
    LN_start__check_qt(python, log)
    return python
# ==============================================================================
# FIN: Acción de soporte prepare
# ==============================================================================

# ==============================================================================
# INICIO: Acción de soporte ensure_optional
# FUNCIÓN: Instala las librerías opcionales de imagen sin impedir el arranque.
# Solo paquetes ya compilados (--only-binary), con pocos reintentos, y como mucho
# un intento al día cuando falla (sin Internet, o un Python sin paquetes).
# ==============================================================================
def LN_start__ensure_optional(python, log, environment):
    import time
    if LN_start__works(python, LN_OPTIONAL_IMPORTS):
        return
    state_file = LN_start__Path(environment) / 'linguanova-optional.json'
    wanted = LN_start__hashlib.sha256(LN_start__json.dumps(LN_OPTIONAL_DEPENDENCIES).encode('utf-8')).hexdigest()
    try:
        state = LN_start__json.loads(state_file.read_text(encoding='utf-8'))
    except (OSError, ValueError):
        state = {}
    if state.get('fingerprint') == wanted and time.time() - float(state.get('tried', 0)) < 86400:
        return
    print('Instalando las librerías de imagen de «Aligerar el juego» (opcionales)…', flush=True)
    install = [str(python), '-m', 'pip', 'install', '--only-binary', ':all:', '--retries', '1', '--default-timeout', '20']
    try:
        LN_start__checked(install + LN_OPTIONAL_DEPENDENCIES, log)
    except RuntimeError:
        for requirement in LN_OPTIONAL_DEPENDENCIES:
            try:
                LN_start__checked(install + [requirement], log)
            except RuntimeError:
                pass
    state_file.write_text(LN_start__json.dumps({'fingerprint': wanted, 'tried': time.time()}), encoding='utf-8')
# ==============================================================================
# FIN: Acción de soporte ensure_optional
# ==============================================================================

# ==============================================================================
# INICIO: Acción de soporte main
# FUNCIÓN: Implementación directa main. Origen trazable: start.py.
# Secuencia del bloque: list → LN_start__prepare → print → LN_start__Path(__file__).resolve → LN_start__subprocess.run → LN_start__Path → str.
# Interacción con archivos/ejecutables, en orden del código (se respetan las condiciones visibles):
# Paso 1: LN_start__subprocess.run([str(python), str(LN_SINGLE_FILE), '--directo', *args], cwd=root).
# ==============================================================================
def LN_start__main(argv=None):
    root = LN_start__Path(__file__).resolve().parent
    args = list(LN_start__sys.argv[1:] if argv is None else argv)
    python = LN_start__prepare(root)
    # ==============================================================================
    # INICIO: Bloque If de main — '--preparar' in args
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: '--preparar' in args. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if '--preparar' in args:
        (root / '.linguanova-python.txt').write_text(str(python) + '\n', encoding='utf-8')
        print('Entorno de Python y componentes de Qt comprobados.', flush=True)
        return 0
    # ==============================================================================
    # FIN: Bloque If de main — '--preparar' in args
    # ==============================================================================
    print('Abriendo LinguaNova…', flush=True)
    return LN_start__subprocess.run([str(python), str(LN_SINGLE_FILE), '--directo', *args], cwd=root, env=LN_start__qt_environment()).returncode
# ==============================================================================
# FIN: Acción de soporte main
# ==============================================================================

# ==============================================================================
# INICIO: Acción de soporte launch
# FUNCIÓN: Implementación directa launch. Origen trazable: start.py.
# Secuencia del bloque: LN_start__main → print → log.open → LN_start__traceback.print_exc → LN_start__Path(__file__).resolve → str → log.read_text(encoding='utf-8', errors='replace').splitlines → '\n'.join → LN_start__Path → log.read_text → LN_start__sys.version.split.
# Interacción con archivos/ejecutables, en orden del código (se respetan las condiciones visibles):
# Paso 1: log.open('a', encoding='utf-8').
# Paso 2: log.read_text(encoding='utf-8', errors='replace').splitlines().
# Paso 3: log.read_text(encoding='utf-8', errors='replace').
# ==============================================================================
def LN_start__launch():
    # ==============================================================================
    # INICIO: Bloque Try de launch — gestión de excepciones
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    try:
        return LN_start__main()
    except Exception:
        log = LN_start__Path(__file__).resolve().parent / 'inicio_error.log'
        # ==============================================================================
        # INICIO: Bloque With de launch — log.open('a', encoding='utf-8')
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: log.open('a', encoding='utf-8'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        with log.open('a', encoding='utf-8') as stream:
            LN_start__traceback.print_exc(file=stream)
        # ==============================================================================
        # FIN: Bloque With de launch — log.open('a', encoding='utf-8')
        # ==============================================================================
        print('No se pudo iniciar LinguaNova. Consulta: ' + str(log), file=LN_start__sys.stderr)
        # ==============================================================================
        # INICIO: Bloque Try de launch — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            tail = log.read_text(encoding='utf-8', errors='replace').splitlines()[-25:]
            print('--- ultimas lineas de inicio_error.log ---\n' + '\n'.join(tail), file=LN_start__sys.stderr)
            # ==============================================================================
            # INICIO: Bloque If de launch — LN_start__sys.version_info >= (3, 14)
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_start__sys.version_info >= (3, 14). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if LN_start__sys.version_info >= (3, 14) and any(reason in '\n'.join(tail).lower() for reason in ('no matching distribution found', 'could not find a version that satisfies')):
                print('Sugerencia: Python ' + LN_start__sys.version.split()[0] + ' es muy nuevo y algunas librerias aun no tienen paquetes para el. Instala Python 3.12 o 3.13 y vuelve a ejecutar.', file=LN_start__sys.stderr)
            # ==============================================================================
            # FIN: Bloque If de launch — LN_start__sys.version_info >= (3, 14)
            # ==============================================================================
        except OSError:
            pass
        # ==============================================================================
        # FIN: Bloque Try de launch — gestión de excepciones
        # ==============================================================================
        return 1
    # ==============================================================================
    # FIN: Bloque Try de launch — gestión de excepciones
    # ==============================================================================
# ==============================================================================
# FIN: Acción de soporte launch
# ==============================================================================
pass
