# Paso 2: si falta una dependencia, prepara .venv y relanza ESTE archivo.
# Paso 3: --directo evita un bucle de relanzamiento; en ejecutables no usa venv.
# ==============================================================================
if __name__ == "__main__" and not getattr(LN_SYSTEM_SYS, "frozen", False):
    import importlib.util as LN_EXTERNAL_SPEC
    if "--preparar" in LN_SYSTEM_SYS.argv:
        raise SystemExit(LN_start__launch())
    if "--directo" not in LN_SYSTEM_SYS.argv:
        LN_MISSING_DEPS = []
        for LN_REQUIRED_IMPORT in ("PyQt6", "aiohttp", "requests", "charset_normalizer", "orjson", "py3langid", "openai", "google.genai", "unrpa", "rich", "yaml", "fontTools"):
            try:
                if LN_EXTERNAL_SPEC.find_spec(LN_REQUIRED_IMPORT) is None:
                    LN_MISSING_DEPS.append(LN_REQUIRED_IMPORT)
            except (ImportError, ModuleNotFoundError, ValueError):
                LN_MISSING_DEPS.append(LN_REQUIRED_IMPORT)
        if LN_MISSING_DEPS or LN_SYSTEM_OS.name == 'nt':
            raise SystemExit(LN_start__launch())
    if "--directo" in LN_SYSTEM_SYS.argv:
        LN_SYSTEM_SYS.argv.remove("--directo")
# ==============================================================================
# FIN: Arranque y comprobación de dependencias
