    'Connections {\n'
    '        target: appBackend\n'
    '        function onProjectChanged(path) { projectPathField.text = path }\n'
    '\n'
    '        function onLogMessage(level, message) {\n'
    '            var displayMessage = appBackend.localizeLogMessage(message)\n'
    '            appendLog(level, displayMessage)\n'
    '            if (message.indexOf("❌") >= 0 && (message.indexOf("select a game") >= 0 || message.indexOf("not found") >= 0 || message.indexOf("game folder") >= 0 || message.indexOf("oyun") >= 0))\n'
    '                projectPathField.triggerShake()\n'
    '            // Show toast for toolbox operations and key events\n'
    '            if (message.indexOf("✅") === 0 && (message.indexOf("Font") >= 0 || message.indexOf("Lint") >= 0 || message.indexOf("terms") >= 0 || message.indexOf("imported") >= 0 || message.indexOf("exported") >= 0 || message.indexOf("filled") >= 0 || message.indexOf("translated") >= 0))\n'
    '                showToast(displayMessage.replace("✅ ", ""), "success")\n'
    '            else if (message.indexOf("⚠️") === 0 && (message.indexOf("failed") >= 0 || message.indexOf("not found") >= 0))\n'
    '                showToast(displayMessage.replace("⚠️ ", ""), "warning")\n'
    '            else if (message.indexOf("🔤") === 0 || message.indexOf("🩺") === 0 || message.indexOf("📚") === 0)\n'
    '                showToast(displayMessage, "info")\n'
    '        }\n'
    '\n'
    '        function onProgressChanged(current, total, text) {\n'
    '            if (total > 0) progressBar.value = current / total\n'
    '            progressLabel.text = text + " (" + current + "/" + total + ")"\n'
    '        }\n'
    '\n'
    '        function onStageChanged(stage, displayName) {\n'
    '            currentStage = stage\n'
    '            stageCustomName = cleanStageText(displayName)\n'
    '            var stageProgress = {\n'
    '                "idle": 0, "validating": 5, "unren": 15,\n'
    '                "generating": 30, "parsing": 40,\n'
    '                "saving": 90, "completed": 100, "error": 0\n'
    '            }\n'
    '            if (stage !== "translating" && stageProgress[stage] !== undefined)\n'
    '                progressBar.value = stageProgress[stage] / 100\n'
    '        }\n'
    '\n'
    '        function onTranslationStarted() {\n'
    '            isTranslating = true\n'
    '            // Close any route picker that happened to be open as the run started.\n'
    '            if (sourceLangPopup.opened) sourceLangPopup.close()\n'
    '            if (targetLangPopup.opened) targetLangPopup.close()\n'
    '            statsVisible = false\n'
    '            progressBar.value = 0\n'
    '            progressLabel.text = ""\n'
    '            currentStage = "starting"\n'
    '            navIndex = 0 // Switch to the Dashboard tab to follow the run live\n'
    '        }\n'
    '\n'
    '        function onTranslationFinished(success, message) {\n'
    '            isTranslating = false\n'
    '            progressBar.value = successRate / 100\n'
    '            // Five-language batch: no toast per language; one summary at the end.\n'
    '            if (appBackend.batchInProgress) {\n'
    '                currentStage = success ? "completed" : "error"\n'
    '                return\n'
    '            }\n'
    '            if (success) {\n'
    '                currentStage = "completed"\n'
    '                if (statsPartial)\n'
    '                    showToast(appBackend.getTextWithDefault("translation_completed_partial", "Translation finished with pending lines"), "warning")\n'
    '                else\n'
    '                    showToast(appBackend.getTextWithDefault("translation_completed", "Translation completed successfully."), "success")\n'
    '            } else {\n'
    '                currentStage = "error"\n'
    '                showToast(appBackend.getTextWithDefault("pipeline_translate_failed", "Translation failed") + ": " + message, "error")\n'
    '            }\n'
    '        }\n'
    '\n'
    '        function onStatsReady(total, translated, untranslated) {\n'
    '            // Banner numbers only; the backend logs the full breakdown\n'
    '            // (translated / same as original / empty / failed / blocked).\n'
    '            totalLines = total\n'
    '            translatedLines = translated\n'
    '            successRate = total > 0 ? (translated / total) * 100 : 0\n'
    '        }\n'
    '\n'
    '        function onStatsDetailReady(scope, total, translated, unchanged, pending, partial) {\n'
    '            statsScope = scope\n'
    '            totalLines = total\n'
    '            translatedLines = translated\n'
    '            unchangedLines = unchanged\n'
    '            pendingLines = pending\n'
    '            statsPartial = partial\n'
    '            successRate = total > 0 ? (translated / total) * 100 : (scope === "translation" ? 100 : 0)\n'
    '            statsVisible = true\n'
    '        }\n'
    '\n'
    '        function onStatsCleared() {\n'
    '            statsVisible = false\n'
    '            statsPartial = false\n'
    '            progressBar.value = 0\n'
    '            progressLabel.text = ""\n'
    '        }\n'
    '\n'
    '        function onBatchSummaryReady(reportJson, reportPath) {\n'
    '            batchSummaryDialog.show(reportJson, reportPath, "translation")\n'
    '        }\n'
    '\n'
    '        function onCompletionSummary(title, message, outPath, diagPath, reviewCount) {\n'
    '            outputPath = outPath\n'
    '            completionDialog.summaryTitle = title\n'
    '            completionDialog.summaryText = message\n'
    '            completionDialog.outputPath = outPath\n'
    '            completionDialog.diagPath = diagPath\n'
    '            completionDialog.open()\n'
