    '\n'
    '        function onWarningMessage(title, message) {\n'
    '            warningDialog.titleText = title\n'
    '            warningDialog.bodyText = message\n'
    '            warningDialog.open()\n'
    '        }\n'
    '\n'
    '        function onUpdateAvailable(currentVersion, latestVersion, releaseUrl) {\n'
    '            updateDialog.latestVersion = latestVersion\n'
