    '            function filteredGlossaryModel() {\n'
    '                appBackend.uiTrigger\n'
    '                var list = appBackend.glossaryList || []\n'
    '                var q = pageGlossary.searchQuery\n'
    '                if (!q) return list\n'
    '                var result = []\n'
    '                for (var i = 0; i < list.length; i++) {\n'
    '                    var item = list[i]\n'
    '                    var s = (item.source || "").toLowerCase()\n'
    '                    var t = (item.target || "").toLowerCase()\n'
    '                    if (s.indexOf(q) !== -1 || t.indexOf(q) !== -1) {\n'
    '                        result.push(item)\n'
    '                    }\n'
    '                }\n'
    '                return result\n'
    '            }\n'
