LN_RESOURCE_src_gui_qml_components_OptimizeGameCard_qml = (
    '// SPDX-License-Identifier: GPL-3.0-or-later\n'
    '// LinguaNova: new component (2026-11-11).\n'
    '// «Aligerar el juego»: a lighter copy of the selected game. The original is never\n'
    '// written. Audio and video need ffmpeg, a separate program (found, downloaded or chosen).\n'
    'import QtQuick\n'
    'import QtQuick.Controls\n'
    'import QtQuick.Dialogs\n'
    'import QtQuick.Layouts\n'
    '\n'
    'Rectangle {\n'
    '    id: card\n'
    '    objectName: "optimizeGameCard"\n'
    '    property bool locked: false\n'
    '    readonly property bool hasGame: (dashboardBackend.projectInfo.path || "").length > 0\n'
    '    readonly property bool hasFfmpeg: optimizerBackend.ffmpegPath.length > 0\n'
    '    readonly property bool canStart: !optimizerBackend.busy && !card.locked && card.hasGame\n'
    '    function t(key, fallback) { var refresh = appBackend.uiTrigger; return appBackend.getTextWithDefault(key, fallback) }\n'
    '\n'
    '    implicitHeight: content.implicitHeight + 32\n'
    '    radius: Theme.radiusLg\n'
    '    color: Theme.card\n'
    '    border.color: Theme.cardBorder\n'
    '\n'
    '    ColumnLayout {\n'
    '        id: content\n'
    '        anchors.fill: parent\n'
    '        anchors.margins: 16\n'
    '        spacing: 10\n'
    '\n'
    '        PageHeader {\n'
    '            glyph: "⇣"\n'
    '            glyphColor: Theme.success\n'
    '            title: card.t("opt_title", "Lighten the game")\n'
    '            subtitle: card.t("opt_desc", "Creates a lighter copy of the game next to it, with recompressed images, audio and video. The original game is not touched. Use it after translating and generating the MOD: the copy keeps them.")\n'
    '        }\n'
    '\n'
    '        RowLayout {\n'
    '            Layout.fillWidth: true\n'
    '            spacing: 10\n'
    '            Label {\n'
    '                text: card.t("opt_level_label", "Compression")\n'
    '                color: Theme.txt\n'
    '                font.pixelSize: Theme.fontMd\n'
    '            }\n'
    '            ComboBox {\n'
    '                id: levelBox\n'
    '                objectName: "optimizeLevel"\n'
    '                Layout.preferredWidth: 300\n'
    '                Layout.preferredHeight: 40\n'
    '                font.pixelSize: Theme.fontMd\n'
    '                enabled: !optimizerBackend.busy\n'
    '                currentIndex: 1\n'
    '                model: [card.t("opt_level_safe", "Safe"),\n'
    '                        card.t("opt_level_balanced", "Balanced (recommended)"),\n'
    '                        card.t("opt_level_max", "Maximum")]\n'
    '            }\n'
    '            Item { Layout.fillWidth: true }\n'
    '        }\n'
    '        Label {\n'
    '            Layout.fillWidth: true\n'
    '            text: levelBox.currentIndex === 0 ? card.t("opt_level_safe_hint", "No quality loss at all. Small saving.")\n'
    '                : levelBox.currentIndex === 2 ? card.t("opt_level_max_hint", "The smallest size. It may show in colour gradients and in music with headphones.")\n'
    '                : card.t("opt_level_balanced_hint", "Loss you will not notice. Good saving.")\n'
    '            color: Theme.txtDim\n'
    '            font.pixelSize: Theme.fontSm\n'
    '            wrapMode: Text.WordWrap\n'
    '        }\n'
    '\n'
    '        CheckBox {\n'
    '            id: oldPc\n'
    '            implicitHeight: 32\n'
    '            topPadding: 0; bottomPadding: 0\n'
    '            font.pixelSize: Theme.fontMd\n'
    '            objectName: "optimizeOldPc"\n'
    '            enabled: !optimizerBackend.busy\n'
    '            text: card.t("opt_old_pc", "Old PC mode (only for the game\'s videos)")\n'
    '        }\n'
    '        Label {\n'
    '            Layout.fillWidth: true\n'
    '            Layout.leftMargin: 32\n'
    '            text: card.t("opt_old_pc_hint", "For a copy meant for a PC where videos stutter: at most 720p and 30 frames per second, in a format that is easier to play. Not recommended for a copy you will share.")\n'
    '            color: Theme.txtDim\n'
    '            font.pixelSize: Theme.fontSm\n'
    '            wrapMode: Text.WordWrap\n'
    '        }\n'
    '        CheckBox {\n'
    '            id: windowsOnly\n'
    '            implicitHeight: 32\n'
    '            topPadding: 0; bottomPadding: 0\n'
    '            font.pixelSize: Theme.fontMd\n'
    '            objectName: "optimizeWindowsOnly"\n'
    '            enabled: !optimizerBackend.busy\n'
    '            text: card.t("opt_windows_only", "Remove engine files for Linux and Mac")\n'
    '        }\n'
    '        CheckBox {\n'
    '            id: lowRam\n'
    '            implicitHeight: 32\n'
    '            topPadding: 0; bottomPadding: 0\n'
    '            font.pixelSize: Theme.fontMd\n'
    '            objectName: "optimizeLowRam"\n'
    '            enabled: !optimizerBackend.busy\n'
    '            text: card.t("opt_low_ram", "Settings for PCs with little RAM")\n'
    '        }\n'
    '\n'
    '        Rectangle {\n'
    '            Layout.fillWidth: true\n'
    '            implicitHeight: ffmpegRow.implicitHeight + 20\n'
    '            radius: Theme.radiusMd\n'
    '            color: Theme.input\n'
    '            border.color: Theme.tint(card.hasFfmpeg ? Theme.success : Theme.warn, 0.4)\n'
    '\n'
    '            RowLayout {\n'
    '                id: ffmpegRow\n'
    '                anchors.fill: parent\n'
    '                anchors.margins: 10\n'
    '                spacing: 8\n'
    '                Label {\n'
    '                    Layout.fillWidth: true\n'
    '                    text: card.hasFfmpeg\n'
    '                          ? card.t("opt_ffmpeg_found", "Audio and video: ffmpeg ready ({path}).").replace("{path}", optimizerBackend.ffmpegPath)\n'
    '                          : card.t("opt_ffmpeg_missing", "Audio and video need ffmpeg, a separate free program. Without it only images are compressed.")\n'
    '                    color: card.hasFfmpeg ? Theme.success : Theme.warn\n'
    '                    font.pixelSize: Theme.fontSm\n'
    '                    wrapMode: Text.WrapAnywhere\n'
    '                }\n'
    '                ThemedButton {\n'
    '                    objectName: "downloadFfmpeg"\n'
    '                    visible: !card.hasFfmpeg && optimizerBackend.canDownloadFfmpeg\n'
    '                    enabled: !optimizerBackend.busy\n'
    '                    tint: Theme.warn\n'
    '                    emphasized: true\n'
    '                    text: card.t("opt_ffmpeg_download", "Download ffmpeg (~100 MB)")\n'
    '                    onClicked: optimizerBackend.downloadFfmpeg()\n'
    '                }\n'
    '                ThemedButton {\n'
    '                    visible: !card.hasFfmpeg\n'
    '                    enabled: !optimizerBackend.busy\n'
    '                    text: card.t("opt_ffmpeg_choose", "Choose ffmpeg.exe…")\n'
    '                    onClicked: ffmpegPicker.open()\n'
    '                }\n'
    '            }\n'
    '        }\n'
    '        Label {\n'
    '            Layout.fillWidth: true\n'
    '            visible: optimizerBackend.missingLibraries.length > 0\n'
    '            text: card.t("opt_libs_missing", "Missing image libraries: {libs}.").replace("{libs}", optimizerBackend.missingLibraries)\n'
    '            color: Theme.warn\n'
    '            font.pixelSize: Theme.fontSm\n'
    '            wrapMode: Text.WordWrap\n'
    '        }\n'
    '\n'
    '        RowLayout {\n'
    '            Layout.fillWidth: true\n'
    '            spacing: 8\n'
    '            ThemedButton {\n'
    '                objectName: "createOptimizedCopy"\n'
    '                emphasized: true\n'
    '                tint: Theme.success\n'
    '                enabled: card.canStart\n'
    '                text: card.t("opt_create", "Create lighter copy")\n'
    '                onClicked: {\n'
    '                    var suggested = optimizerBackend.suggestedParentUrl()\n'
    '                    if (suggested.length > 0) folderPicker.currentFolder = suggested\n'
    '                    folderPicker.open()\n'
    '                }\n'
    '            }\n'
    '            ThemedButton {\n'
    '                objectName: "estimateOptimization"\n'
    '                enabled: card.canStart\n'
    '                text: card.t("opt_estimate", "Estimate saving")\n'
    '                onClicked: optimizerBackend.estimate(levelBox.currentIndex, oldPc.checked, windowsOnly.checked)\n'
    '            }\n'
    '            ThemedButton {\n'
    '                visible: optimizerBackend.busy\n'
    '                text: card.t("opt_cancel", "Stop")\n'
    '                onClicked: optimizerBackend.cancel()\n'
    '            }\n'
    '            ThemedButton {\n'
    '                visible: !optimizerBackend.busy && optimizerBackend.lastOutputPath.length > 0\n'
    '                text: card.t("opt_reveal", "Open copy")\n'
    '                onClicked: optimizerBackend.revealOutput()\n'
    '            }\n'
    '            BusyIndicator {\n'
    '                visible: optimizerBackend.busy\n'
    '                running: visible\n'
    '                Layout.preferredWidth: 24; Layout.preferredHeight: 24\n'
    '            }\n'
    '            Item { Layout.fillWidth: true }\n'
    '        }\n'
    '        ProgressBar {\n'
    '            Layout.fillWidth: true\n'
    '            visible: optimizerBackend.busy\n'
    '            from: 0; to: 1\n'
    '            value: optimizerBackend.fraction\n'
    '        }\n'
    '        Label {\n'
    '            Layout.fillWidth: true\n'
    '            visible: optimizerBackend.busy && text.length > 0\n'
    '            text: optimizerBackend.stage\n'
    '            color: Theme.txt2\n'
    '            font.pixelSize: Theme.fontSm\n'
    '            wrapMode: Text.WordWrap\n'
    '        }\n'
    '        Label {\n'
    '            Layout.fillWidth: true\n'
    '            visible: text.length > 0\n'
    '            text: optimizerBackend.status\n'
    '            color: Theme.txt2\n'
    '            font.pixelSize: Theme.fontSm\n'
    '            wrapMode: Text.WrapAnywhere\n'
    '        }\n'
    '    }\n'
    '\n'
    '    FolderDialog {\n'
    '        id: folderPicker\n'
    '        title: card.t("opt_pick_folder", "Where to create the lighter copy")\n'
    '        onAccepted: optimizerBackend.optimize(selectedFolder.toString(), levelBox.currentIndex, oldPc.checked, windowsOnly.checked, lowRam.checked)\n'
    '    }\n'
    '    FileDialog {\n'
    '        id: ffmpegPicker\n'
    '        fileMode: FileDialog.OpenFile\n'
    '        title: card.t("opt_pick_ffmpeg", "Choose ffmpeg.exe")\n'
    '        nameFilters: ["ffmpeg (ffmpeg.exe ffmpeg)", "* (*)"]\n'
    '        onAccepted: optimizerBackend.chooseFfmpeg(selectedFile.toString())\n'
    '    }\n'
    '}\n'
)
