# INICIO: Registro de recursos Qt en memoria
# FUNCIÓN: Construye los índices de nombres y contenido del formato Qt Resource versión 1 y los registra. Mantiene los tres búferes vivos. QML, iconos y componentes se leen mediante qrc:/linguanova/; no se crean archivos de código auxiliares.
# ==============================================================================
import struct
from PyQt6.QtCore import qRegisterResourceData,QFile

def LN_register_resource_buffers(files):
 def h(s):
  v=0
  for c in s:
   v=(v<<4)+ord(c);v^=(v&0xf0000000)>>23;v&=0x0fffffff
  return v
 root={'name':'','children':{}}
 for path,data in files.items():
  cur=root
  parts=path.split('/')
  for p in parts: cur=cur['children'].setdefault(p,{'name':p,'children':{}})
  cur['data']=data
 nodes=[root]
 for n in nodes:
  ch=sorted(n['children'].values(),key=lambda x:(h(x['name']),x['name']))
  n['offset']=len(nodes);n['count']=len(ch);nodes.extend(ch)
 names=bytearray();payload=bytearray();tree=bytearray()
 for n in nodes:
  off=len(names);name=n['name'];names+=struct.pack('>HI',len(name.encode('utf-16-be'))//2,h(name))+name.encode('utf-16-be')
  if 'data' in n:
   doff=len(payload);data=n['data'];payload+=struct.pack('>I',len(data))+data
   tree+=struct.pack('>IHHHI',off,0,0,1,doff)
  else: tree+=struct.pack('>IHII',off,2,n['count'],n['offset'])
 return bytes(tree),bytes(names),bytes(payload)

LN_QRC_TREE, LN_QRC_NAMES, LN_QRC_DATA = LN_register_resource_buffers({"linguanova/" + k: v for k, v in LN_RESOURCE_MAP.items()})
if not qRegisterResourceData(1, LN_QRC_TREE, LN_QRC_NAMES, LN_QRC_DATA):
    raise RuntimeError("No se pudieron registrar los recursos Qt de LinguaNova")
