def LN_src_utils_config__normalize_engine_code(engine: LN_src_utils_config__Any) -> str:
    """Normalize engine enum/string values to a lowercase config code."""
    # ==============================================================================
    # INICIO: Bloque If de normalize_engine_code — hasattr(engine, 'value')
