# Secuencia del bloque: LN_src_utils_config__ENGINE_BATCH_SIZE_CAPS.get → LN_src_utils_config__normalize_engine_code.
# ==============================================================================
def LN_src_utils_config__get_engine_batch_size_cap(engine: LN_src_utils_config__Any) -> LN_src_utils_config__Optional[int]:
    """Return the hard cap for engines that require a lower effective batch size."""
    return LN_src_utils_config__ENGINE_BATCH_SIZE_CAPS.get(LN_src_utils_config__normalize_engine_code(engine))
