    # ==============================================================================
    @staticmethod
    def _resolve_setting_alias(section: str, setting: str) -> str:
        """Map legacy config keys to the current dataclass field names."""
        # ==============================================================================
        # INICIO: Bloque If de ConfigManager._resolve_setting_alias — section in {'ui', 'app'}
