        # ==============================================================================
        if section in {'ui', 'app'}:
            return LN_src_utils_config__LEGACY_APP_SETTING_ALIASES.get(setting, setting)
        # ==============================================================================
        # FIN: Bloque If de ConfigManager._resolve_setting_alias — section in {'ui', 'app'}
        # ==============================================================================
        return setting
