    # ==============================================================================
    # INICIO: Acción de soporte ConfigManager.get_api_to_renpy_map
    # FUNCIÓN: Get API language code to Ren'Py language code mapping.
    # Implementación directa ConfigManager.get_api_to_renpy_map. Origen trazable: src/utils/config.py.
    # Secuencia del bloque: item['api'].lower → self.get_all_languages.
    # ==============================================================================
    def get_api_to_renpy_map(self) -> LN_src_utils_config__Dict[str, str]:
        """Get API language code to Ren'Py language code mapping."""
        return {item['api'].lower(): item['renpy'] for item in self.get_all_languages()}
    # ==============================================================================
    # FIN: Acción de soporte ConfigManager.get_api_to_renpy_map
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte ConfigManager.normalize_renpy_language_code
    # FUNCIÓN: Normalize language aliases for game-folder and legacy-code tools.
    # Implementación directa ConfigManager.normalize_renpy_language_code. Origen trazable: src/utils/config.py.
    # Secuencia del bloque: str(code or '').strip → value.lower → self.get_api_to_renpy_map → legacy_map.get → item['renpy'].lower → str → resolve → self.get_all_languages.
    # ==============================================================================
    def normalize_renpy_language_code(self, code: LN_src_utils_config__Any) -> str:
        """Normalize language aliases for game-folder and legacy-code tools."""
        value = str(code or '').strip()
        # ==============================================================================
        # INICIO: Bloque If de ConfigManager.normalize_renpy_language_code — not value
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not value. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not value:
            return 'english'
        # ==============================================================================
        # FIN: Bloque If de ConfigManager.normalize_renpy_language_code — not value
        # ==============================================================================
        resolve = LN_src_utils_languages__resolve
        # ==============================================================================
        # INICIO: Bloque Try de ConfigManager.normalize_renpy_language_code — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            return resolve(value).renpy
        except ValueError:
            pass
        # ==============================================================================
        # FIN: Bloque Try de ConfigManager.normalize_renpy_language_code — gestión de excepciones
        # ==============================================================================
        lowered = value.lower()
        renpy_codes = {item['renpy'].lower(): item['renpy'] for item in self.get_all_languages()}
        # ==============================================================================
        # INICIO: Bloque If de ConfigManager.normalize_renpy_language_code — lowered in renpy_codes
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: lowered in renpy_codes. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if lowered in renpy_codes:
            return renpy_codes[lowered]
        # ==============================================================================
        # FIN: Bloque If de ConfigManager.normalize_renpy_language_code — lowered in renpy_codes
        # ==============================================================================
        api_to_renpy = self.get_api_to_renpy_map()
        # ==============================================================================
        # INICIO: Bloque If de ConfigManager.normalize_renpy_language_code — lowered in api_to_renpy
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: lowered in api_to_renpy. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if lowered in api_to_renpy:
            return api_to_renpy[lowered]
        # ==============================================================================
        # FIN: Bloque If de ConfigManager.normalize_renpy_language_code — lowered in api_to_renpy
        # ==============================================================================
        legacy_map = {'tr': 'turkish', 'de': 'german', 'pl': 'polish', 'zh-cn': 'chinese_s', 'zh_tw': 'chinese_t', 'zh-tw': 'chinese_t'}
        return legacy_map.get(lowered, value)
    # ==============================================================================
    # FIN: Acción de soporte ConfigManager.normalize_renpy_language_code
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte ConfigManager._normalize_supported_translation_language
    # FUNCIÓN: Implementación directa ConfigManager._normalize_supported_translation_language. Origen trazable: src/utils/config.py.
    # Secuencia del bloque: resolve → str.
    # ==============================================================================
    def _normalize_supported_translation_language(self, code: LN_src_utils_config__Any) -> str:
        resolve = LN_src_utils_languages__resolve
        return resolve(str(code)).renpy
    # ==============================================================================
    # FIN: Acción de soporte ConfigManager._normalize_supported_translation_language
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte ConfigManager._migrate_portuguese_variant
    # FUNCIÓN: Up to 1.5.0 the Portuguese variant was a DeepL setting; it is a language now.
    #
    # A saved "PT-BR" setting moves the old Portuguese target to the
    # Brazilian Portuguese folder (translator and MOD).
    # Implementación directa ConfigManager._migrate_portuguese_variant. Origen trazable: src/utils/config.py.
    # Secuencia del bloque: str(raw.get('deepl_portuguese_variant', '')).upper → str(ts.target_language).lower → str(ts.mod_target_language).lower → str → raw.get.
    # ==============================================================================
    def _migrate_portuguese_variant(self, raw: LN_src_utils_config__Dict[str, LN_src_utils_config__Any]) -> bool:
        """Up to 1.5.0 the Portuguese variant was a DeepL setting; it is a language now.

        A saved "PT-BR" setting moves the old Portuguese target to the
        Brazilian Portuguese folder (translator and MOD).
        """
        # ==============================================================================
        # INICIO: Bloque If de ConfigManager._migrate_portuguese_variant — str(raw.get('deepl_portuguese_variant', '')).upper() != 'PT-BR'
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: str(raw.get('deepl_portuguese_variant', '')).upper() != 'PT-BR'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if str(raw.get('deepl_portuguese_variant', '')).upper() != 'PT-BR':
            return False
        # ==============================================================================
        # FIN: Bloque If de ConfigManager._migrate_portuguese_variant — str(raw.get('deepl_portuguese_variant', '')).upper() != 'PT-BR'
        # ==============================================================================
        ts = self.translation_settings
        changed = False
        # ==============================================================================
        # INICIO: Bloque If de ConfigManager._migrate_portuguese_variant — str(ts.target_language).lower() in ('portuguese', 'pt')
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: str(ts.target_language).lower() in ('portuguese', 'pt'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if str(ts.target_language).lower() in ('portuguese', 'pt'):
            ts.target_language = 'portuguese_brazil'
            changed = True
        # ==============================================================================
        # FIN: Bloque If de ConfigManager._migrate_portuguese_variant — str(ts.target_language).lower() in ('portuguese', 'pt')
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de ConfigManager._migrate_portuguese_variant — str(ts.mod_target_language).lower() == 'portuguese'
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: str(ts.mod_target_language).lower() == 'portuguese'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if str(ts.mod_target_language).lower() == 'portuguese':
            ts.mod_target_language = 'portuguese_brazil'
            changed = True
        # ==============================================================================
        # FIN: Bloque If de ConfigManager._migrate_portuguese_variant — str(ts.mod_target_language).lower() == 'portuguese'
        # ==============================================================================
        return changed
    # ==============================================================================
    # FIN: Acción de soporte ConfigManager._migrate_portuguese_variant
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte ConfigManager._normalize_loaded_translation_language
    # FUNCIÓN: Keep invalid routing explicit while still loading keys and preferences.
    # Implementación directa ConfigManager._normalize_loaded_translation_language. Origen trazable: src/utils/config.py.
    # Secuencia del bloque: self._normalize_supported_translation_language → self.logger.error → str.
    # ==============================================================================
    def _normalize_loaded_translation_language(self, code: LN_src_utils_config__Any) -> str:
        """Keep invalid routing explicit while still loading keys and preferences.

        A retired variant (Latin American Spanish, European Portuguese) opens
        as Spanish or Brazilian Portuguese instead of an unusable destination.
        """
        code = LN_src_utils_languages__RETIRED_TARGETS.get(str(code or "").strip().lower(), code)
        # ==============================================================================
        # INICIO: Bloque Try de ConfigManager._normalize_loaded_translation_language — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            return self._normalize_supported_translation_language(code)
        except ValueError:
            self.logger.error('Unsupported saved translation language: %r; select a supported destination', code)
            return str(code or '')
        # ==============================================================================
        # FIN: Bloque Try de ConfigManager._normalize_loaded_translation_language — gestión de excepciones
        # ==============================================================================
    # ==============================================================================
    # FIN: Acción de soporte ConfigManager._normalize_loaded_translation_language
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte ConfigManager.save_glossary
    # FUNCIÓN: Save glossary to file.
    # Implementación directa ConfigManager.save_glossary. Origen trazable: src/utils/config.py.
    # Secuencia del bloque: self.logger.info → open → LN_src_utils_config__json.dump → self.logger.error.
    # Interacción con archivos/ejecutables, en orden del código (se respetan las condiciones visibles):
    # Paso 1: open(path, 'w', encoding='utf-8').
    # ==============================================================================
    def save_glossary(self) -> bool:
        """Save the active glossary inside its game, next to its language."""
        if self._glossary_path is None:
            self.logger.warning('Glossary not saved: no game and target language selected')
            return False
        try:
            saved = LN_src_core_project_glossary__save(self._glossary_path, self.glossary, self._glossary_scope[1])
            if saved:
                self.logger.info(f'Glossary saved to {self._glossary_path}')
            return saved
        except Exception as e:
            self.logger.error(f'Error saving glossary: {e}')
            return False
    # ==============================================================================
    # FIN: Acción de soporte ConfigManager.save_glossary
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte ConfigManager.set_glossary_scope
    # FUNCIÓN: Activa el glosario de un juego y un idioma de destino (game/tl/<idioma>/linguanova_glossary.json).
    # ==============================================================================
    def set_glossary_scope(self, project_path: str, language_folder: str) -> bool:
        """Make the glossary of this game and this target language the active one.

        Returns True when the scope changed (the terms were reloaded).
        """
        path = LN_src_core_project_glossary__glossary_path(project_path, language_folder)
        scope = (str(path.parent.parent.parent) if path else '', str(language_folder or '') if path else '')
        if scope == self._glossary_scope and path == self._glossary_path:
            return False
        self._glossary_scope = scope
        self._glossary_path = path
        self.glossary = LN_src_core_project_glossary__load(path)
        return True

    def glossary_scope(self) -> tuple:
        """(game folder, language folder) of the active glossary; empty when none."""
        return self._glossary_scope
    # ==============================================================================
    # FIN: Acción de soporte ConfigManager.set_glossary_scope
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte ConfigManager.set_setting
    # FUNCIÓN: Set a setting value using dot notation (e.g., 'app.app_theme').
    # Implementación directa ConfigManager.set_setting. Origen trazable: src/utils/config.py.
    # Secuencia del bloque: key.split → self._resolve_setting_alias → self._get_section_object → setattr → self._normalize_dataclass_instance → self.save_config → len → self.logger.warning → hasattr → self._normalize_supported_translation_language → self.logger.error.
    # ==============================================================================
    def set_setting(self, key: str, value: LN_src_utils_config__Any) -> None:
        """Set a setting value using dot notation (e.g., 'app.app_theme')."""
