    # ==============================================================================
    # INICIO: Acción de soporte SettingsBackend.set_selected_engine
    # FUNCIÓN: Changes the active translation engine and persists to config.
    # Implementación directa SettingsBackend.set_selected_engine. Origen trazable: src/backend/settings_backend.py.
    # Secuencia del bloque: (engine_str or 'google').lower → self._engine_getter → (self.config.translation_settings.selected_engine or '').lower → self.config.save_config → self._emit.
    # Interacción con archivos/ejecutables, en orden del código (se respetan las condiciones visibles):
    # Paso 1: (self.config.translation_settings.selected_engine or '').lower().
    # ==============================================================================
    def set_selected_engine(self, engine_str: str) -> None:
        """Changes the active translation engine and persists to config."""
        clean_str = (engine_str or 'google').lower()
        new_engine = self._engine_getter(clean_str)
        old_str = (self.config.translation_settings.selected_engine or '').lower()
        self.config.translation_settings.selected_engine = clean_str
        self.config.save_config()
        self._selected_engine = new_engine
        # ==============================================================================
        # INICIO: Bloque If de SettingsBackend.set_selected_engine — clean_str != old_str
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: clean_str != old_str. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if clean_str != old_str:
            self._emit('selected_engine', clean_str)
        # ==============================================================================
        # FIN: Bloque If de SettingsBackend.set_selected_engine — clean_str != old_str
        # ==============================================================================
    # ==============================================================================
    # FIN: Acción de soporte SettingsBackend.set_selected_engine
    # ==============================================================================

