    _VALID_AI_BATCH_FORMATS = ('scene', 'json', 'xml', 'single')

    # ==============================================================================
    # INICIO: Acción de soporte SettingsBackend.get_ai_batch_format
    # FUNCIÓN: Implementación directa SettingsBackend.get_ai_batch_format. Origen trazable: src/backend/settings_backend.py.
    # Secuencia del bloque: getattr.
    # ==============================================================================
    def get_ai_batch_format(self) -> str:
        fmt = getattr(self.config.translation_settings, 'ai_batch_format', 'scene')
        return fmt if fmt in self._VALID_AI_BATCH_FORMATS else 'scene'
    # ==============================================================================
    # FIN: Acción de soporte SettingsBackend.get_ai_batch_format
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte SettingsBackend.set_ai_batch_format
    # FUNCIÓN: Implementación directa SettingsBackend.set_ai_batch_format. Origen trazable: src/backend/settings_backend.py.
    # Secuencia del bloque: str(val or 'scene').strip().lower → self._emit → str(val or 'scene').strip → str.
    # ==============================================================================
    def set_ai_batch_format(self, val: str) -> None:
        fmt = str(val or 'scene').strip().lower()
        # ==============================================================================
        # INICIO: Bloque If de SettingsBackend.set_ai_batch_format — fmt not in self._VALID_AI_BATCH_FORMATS
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: fmt not in self._VALID_AI_BATCH_FORMATS. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if fmt not in self._VALID_AI_BATCH_FORMATS:
            fmt = 'scene'
        # ==============================================================================
        # FIN: Bloque If de SettingsBackend.set_ai_batch_format — fmt not in self._VALID_AI_BATCH_FORMATS
        # ==============================================================================
        self.config.translation_settings.ai_batch_format = fmt
        self._emit('ai_batch_format')
    # ==============================================================================
    # FIN: Acción de soporte SettingsBackend.set_ai_batch_format
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte SettingsBackend.get_ai_scene_batch_size
    # FUNCIÓN: Implementación directa SettingsBackend.get_ai_scene_batch_size. Origen trazable: src/backend/settings_backend.py.
    # Secuencia del bloque: getattr.
    # ==============================================================================
    def get_ai_scene_batch_size(self) -> int:
        return getattr(self.config.translation_settings, 'ai_scene_batch_size', 15)
    # ==============================================================================
    # FIN: Acción de soporte SettingsBackend.get_ai_scene_batch_size
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte SettingsBackend.set_ai_scene_batch_size
    # FUNCIÓN: Implementación directa SettingsBackend.set_ai_scene_batch_size. Origen trazable: src/backend/settings_backend.py.
    # Secuencia del bloque: self._emit → max → min → int.
    # ==============================================================================
    def set_ai_scene_batch_size(self, val: int) -> None:
        # ==============================================================================
        # INICIO: Bloque Try de SettingsBackend.set_ai_scene_batch_size — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            size = max(5, min(int(val), 50))
        except (ValueError, TypeError):
            size = 15
        # ==============================================================================
        # FIN: Bloque Try de SettingsBackend.set_ai_scene_batch_size — gestión de excepciones
        # ==============================================================================
        self.config.translation_settings.ai_scene_batch_size = size
        self._emit('ai_scene_batch_size')
    # ==============================================================================
    # FIN: Acción de soporte SettingsBackend.set_ai_scene_batch_size
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte SettingsBackend.factory_reset
    # FUNCIÓN: Restore the first-launch state.
    #
    # Resets every setting to its default and removes all persisted user
    # data inside the data directory: glossary / critical-terms /
    # never-translate files, per-project translation caches, external TM
    # files, logs and migration markers. The default config is then saved
    # so the next launch starts clean.
    # Implementación directa SettingsBackend.factory_reset. Origen trazable: src/backend/settings_backend.py.
    # Secuencia del bloque: Path → self.config.reset_to_defaults → self.config.save_config → self.logger.info → p.exists → d.is_dir → ensure_data_directories → self.logger.warning → ', '.join → p.unlink → removed.append → shutil.rmtree.
    # Interacción con archivos/ejecutables, en orden del código (se respetan las condiciones visibles):
    # Paso 1: p.unlink().
    # Paso 2: shutil.rmtree(d).
    # ==============================================================================
    def factory_reset(self) -> bool:
        """Restore the first-launch state.

        Resets every setting to its default and removes all persisted user
        data inside the data directory: glossary / critical-terms /
        never-translate files, per-project translation caches, external TM
        files, logs and migration markers. The default config is then saved
        so the next launch starts clean.
        """
        import shutil
        from pathlib import Path
        data_dir = Path(self.config.data_dir)
        removed: List[str] = []
        # ==============================================================================
        # INICIO: Bloque For de SettingsBackend.factory_reset — ('glossary.json', 'critical_terms.json', 'never_translate.json', '.migrated_286')
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: ('glossary.json', 'critical_terms.json', 'never_translate.json', '.migrated_286'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for filename in ('glossary.json', 'critical_terms.json', 'never_translate.json', '.migrated_286'):
            p = data_dir / filename
            # ==============================================================================
            # INICIO: Bloque If de SettingsBackend.factory_reset — p.exists()
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: p.exists(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if p.exists():
                # ==============================================================================
                # INICIO: Bloque Try de SettingsBackend.factory_reset — gestión de excepciones
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                try:
                    p.unlink()
                    removed.append(filename)
                except Exception:
                    self.logger.warning('factory_reset: could not remove %s', p)
                # ==============================================================================
                # FIN: Bloque Try de SettingsBackend.factory_reset — gestión de excepciones
                # ==============================================================================
            # ==============================================================================
            # FIN: Bloque If de SettingsBackend.factory_reset — p.exists()
            # ==============================================================================
        # ==============================================================================
        # FIN: Bloque For de SettingsBackend.factory_reset — ('glossary.json', 'critical_terms.json', 'never_translate.json', '.migrated_286')
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque For de SettingsBackend.factory_reset — ('cache', 'tm', 'logs')
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: ('cache', 'tm', 'logs'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for dirname in ('cache', 'tm', 'logs'):
            d = data_dir / dirname
            # ==============================================================================
            # INICIO: Bloque If de SettingsBackend.factory_reset — d.is_dir()
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: d.is_dir(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if d.is_dir():
                # ==============================================================================
                # INICIO: Bloque Try de SettingsBackend.factory_reset — gestión de excepciones
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                try:
                    shutil.rmtree(d)
                    removed.append(dirname + '/')
                except Exception:
                    self.logger.warning('factory_reset: could not remove %s', d)
                # ==============================================================================
                # FIN: Bloque Try de SettingsBackend.factory_reset — gestión de excepciones
                # ==============================================================================
            # ==============================================================================
            # FIN: Bloque If de SettingsBackend.factory_reset — d.is_dir()
            # ==============================================================================
        # ==============================================================================
        # FIN: Bloque For de SettingsBackend.factory_reset — ('cache', 'tm', 'logs')
        # ==============================================================================
        self.config.reset_to_defaults()
        self.config.glossary = {}
        self.config.critical_terms = []
        self.config.never_translate_rules = {}
        self.config.save_config()
        # ==============================================================================
        # INICIO: Bloque Try de SettingsBackend.factory_reset — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            ensure_data_directories = LN_src_utils_path_manager__ensure_data_directories
            ensure_data_directories(data_dir)
        except Exception:
            self.logger.warning('factory_reset: could not recreate data directories')
        # ==============================================================================
        # FIN: Bloque Try de SettingsBackend.factory_reset — gestión de excepciones
        # ==============================================================================
        self.logger.info('factory_reset complete: removed %s', ', '.join(removed) or 'nothing')
        return True
    # ==============================================================================
    # FIN: Acción de soporte SettingsBackend.factory_reset
    # ==============================================================================

