    # ==============================================================================
    # INICIO: Acción de soporte SettingsBackend.set_ui_language
    # FUNCIÓN: Implementación directa SettingsBackend.set_ui_language. Origen trazable: src/backend/settings_backend.py.
    # Secuencia del bloque: Language → self.config.load_locale → self.config.save_config → self._emit → ValueError → self.logger.warning.
    # ==============================================================================
    def set_ui_language(self, lang_code: str) -> None:
        # ==============================================================================
        # INICIO: Bloque Try de SettingsBackend.set_ui_language — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            Language = LN_src_utils_config__Language
            # ==============================================================================
            # INICIO: Bloque If de SettingsBackend.set_ui_language — lang_code not in {'en', 'es', 'fr', 'pt', 'ru'}
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: lang_code not in {'en', 'es', 'fr', 'pt', 'ru'}. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if lang_code not in {'en', 'es', 'fr', 'pt', 'ru'}:
                raise ValueError(f'Unsupported interface language: {lang_code}')
            # ==============================================================================
            # FIN: Bloque If de SettingsBackend.set_ui_language — lang_code not in {'en', 'es', 'fr', 'pt', 'ru'}
            # ==============================================================================
            lang = Language(lang_code)
            self.config.load_locale(lang)
            self.config.save_config()
            self._emit('language', lang_code)
        except Exception as e:
            self.logger.warning('Error setting UI language: %s', e)
        # ==============================================================================
        # FIN: Bloque Try de SettingsBackend.set_ui_language — gestión de excepciones
        # ==============================================================================
    # ==============================================================================
    # FIN: Acción de soporte SettingsBackend.set_ui_language
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte SettingsBackend.get_target_languages
    # FUNCIÓN: Return target language list as list of {code, name} dicts.
    # Implementación directa SettingsBackend.get_target_languages. Origen trazable: src/backend/settings_backend.py.
    # Secuencia del bloque: self.config.get_target_languages_for_ui → languages.append.
    # ==============================================================================
    def get_target_languages(self) -> list:
        """Return target language list as list of {code, name} dicts."""
        languages = []
        # ==============================================================================
        # INICIO: Bloque For de SettingsBackend.get_target_languages — self.config.get_target_languages_for_ui()
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self.config.get_target_languages_for_ui(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for code, name in self.config.get_target_languages_for_ui():
            languages.append({'code': code, 'name': name})
        # ==============================================================================
        # FIN: Bloque For de SettingsBackend.get_target_languages — self.config.get_target_languages_for_ui()
        # ==============================================================================
        return languages
    # ==============================================================================
    # FIN: Acción de soporte SettingsBackend.get_target_languages
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte SettingsBackend.get_target_language
    # FUNCIÓN: Implementación directa SettingsBackend.get_target_language. Origen trazable: src/backend/settings_backend.py.
    # Secuencia del bloque: evalúa y devuelve los datos definidos en el cuerpo.
    # ==============================================================================
    def get_target_language(self) -> str:
        return self.config.translation_settings.target_language or 'english'
