    # ==============================================================================
    # INICIO: Acción de soporte SettingsBackend.set_target_language
    # FUNCIÓN: Implementación directa SettingsBackend.set_target_language. Origen trazable: src/backend/settings_backend.py.
    # Secuencia del bloque: self.config.normalize_renpy_language_code → self.config.save_config → self.logger.info → self.logger.warning → self.config.get_target_languages_for_ui.
    # ==============================================================================
    def set_target_language(self, lang: str) -> None:
        normalized = self.config.normalize_renpy_language_code(lang)
        supported = {code for code, _name in self.config.get_target_languages_for_ui()}
        # ==============================================================================
        # INICIO: Bloque If de SettingsBackend.set_target_language — normalized not in supported
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: normalized not in supported. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if normalized not in supported:
            self.logger.warning('Ignoring unsupported target language: %s', lang)
            return
        # ==============================================================================
        # FIN: Bloque If de SettingsBackend.set_target_language — normalized not in supported
        # ==============================================================================
        self.config.translation_settings.target_language = normalized
        self.config.save_config()
        self.logger.info('[SettingsBackend] Target language: %s', normalized)
    # ==============================================================================
    # FIN: Acción de soporte SettingsBackend.set_target_language
    # ==============================================================================

