def LN_src_utils_languages__engine_code(value: str, engine: str, *, target: bool=True) -> str:
    """The code ``engine`` expects for a catalogue language.

    Unknown values are returned unchanged so engine clients can still map
    their own documented codes.
    """
    lang = LN_src_utils_languages__find(value)
    key = str(getattr(engine, 'value', engine) or '').lower()
    # ==============================================================================
    # INICIO: Bloque If de engine_code — lang is None
