    # ==============================================================================
    if LN_src_utils_languages__find(raw) is None:
        return {'ZH-CN': 'ZH', 'ZH-TW': 'ZH', 'NO': 'NB', 'KU': 'KMR'}.get(raw.upper(), raw.upper())
    # ==============================================================================
    # FIN: Bloque If de deepl_code — LN_src_utils_languages__find(raw) is None
