    # ==============================================================================
    # INICIO: Acción de soporte RenPyOutputFormatter._is_wrapped_heading
    # FUNCIÓN: v2.8.13: Detect wrapped section headings on single-token strings.
    #
    # A wrapped heading repeats the SAME non-alphanumeric character two or
    # more times at both ends of the text, e.g. "---Drops---" or
    # "===TITLE===". Such strings are menu/section dividers generated by
    # game code, not lines a player reads, so they must never reach the
    # translation engine.
    #
    # Conservative by design:
    # - whitespace disqualifies (em-dash dialogue like "—Wait—" is safe;
    #   in any case em dashes are single repeats and fail the >=2 rule)
    # - alphanumerics, '.', '_', '[', '{' cannot be wrappers (those are
    #   handled by the identifier/markup filters)
    # - the wrapper run must leave real content between both ends
    # Implementación directa RenPyOutputFormatter._is_wrapped_heading. Origen trazable: src/core/output_formatter.py.
    # Secuencia del bloque: reversed → first.isalnum → len.
    # ==============================================================================
    def _is_wrapped_heading(self, text: str) -> bool:
        """
        v2.8.13: Detect wrapped section headings on single-token strings.

        A wrapped heading repeats the SAME non-alphanumeric character two or
        more times at both ends of the text, e.g. "---Drops---" or
        "===TITLE===". Such strings are menu/section dividers generated by
        game code, not lines a player reads, so they must never reach the
        translation engine.

        Conservative by design:
        - whitespace disqualifies (em-dash dialogue like "—Wait—" is safe;
          in any case em dashes are single repeats and fail the >=2 rule)
        - alphanumerics, '.', '_', '[', '{' cannot be wrappers (those are
          handled by the identifier/markup filters)
        - the wrapper run must leave real content between both ends
        """
        # ==============================================================================
        # INICIO: Bloque If de RenPyOutputFormatter._is_wrapped_heading — len(text) < 5 or ' ' in text
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: len(text) < 5 or ' ' in text. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if len(text) < 5 or ' ' in text:
            return False
        # ==============================================================================
        # FIN: Bloque If de RenPyOutputFormatter._is_wrapped_heading — len(text) < 5 or ' ' in text
        # ==============================================================================
        first = text[0]
        # ==============================================================================
        # INICIO: Bloque If de RenPyOutputFormatter._is_wrapped_heading — first.isalnum() or first in '._[{ \t'
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: first.isalnum() or first in '._[{ \t'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if first.isalnum() or first in '._[{ \t':
            return False
        # ==============================================================================
        # FIN: Bloque If de RenPyOutputFormatter._is_wrapped_heading — first.isalnum() or first in '._[{ \t'
        # ==============================================================================
        lead = 0
        # ==============================================================================
        # INICIO: Bloque For de RenPyOutputFormatter._is_wrapped_heading — text
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: text. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for ch in text:
            # ==============================================================================
            # INICIO: Bloque If de RenPyOutputFormatter._is_wrapped_heading — ch != first
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: ch != first. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if ch != first:
                break
            # ==============================================================================
            # FIN: Bloque If de RenPyOutputFormatter._is_wrapped_heading — ch != first
            # ==============================================================================
            lead += 1
        # ==============================================================================
        # FIN: Bloque For de RenPyOutputFormatter._is_wrapped_heading — text
        # ==============================================================================
        tail = 0
        # ==============================================================================
        # INICIO: Bloque For de RenPyOutputFormatter._is_wrapped_heading — reversed(text)
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: reversed(text). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for ch in reversed(text):
            # ==============================================================================
            # INICIO: Bloque If de RenPyOutputFormatter._is_wrapped_heading — ch != first
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: ch != first. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if ch != first:
                break
            # ==============================================================================
            # FIN: Bloque If de RenPyOutputFormatter._is_wrapped_heading — ch != first
            # ==============================================================================
            tail += 1
        # ==============================================================================
        # FIN: Bloque For de RenPyOutputFormatter._is_wrapped_heading — reversed(text)
        # ==============================================================================
        return lead >= 2 and tail >= 2 and (len(text) > lead + tail)
    # ==============================================================================
    # FIN: Acción de soporte RenPyOutputFormatter._is_wrapped_heading
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte RenPyOutputFormatter.escape_renpy_string
    # FUNCIÓN: Escape special characters for Ren'Py strings.
    #
    # Handles:
    # - Backslashes, quotes, newlines, tabs, carriage returns
    # - Protects Ren'Py variables [var], [var!t] and tags {tag}
    # - Protects disambiguation tags {#identifier}
    # - Handles double brackets [[ and {{
    # Implementación directa RenPyOutputFormatter.escape_renpy_string. Origen trazable: src/core/output_formatter.py.
    # Secuencia del bloque: re.compile → variable_pattern.findall → disambiguation_pattern.findall → tag_pattern.findall → temp_text.replace → protection_map.items → tag.startswith.
    # ==============================================================================
    def escape_renpy_string(self, text: str) -> str:
        """Escape special characters for Ren'Py strings.

        Handles:
        - Backslashes, quotes, newlines, tabs, carriage returns
        - Protects Ren'Py variables [var], [var!t] and tags {tag}
        - Protects disambiguation tags {#identifier}
        - Handles double brackets [[ and {{
        """
        # ==============================================================================
        # INICIO: Bloque If de RenPyOutputFormatter.escape_renpy_string — not text
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not text. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not text:
            return text
        # ==============================================================================
        # FIN: Bloque If de RenPyOutputFormatter.escape_renpy_string — not text
        # ==============================================================================
        import re
        variable_pattern = re.compile('\\[[^\\[\\]]+\\]')
        variables = variable_pattern.findall(text)
        disambiguation_pattern = re.compile('\\{#[^}]+\\}')
        disambiguation_tags = disambiguation_pattern.findall(text)
        tag_pattern = re.compile('\\{[^{}]*\\}')
        tags = tag_pattern.findall(text)
        temp_text = text
        protection_map = {}
        counter = 0
        # ==============================================================================
        # INICIO: Bloque For de RenPyOutputFormatter.escape_renpy_string — disambiguation_tags
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: disambiguation_tags. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for dtag in disambiguation_tags:
            placeholder = f'⟦DIS{counter:03d}⟧'
            protection_map[placeholder] = dtag
            temp_text = temp_text.replace(dtag, placeholder, 1)
            counter += 1
        # ==============================================================================
        # FIN: Bloque For de RenPyOutputFormatter.escape_renpy_string — disambiguation_tags
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque For de RenPyOutputFormatter.escape_renpy_string — variables
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: variables. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for var in variables:
            placeholder = f'⟦VAR{counter:03d}⟧'
            protection_map[placeholder] = var
            temp_text = temp_text.replace(var, placeholder, 1)
            counter += 1
        # ==============================================================================
        # FIN: Bloque For de RenPyOutputFormatter.escape_renpy_string — variables
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque For de RenPyOutputFormatter.escape_renpy_string — tags
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: tags. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for tag in tags:
            # ==============================================================================
            # INICIO: Bloque If de RenPyOutputFormatter.escape_renpy_string — tag.startswith('{#')
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: tag.startswith('{#'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if tag.startswith('{#'):
                continue
            # ==============================================================================
            # FIN: Bloque If de RenPyOutputFormatter.escape_renpy_string — tag.startswith('{#')
            # ==============================================================================
            placeholder = f'⟦TAG{counter:03d}⟧'
            protection_map[placeholder] = tag
            temp_text = temp_text.replace(tag, placeholder, 1)
            counter += 1
        # ==============================================================================
        # FIN: Bloque For de RenPyOutputFormatter.escape_renpy_string — tags
        # ==============================================================================
        temp_text = temp_text.replace('\\', '\\\\')
        temp_text = temp_text.replace('"', '\\"')
        temp_text = temp_text.replace('\r', '')
        temp_text = temp_text.replace('\n', '\\n')
        temp_text = temp_text.replace('\t', '\\t')
        # ==============================================================================
        # INICIO: Bloque For de RenPyOutputFormatter.escape_renpy_string — protection_map.items()
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: protection_map.items(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for placeholder, original_content in protection_map.items():
            temp_text = temp_text.replace(placeholder, original_content)
        # ==============================================================================
        # FIN: Bloque For de RenPyOutputFormatter.escape_renpy_string — protection_map.items()
        # ==============================================================================
        return temp_text
    # ==============================================================================
    # FIN: Acción de soporte RenPyOutputFormatter.escape_renpy_string
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte RenPyOutputFormatter.generate_character_translation
    # FUNCIÓN: Generate a character dialogue translation block.
    # Implementación directa RenPyOutputFormatter.generate_character_translation. Origen trazable: src/core/output_formatter.py.
    # Secuencia del bloque: self.escape_renpy_string → LN_src_core_output_formatter__format_renpy_speaker → escaped_original.replace.
    # ==============================================================================
    def generate_character_translation(self, character_name: str, original_text: str, translated_text: str, language_code: str, translation_id: str=None, mode: str='simple') -> str:
        """Generate a character dialogue translation block."""
        escaped_original = self.escape_renpy_string(original_text)
        escaped_translated = self.escape_renpy_string(translated_text)
        fmt_char = LN_src_core_output_formatter__format_renpy_speaker(character_name)
        # ==============================================================================
        # INICIO: Bloque If de RenPyOutputFormatter.generate_character_translation — mode == 'old_new'
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: mode == 'old_new'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if mode == 'old_new':
            block = f'    old {fmt_char} "{escaped_original}"\n    new {fmt_char} "{escaped_translated}"\n\n'
        else:
            comment_original = escaped_original.replace('\n', '\\n')
            block = f'    # {fmt_char} "{comment_original}"\n    {fmt_char} "{escaped_translated}"\n\n'
        # ==============================================================================
        # FIN: Bloque If de RenPyOutputFormatter.generate_character_translation — mode == 'old_new'
        # ==============================================================================
        return block
    # ==============================================================================
    # FIN: Acción de soporte RenPyOutputFormatter.generate_character_translation
