    # ==============================================================================
    # INICIO: Acción de soporte RenPyParser.compute_translation_id
    # FUNCIÓN: Compute Ren'Py-compatible translation ID using MD5 hash.
    #
    # Ren'Py generates translation IDs as: label_<8charhash>
    # For collisions, appends serial: label_<8charhash>m, label_<8charhash>n, etc.
    #
    # v2.8.3: This ensures LinguaNova output matches Ren'Py's internal ID format exactly,
    # enabling proper loading of generated tl/ translation files.
    #
    # Args:
    #     label_context: Current label name (e.g., 'start', 'define_character')
    #     statement_text: Raw statement text (e.g., 'e "Thank you..."')
    #     serial: Collision counter (0 = first, 1 = append 'm', 2 = append 'n', etc.)
    #
    # Returns:
    #     Translation ID string (e.g., 'start_636ae3f5', 'start_bd1ad9e1m')
    # Implementación directa RenPyParser.compute_translation_id. Origen trazable: src/core/parser.py.
    # Secuencia del bloque: LN_src_core_parser__re.sub → f'{label_clean}:{statement_text}'.encode → hashlib.md5 → label_context.strip().lower → hash_obj.hexdigest → chr → label_context.strip → ord.
    # ==============================================================================
    def compute_translation_id(self, label_context: str, statement_text: str, serial: int=0) -> str:
        """
        Compute Ren'Py-compatible translation ID using MD5 hash.

        Ren'Py generates translation IDs as: label_<8charhash>
        For collisions, appends serial: label_<8charhash>m, label_<8charhash>n, etc.

        v2.8.3: This ensures LinguaNova output matches Ren'Py's internal ID format exactly,
        enabling proper loading of generated tl/ translation files.

        Args:
            label_context: Current label name (e.g., 'start', 'define_character')
            statement_text: Raw statement text (e.g., 'e "Thank you..."')
            serial: Collision counter (0 = first, 1 = append 'm', 2 = append 'n', etc.)

        Returns:
            Translation ID string (e.g., 'start_636ae3f5', 'start_bd1ad9e1m')
        """
        import hashlib
        label_clean = label_context.strip().lower() if label_context else 'default'
        label_clean = LN_src_core_parser__re.sub('[^a-z0-9_]', '_', label_clean)
        label_clean = label_clean[:32]
        combined = f'{label_clean}:{statement_text}'.encode('utf-8', errors='replace')
        hash_obj = hashlib.md5(combined)
        hash_hex = hash_obj.hexdigest()[:8]
        trans_id = f'{label_clean}_{hash_hex}'
        # ==============================================================================
        # INICIO: Bloque If de RenPyParser.compute_translation_id — serial > 0
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: serial > 0. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if serial > 0:
            serial_char = chr(ord('m') + serial - 1)
            trans_id += serial_char
        # ==============================================================================
        # FIN: Bloque If de RenPyParser.compute_translation_id — serial > 0
        # ==============================================================================
        return trans_id
    # ==============================================================================
    # FIN: Acción de soporte RenPyParser.compute_translation_id
