    # ==============================================================================
    # INICIO: Acción de soporte RenPyParser.restore_placeholders
    # FUNCIÓN: Restore placeholders in translated text.
    # Uses Unicode bracket markers ⟦0000⟧ which are more resistant to translation corruption.
    # Implementación directa RenPyParser.restore_placeholders. Origen trazable: src/core/parser.py.
    # Secuencia del bloque: placeholder_map.items → restored_text.replace → placeholder_id.startswith → placeholder_id.endswith → re.sub → re.escape.
    # ==============================================================================
    def restore_placeholders(self, translated_text: str, placeholder_map: dict) -> str:
        """
        Restore placeholders in translated text.
        Uses Unicode bracket markers ⟦0000⟧ which are more resistant to translation corruption.
        """
        # ==============================================================================
        # INICIO: Bloque If de RenPyParser.restore_placeholders — not translated_text or not placeholder_map
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not translated_text or not placeholder_map. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not translated_text or not placeholder_map:
            return translated_text
        # ==============================================================================
        # FIN: Bloque If de RenPyParser.restore_placeholders — not translated_text or not placeholder_map
        # ==============================================================================
        restored_text = translated_text
        # ==============================================================================
        # INICIO: Bloque For de RenPyParser.restore_placeholders — placeholder_map.items()
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: placeholder_map.items(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for placeholder_id, original_placeholder in placeholder_map.items():
            restored_text = restored_text.replace(placeholder_id, original_placeholder)
        # ==============================================================================
        # FIN: Bloque For de RenPyParser.restore_placeholders — placeholder_map.items()
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque For de RenPyParser.restore_placeholders — placeholder_map.items()
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: placeholder_map.items(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for placeholder_id, original_placeholder in placeholder_map.items():
            # ==============================================================================
            # INICIO: Bloque If de RenPyParser.restore_placeholders — placeholder_id.startswith('⟦') and placeholder_id.endswith('⟧')
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: placeholder_id.startswith('⟦') and placeholder_id.endswith('⟧'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if placeholder_id.startswith('⟦') and placeholder_id.endswith('⟧'):
                number_part = placeholder_id[1:-1]
                space_patterns = [f'⟦ {number_part} ⟧', f'⟦ {number_part}⟧', f'⟦{number_part} ⟧', f' {placeholder_id} ', f' {placeholder_id}', f'{placeholder_id} ']
                # ==============================================================================
                # INICIO: Bloque For de RenPyParser.restore_placeholders — space_patterns
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: space_patterns. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                for pattern in space_patterns:
                    # ==============================================================================
                    # INICIO: Bloque If de RenPyParser.restore_placeholders — pattern in restored_text
                    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: pattern in restored_text. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                    # ==============================================================================
                    if pattern in restored_text:
                        restored_text = restored_text.replace(pattern, original_placeholder)
                    # ==============================================================================
                    # FIN: Bloque If de RenPyParser.restore_placeholders — pattern in restored_text
                    # ==============================================================================
                # ==============================================================================
                # FIN: Bloque For de RenPyParser.restore_placeholders — space_patterns
                # ==============================================================================
                import re
                unicode_patterns = ['⟦\\s*' + re.escape(number_part) + '\\s*⟧', '\\[\\s*' + re.escape(number_part) + '\\s*\\]', '【\\s*' + re.escape(number_part) + '\\s*】']
                # ==============================================================================
                # INICIO: Bloque For de RenPyParser.restore_placeholders — unicode_patterns
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: unicode_patterns. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                for pattern in unicode_patterns:
                    restored_text = re.sub(pattern, original_placeholder, restored_text)
                # ==============================================================================
                # FIN: Bloque For de RenPyParser.restore_placeholders — unicode_patterns
                # ==============================================================================
            # ==============================================================================
            # FIN: Bloque If de RenPyParser.restore_placeholders — placeholder_id.startswith('⟦') and placeholder_id.endswith('⟧')
            # ==============================================================================
        # ==============================================================================
        # FIN: Bloque For de RenPyParser.restore_placeholders — placeholder_map.items()
        # ==============================================================================
        return restored_text
