    # Secuencia del bloque: placeholder_map.items → self.logger.warning.
    # ==============================================================================
    def validate_placeholders(self, text: str, placeholder_map: dict) -> bool:
        """
        Validate that placeholders in the translated text match the original placeholders.
        Ensures that variables like [player_name] are preserved.

        Args:
            text: The translated text to validate.
            placeholder_map: The original placeholder map from preserve_placeholders.

        Returns:
            True if all placeholders are valid, False otherwise.
        """
        # ==============================================================================
        # INICIO: Bloque For de RenPyParser.validate_placeholders — placeholder_map.items()
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: placeholder_map.items(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for placeholder_id, original_placeholder in placeholder_map.items():
            # ==============================================================================
            # INICIO: Bloque If de RenPyParser.validate_placeholders — placeholder_id not in text
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: placeholder_id not in text. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if placeholder_id not in text:
                self.logger.warning(f'Missing placeholder {placeholder_id} in text: {text}')
                return False
            # ==============================================================================
            # FIN: Bloque If de RenPyParser.validate_placeholders — placeholder_id not in text
            # ==============================================================================
        # ==============================================================================
        # FIN: Bloque For de RenPyParser.validate_placeholders — placeholder_map.items()
        # ==============================================================================
        return True
