    def _extract_multiline_define_default(self, lines: LN_src_core_parser__List[str], file_path: LN_src_core_parser__Union[str, LN_src_core_parser__Path]) -> LN_src_core_parser__List[LN_src_core_parser__Dict[str, LN_src_core_parser__Any]]:
        """
        V2.7.1: Extract translatable strings from multi-line define/default structures.

        Handles:
            define quest_data = {
                "title": "Dragon Slayer",
                "desc": "Kill the mighty dragon",
            }
        """
        entries: List[Dict[str, Any]] = []
        idx = 0
        # ==============================================================================
        # INICIO: Bloque While de RenPyParser._extract_multiline_define_default — idx < len(lines)
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: idx < len(lines). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        while idx < len(lines):
            line = lines[idx]
            info = LN_src_core_parser__MultiLineStructureParser.detect_multiline_start(line)
            # ==============================================================================
            # INICIO: Bloque If de RenPyParser._extract_multiline_define_default — info
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: info. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if info:
                var_name = info['var_name']
                # ==============================================================================
                # INICIO: Bloque If de RenPyParser._extract_multiline_define_default — not self._deep_var_analyzer.is_likely_translatable(var_name, threshold=0.35)
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not self._deep_var_analyzer.is_likely_translatable(var_name, threshold=0.35). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                if not self._deep_var_analyzer.is_likely_translatable(var_name, threshold=0.35):
                    idx += 1
                    continue
                # ==============================================================================
                # FIN: Bloque If de RenPyParser._extract_multiline_define_default — not self._deep_var_analyzer.is_likely_translatable(var_name, threshold=0.35)
                # ==============================================================================
                collected_code, end_idx = LN_src_core_parser__MultiLineStructureParser.collect_block(lines, idx, info)
                # ==============================================================================
                # INICIO: Bloque Try de RenPyParser._extract_multiline_define_default — gestión de excepciones
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                try:
                    results = LN_src_core_parser__MultiLineStructureParser.extract_translatable_values(var_name, collected_code)
                    # ==============================================================================
                    # INICIO: Bloque For de RenPyParser._extract_multiline_define_default — results
                    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: results. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                    # ==============================================================================
                    for r in results:
                        text = r['text']
                        # ==============================================================================
                        # INICIO: Bloque If de RenPyParser._extract_multiline_define_default — text and self.is_meaningful_text(text)
                        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: text and self.is_meaningful_text(text). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                        # ==============================================================================
                        if text and self.is_meaningful_text(text):
                            entries.append({'text': text, 'line_number': idx + 1 + r.get('lineno', 0), 'context_line': line.strip(), 'text_type': LN_src_core_parser__TextType.DEFINE_TEXT, 'context_path': [f'variable:{var_name}', r.get('context', '')], 'is_deep_scan': True, 'is_ast_scan': True, 'file_path': str(file_path)})
                        # ==============================================================================
                        # FIN: Bloque If de RenPyParser._extract_multiline_define_default — text and self.is_meaningful_text(text)
                        # ==============================================================================
                    # ==============================================================================
                    # FIN: Bloque For de RenPyParser._extract_multiline_define_default — results
                    # ==============================================================================
                except Exception as exc:
                    self.logger.debug(f'Multi-line structure parse error at {file_path}:{idx + 1}: {exc}')
                # ==============================================================================
                # FIN: Bloque Try de RenPyParser._extract_multiline_define_default — gestión de excepciones
                # ==============================================================================
                idx = end_idx + 1
            else:
                idx += 1
            # ==============================================================================
            # FIN: Bloque If de RenPyParser._extract_multiline_define_default — info
            # ==============================================================================
        # ==============================================================================
        # FIN: Bloque While de RenPyParser._extract_multiline_define_default — idx < len(lines)
        # ==============================================================================
        return entries
