    # ==============================================================================
    # INICIO: Acción de soporte RenPyParser._is_position_in_python_block
    # FUNCIÓN: Check whether the given line is inside a python block
    # Implementación directa RenPyParser._is_position_in_python_block. Origen trazable: src/core/parser.py.
    # Secuencia del bloque: enumerate → line.strip → stripped.startswith → self._calculate_indent → self.python_block_re.match.
    # ==============================================================================
    def _is_position_in_python_block(self, lines: LN_src_core_parser__List[str], target_line: int) -> bool:
        """Check whether the given line is inside a python block"""
        in_python_block = False
        python_block_indent = 0
        # ==============================================================================
        # INICIO: Bloque For de RenPyParser._is_position_in_python_block — enumerate(lines[:target_line], 1)
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: enumerate(lines[:target_line], 1). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for line_num, line in enumerate(lines[:target_line], 1):
            stripped = line.strip()
            # ==============================================================================
            # INICIO: Bloque If de RenPyParser._is_position_in_python_block — stripped.startswith('#')
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: stripped.startswith('#'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if stripped.startswith('#'):
                continue
            # ==============================================================================
            # FIN: Bloque If de RenPyParser._is_position_in_python_block — stripped.startswith('#')
            # ==============================================================================
            indent = self._calculate_indent(line)
            # ==============================================================================
            # INICIO: Bloque If de RenPyParser._is_position_in_python_block — self.python_block_re.match(stripped)
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self.python_block_re.match(stripped). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if self.python_block_re.match(stripped):
                in_python_block = True
                python_block_indent = indent
                continue
            # ==============================================================================
            # FIN: Bloque If de RenPyParser._is_position_in_python_block — self.python_block_re.match(stripped)
            # ==============================================================================
            # ==============================================================================
            # INICIO: Bloque If de RenPyParser._is_position_in_python_block — in_python_block and indent <= python_block_indent and stripped
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: in_python_block and indent <= python_block_indent and stripped. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if in_python_block and indent <= python_block_indent and stripped:
                # ==============================================================================
                # INICIO: Bloque If de RenPyParser._is_position_in_python_block — not stripped.startswith('#')
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not stripped.startswith('#'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                if not stripped.startswith('#'):
                    in_python_block = False
                # ==============================================================================
                # FIN: Bloque If de RenPyParser._is_position_in_python_block — not stripped.startswith('#')
                # ==============================================================================
            # ==============================================================================
            # FIN: Bloque If de RenPyParser._is_position_in_python_block — in_python_block and indent <= python_block_indent and stripped
            # ==============================================================================
        # ==============================================================================
        # FIN: Bloque For de RenPyParser._is_position_in_python_block — enumerate(lines[:target_line], 1)
        # ==============================================================================
        return in_python_block
