    # INICIO: Acción de soporte RenPyParser._extract_triple_string_content
    # FUNCIÓN: Extract the content of a triple-quoted string
    # Implementación directa RenPyParser._extract_triple_string_content. Origen trazable: src/core/parser.py.
    # Secuencia del bloque: triple_quoted.strip → triple_quoted.startswith → triple_quoted.endswith → triple_quoted[3:-3].strip.
    # ==============================================================================
    def _extract_triple_string_content(self, triple_quoted: str) -> str:
        """Extract the content of a triple-quoted string"""
        # ==============================================================================
        # INICIO: Bloque If de RenPyParser._extract_triple_string_content — not triple_quoted
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not triple_quoted. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not triple_quoted:
            return ''
        # ==============================================================================
        # FIN: Bloque If de RenPyParser._extract_triple_string_content — not triple_quoted
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de RenPyParser._extract_triple_string_content — triple_quoted.startswith('"""') and triple_quoted.endswith('"""')
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: triple_quoted.startswith('"""') and triple_quoted.endswith('"""'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if triple_quoted.startswith('"""') and triple_quoted.endswith('"""'):
            return triple_quoted[3:-3].strip()
        # ==============================================================================
        # INICIO: Bloque If de RenPyParser._extract_triple_string_content — triple_quoted.startswith("'''") and triple_quoted.endswith("'''")
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: triple_quoted.startswith("'''") and triple_quoted.endswith("'''"). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        elif triple_quoted.startswith("'''") and triple_quoted.endswith("'''"):
            return triple_quoted[3:-3].strip()
        # ==============================================================================
        # FIN: Bloque If de RenPyParser._extract_triple_string_content — triple_quoted.startswith("'''") and triple_quoted.endswith("'''")
        # ==============================================================================
        # ==============================================================================
        # FIN: Bloque If de RenPyParser._extract_triple_string_content — triple_quoted.startswith('"""') and triple_quoted.endswith('"""')
        # ==============================================================================
        return triple_quoted.strip()
