    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte RenPyParser._is_untranslatable_character_name
    # FUNCIÓN: Character("Name") display name while translate_character_names is off.
    #
    # The regular extractor honours the setting (off by default), but the
    # deep-scan and AST passes picked the same literal up again, so names
    # like "Rose", "Hope" or "Mark" were translated anyway.
    # Implementación directa RenPyParser._is_untranslatable_character_name. Origen trazable: src/core/parser.py.
    # Secuencia del bloque: getattr → any → (context_line or '').lower → m.group → LN_src_core_parser___CHARACTER_NAME_ARG_RE.finditer.
    # ==============================================================================
    def _is_untranslatable_character_name(self, text: str, context_line: str) -> bool:
        """Character("Name") display name while translate_character_names is off.

        The regular extractor honours the setting (off by default), but the
        deep-scan and AST passes picked the same literal up again, so names
        like "Rose", "Hope" or "Mark" were translated anyway.
        """
        # ==============================================================================
        # INICIO: Bloque If de RenPyParser._is_untranslatable_character_name — not text or 'character' not in (context_line or '').lower()
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not text or 'character' not in (context_line or '').lower(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not text or 'character' not in (context_line or '').lower():
            return False
        # ==============================================================================
        # FIN: Bloque If de RenPyParser._is_untranslatable_character_name — not text or 'character' not in (context_line or '').lower()
        # ==============================================================================
        ts = getattr(self.config, 'translation_settings', None)
        # ==============================================================================
        # INICIO: Bloque If de RenPyParser._is_untranslatable_character_name — ts is not None and getattr(ts, 'translate_character_names', False)
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: ts is not None and getattr(ts, 'translate_character_names', False). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if ts is not None and getattr(ts, 'translate_character_names', False):
            return False
        # ==============================================================================
        # FIN: Bloque If de RenPyParser._is_untranslatable_character_name — ts is not None and getattr(ts, 'translate_character_names', False)
        # ==============================================================================
        return any((m.group('name') == text for m in LN_src_core_parser___CHARACTER_NAME_ARG_RE.finditer(context_line)))
    # ==============================================================================
    # FIN: Acción de soporte RenPyParser._is_untranslatable_character_name
    # ==============================================================================

