    def _create_deep_scan_entry(self, text: str, line_number: int, context_line: str, in_python: bool, file_path: str='', found_key: LN_src_core_parser__Optional[str]=None) -> LN_src_core_parser__Optional[LN_src_core_parser__Dict[str, LN_src_core_parser__Any]]:
        """Build an entry for a deep scan result"""
