        # ==============================================================================
        if found_key:
            context_tag = f'variable:{found_key}'
        # ==============================================================================
        # FIN: Bloque If de RenPyParser._create_deep_scan_entry — found_key
        # ==============================================================================
        return {'text': text, 'line_number': line_number, 'context_line': context_line, 'character': '', 'text_type': text_type, 'context_path': [context_tag], 'processed_text': processed_text, 'placeholder_map': placeholder_map, 'is_deep_scan': True, 'file_path': file_path}
