    # ==============================================================================
    def extract_with_deep_scan(self, file_path: LN_src_core_parser__Union[str, LN_src_core_parser__Path], include_deep_scan: bool=True, include_ast_scan: bool=True) -> LN_src_core_parser__List[LN_src_core_parser__Dict[str, LN_src_core_parser__Any]]:
        """
        Normal extraction + optional deep scan + AST scan.

        Args:
            file_path: File path
            include_deep_scan: include the regex-based deep scan results
            include_ast_scan: include the AST-based deep scan results (v2.4.1)

        Returns:
            Combined entry list
        """
        entries = self.extract_text_entries(file_path)
        seen_texts = {e.get('text', '') for e in entries}
