def LN_src_core_pipeline_validating__is_runtime_hook_enabled(config) -> bool:
    """Single source of truth for whether runtime assets should be generated."""
    ts = getattr(config, 'translation_settings', None)
    # ==============================================================================
    # INICIO: Bloque If de is_runtime_hook_enabled — ts is None
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: ts is None. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if ts is None:
        return False
    # ==============================================================================
    # FIN: Bloque If de is_runtime_hook_enabled — ts is None
    # ==============================================================================
    enable_runtime_hook = bool(getattr(ts, 'enable_runtime_hook', True))
    auto_generate_hook = bool(getattr(ts, 'auto_generate_hook', True))
    force_runtime = bool(getattr(ts, 'force_runtime_translation', False))
    return force_runtime or (enable_runtime_hook and auto_generate_hook)
