def LN_src_core_pipeline_translating__get_guard_reason_text(reason: str, config) -> str:
    reason_key_map = {'separator_remnant': ('guard_reason_separator_remnant', 'separator markers leaked into the output'), 'placeholder_remnant': ('guard_reason_placeholder_remnant', 'placeholder tokens leaked into the output'), 'html_leakage': ('guard_reason_html_leakage', 'HTML markup leaked into the output'), 'length_inflation': ('guard_reason_length_inflation', 'translated text expanded far beyond the source'), 'placeholder_set_mismatch': ('guard_reason_placeholder_set_mismatch', 'placeholder structure changed'), 'renpy_tag_set_mismatch': ('guard_reason_renpy_tag_set_mismatch', "Ren'Py text tags changed"), 'printf_set_mismatch': ('guard_reason_printf_set_mismatch', 'printf-style format specifiers changed'), 'renpy_tag_order_invalid': ('guard_reason_renpy_tag_order_invalid', "Ren'Py text tags were reordered or left unbalanced"), 'replacement_char': ('guard_reason_replacement_char', 'the output contains unreadable characters (U+FFFD)')}
    key, default = reason_key_map.get(reason, ('guard_reason_unknown', (reason or 'suspicious translator output').replace('_', ' ')))
    return config.get_log_text(key, default)
