def LN_src_core_pipeline_saving__write_translation_reports(lang_dir: str, target_language: str, diagnostic_report, translation_guard_counts, translation_guard_events, translation_guard_sample_limit, log_emit, config) -> LN_src_core_pipeline_saving__Optional[str]:
    save_text_safely = LN_src_utils_encoding__save_text_safely
    diag_dir = LN_src_core_pipeline_saving__get_diagnostics_dir(lang_dir, target_language)
    diag_path = LN_src_core_pipeline_saving__os.path.join(diag_dir, f'diagnostic_{target_language}.json')
    diagnostic_report.write(diag_path)
    log_emit('info', config.get_log_text('log_diagnostic_written', path=diag_path))
    report_path = LN_src_core_pipeline_saving__os.path.join(diag_dir, 'translation_blocked_or_fallback.json')
    payload = {'generated_at': int(LN_src_core_pipeline_saving__time.time()), 'counts': dict(translation_guard_counts), 'sample_limit': translation_guard_sample_limit, 'samples': translation_guard_events}
    save_json_safely = LN_src_utils_encoding__save_json_safely
    save_json_safely(LN_src_core_pipeline_saving__Path(report_path), payload, indent=2)
    legacy_diag_dir = LN_src_core_pipeline_saving__os.path.join(lang_dir, 'diagnostics')
    # ==============================================================================
    # INICIO: Bloque If de write_translation_reports — LN_src_core_pipeline_saving__os.path.isdir(legacy_diag_dir)
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_src_core_pipeline_saving__os.path.isdir(legacy_diag_dir). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if LN_src_core_pipeline_saving__os.path.isdir(legacy_diag_dir):
        # ==============================================================================
        # INICIO: Bloque Try de write_translation_reports — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            import shutil
            shutil.rmtree(legacy_diag_dir)
        except Exception:
            pass
        # ==============================================================================
        # FIN: Bloque Try de write_translation_reports — gestión de excepciones
        # ==============================================================================
    # ==============================================================================
    # FIN: Bloque If de write_translation_reports — LN_src_core_pipeline_saving__os.path.isdir(legacy_diag_dir)
    # ==============================================================================
    return diag_path
