# ==============================================================================
# INICIO: Acción de soporte get_translation_stats
# FUNCIÓN: Statistics of what the tl files really contain.
#
# A slot only counts as translated when it holds text that differs from the
# source. Ren'Py's template (and LinguaNova's fallback for failed lines)
# copies the source into the slot; such a line is still shown in the
# original language, so it is reported as ``same_as_source`` instead of
# "translated". Before 2026-10-18 every non-empty slot counted as
# translated, which made a fresh SDK template look 100 % translated.
#
# Keys:
#   total            every slot found in the files
#   translated       slot text differs from the source
#   same_as_source   slot repeats the source (names, "...", untranslated)
#   empty            slot is empty (Ren'Py would show an empty line)
#   untranslated     total - translated (kept for older callers)
#   progress         translated / total * 100
# Implementación directa get_translation_stats. Origen trazable: src/core/tl_parser.py.
# Secuencia del bloque: entry.needs_translation → entry.is_source_copy.
# Interacción con archivos/ejecutables, en orden del código (se respetan las condiciones visibles):
# Paso 1: entry.is_source_copy().
# ==============================================================================
LN_src_core_tl_parser___technical_formatter = LN_src_core_output_formatter__RenPyOutputFormatter()
LN_src_core_tl_parser___RECOVERY_TOKENS = LN_src_core_tl_parser__re.compile(
    LN_src_core_pipeline_constants__PRINTF_SPEC_RE.pattern + '|' + LN_src_core_syntax_guard__PROTECT_RE.pattern)

# INICIO: LN_src_core_tl_parser__is_exempt_entry
# FUNCIÓN: Clasifica fuentes con la política común del parser y del formateador.

def LN_src_core_tl_parser__is_exempt_entry(entry: LN_src_core_tl_parser__TranslationEntry, config=None, marked_texts=()) -> bool:
    """Classify the source; callers count an actually empty slot separately."""
    original = entry.original_text
    if LN_src_core_pipeline_extraction__is_nontranslatable_identifier_entry(entry):
        return True
    if LN_src_core_tl_parser__TLParser.should_skip_text(original):
        return True
    settings = getattr(config, 'translation_settings', None)
    is_name = (entry.entry_type == 'character_name' or
               getattr(entry, 'text_type', '') == 'character_name' or
               'define:character' in (entry.context_path or ()))
    if is_name and not getattr(settings, 'translate_character_names', False):
        return True
    visible = LN_src_core_tl_parser___RECOVERY_TOKENS.sub('', original)
    if not any(char.isalpha() for char in visible):
        return True
    return original not in marked_texts and LN_src_core_tl_parser___technical_formatter._should_skip_translation(original)

# FIN: LN_src_core_tl_parser__is_exempt_entry

# INICIO: LN_src_core_tl_parser__get_translation_stats
# FUNCIÓN: Cuenta el contenido de los archivos y excluye únicamente las copias exentas.

def LN_src_core_tl_parser__get_translation_stats(tl_files: LN_src_core_tl_parser__List[LN_src_core_tl_parser__TranslationFile], config=None, marked_texts=()) -> LN_src_core_tl_parser__Dict:
    """Count saved slots. Empty slots are pending even when the source is technical."""
    total = translated = same = empty = exempt = 0
    for tl_file in tl_files:
        for entry in (*tl_file.entries, *getattr(tl_file, 'filtered_entries', ())):
            total += 1
            if entry.needs_translation():
                empty += 1
            elif not entry.is_source_copy():
                translated += 1
            elif LN_src_core_tl_parser__is_exempt_entry(entry, config, marked_texts):
                exempt += 1
            else:
                same += 1
    translatable = total - exempt
    return {
        'total': total, 'translated': translated, 'same_as_source': same,
        'empty': empty, 'exempt': exempt, 'translatable': translatable,
        'untranslated': empty + same,
        'progress': translated * 100.0 / translatable if translatable else 100.0,
    }

# FIN: LN_src_core_tl_parser__get_translation_stats
