    # ==============================================================================
    def _emit_generation_scan_progress(self, label, current, total, file_path):
        """Report source-scan activity inside the 30..39% GENERATING phase."""
        # ==============================================================================
        # INICIO: Bloque If de TranslationPipeline._emit_generation_scan_progress — total <= 0
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: total <= 0. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if total <= 0:
            return
        # ==============================================================================
        # FIN: Bloque If de TranslationPipeline._emit_generation_scan_progress — total <= 0
        # ==============================================================================
        phase_pct = max(0, min(100, int(current / total * 100)))
        overall_pct = 30 + min(9, int(phase_pct / 100 * 9))
        # ==============================================================================
        # INICIO: Bloque Try de TranslationPipeline._emit_generation_scan_progress — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            file_name = LN_src_core_pipeline_orchestrator__Path(file_path).name
        except Exception:
            file_name = str(file_path)
        # ==============================================================================
        # FIN: Bloque Try de TranslationPipeline._emit_generation_scan_progress — gestión de excepciones
        # ==============================================================================
        self.progress_updated.emit(overall_pct, 100, f'{label}: {file_name}' if file_name else str(label))
        LN_src_core_pipeline_orchestrator___emit_scan(self.log_message.emit, label, current, total, file_path, step=10)
