    # INICIO: TranslationPipeline._completion_stats
    # FUNCIÓN: Resume el contenido del disco y los intentos de la ejecución.

    def _completion_stats(self, tl_files_updated, failed_paths=None, stopped=False, *, lang_dir=None):
        marked_texts = self._get_marked_texts()
        stats = LN_src_core_pipeline_orchestrator__get_translation_stats(tl_files_updated, self.config, marked_texts)
        counts = getattr(self, '_run_counts', {})
        stats.update({key: value for key, value in counts.items() if key != 'stopped'})
        stats['pending'] = stats['same_as_source']
        stats['write_failures'] = len(failed_paths or ())
        stats['syntax_issues'] = len(getattr(self, '_last_syntax_issues', ()))
        stats['stopped'] = bool(stopped or counts.get('stopped') or self.should_stop)
        stats['partial'] = any(stats[key] for key in ('pending', 'empty', 'write_failures', 'syntax_issues', 'stopped'))
        if lang_dir is not None:
            try:
                report = self._write_pending_report(tl_files_updated, lang_dir, marked_texts, stats['stopped'])
            except OSError as exc:
                self.logger.warning('Could not write pending lines report: %s', exc)
            else:
                if report:
                    stats['pending_report'] = report
        return stats

