    # ==============================================================================
    # INICIO: TranslationPipeline._pending_entry_key
    # FUNCIÓN: Identifica un hueco por archivo, línea y fuente.

    @staticmethod
    def _pending_entry_key(entry: LN_src_core_tl_parser__TranslationEntry) -> tuple[str, int, str]:
        path = LN_src_core_pipeline_orchestrator__os.path
        return path.normcase(path.abspath(entry.file_path)), entry.line_number, entry.original_text

