    # INICIO: TranslationPipeline._recover_pending_entries
    # FUNCIÓN: Recupera fallos individuales con el motor elegido y valida las respuestas antes de conservarlas.

    def _recover_pending_entries(self, translations: dict[str, str]) -> None:
        attempts = self._translation_attempts
        if not attempts or self.should_stop or getattr(self, '_stop_reason', None) == 'quota':
            return
        manager = self.translation_manager
        translator = manager.translators.get(self.engine)
        if translator is None:
            return
        recovered = 0
        codes = self.diagnostic_report.stage_provenance['engine_codes']
