                    if guard(translator):
                        return None, 'rate_limited_429'
                    protected, placeholders = protect(text)
                    protected, glossary_tokens = LN_src_core_glossary_manager__GlossaryManager.protect_terms(protected, glossary, xml_mode=xml)
                    placeholders.update(glossary_tokens)
                    req = LN_src_core_pipeline_orchestrator__TranslationRequest(
                        text=protected, source_lang=source, target_lang=target, engine=self.engine,
                        metadata={'original_text': text, 'translation_id': tid, 'file_path': entry.file_path,
                                  'line_number': entry.line_number, 'preprotected': True,
                                  'placeholders': placeholders, 'xml_mode': xml, 'allow_engine_fallback': False})
