    # INICIO: TranslationPipeline._recover_tagged_segments
    # FUNCIÓN: Traduce tramos legibles sin alterar etiquetas, variables o formatos protegidos.

    def _recover_tagged_segments(self, entry, tid: str, request) -> tuple[str | None, dict[str, str], str | None]:
        original = entry.original_text
        # Use the same token matcher as protect_renpy_syntax. Offsets preserve
        # even repeated and nested tokens, with their original spacing.
        tokens = list(LN_src_core_tl_parser___RECOVERY_TOKENS.finditer(original))
        if not tokens:
            return None, {}, None
        output = []
        answers = {}
        end = 0
        for token in [*tokens, None]:
            start = token.start() if token else len(original)
            span = original[end:start]
            text = span.strip()
            if any(char.isalpha() for char in text):
                if text not in answers:
                    translated, reason = request(text, entry, tid)
                    if translated is None and reason != 'unchanged_by_engine':
                        return None, {}, reason
                    answers[text] = translated or text
                left = len(span) - len(span.lstrip())
                right = len(span.rstrip())
                span = span[:left] + answers[text].strip() + span[right:]
            output.append(span)
            if token:
                output.append(token.group())
                end = token.end()
        atomic = {source: target for source, target in answers.items() if source != target}
        if not atomic:
            return None, {}, None
        candidate, blocked = self._sanitize_translation_for_output(
            original=original, translated=''.join(output), file_path=entry.file_path,
            translation_id=tid, line_number=entry.line_number)
        if blocked:
            return None, {}, 'guard_' + blocked
        return candidate, atomic, None

