    # INICIO: Acción de soporte ProxyManager._parse_proxy_string
    # FUNCIÓN: Parse a proxy string (URL or host:port) into ProxyInfo.
    # Implementación directa ProxyManager._parse_proxy_string. Origen trazable: src/core/proxy_manager.py.
    # Secuencia del bloque: entry.strip → LN_src_core_proxy_manager__urlparse → protocol.lower().startswith → LN_src_core_proxy_manager__ProxyInfo → self.logger.debug → entry.rsplit → protocol.lower → host_part.split → host.strip → int → entry.split → port_str.strip.
    # ==============================================================================
    def _parse_proxy_string(self, entry: str) -> LN_src_core_proxy_manager__Optional[LN_src_core_proxy_manager__ProxyInfo]:
        """Parse a proxy string (URL or host:port) into ProxyInfo."""
        entry = entry.strip()
        # ==============================================================================
        # INICIO: Bloque If de ProxyManager._parse_proxy_string — not entry
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not entry. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not entry:
            return None
        # ==============================================================================
        # FIN: Bloque If de ProxyManager._parse_proxy_string — not entry
        # ==============================================================================
        protocol = 'http'
        host = None
        port = None
        auth_url = ''
        # ==============================================================================
        # INICIO: Bloque Try de ProxyManager._parse_proxy_string — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            # ==============================================================================
            # INICIO: Bloque If de ProxyManager._parse_proxy_string — '://' in entry
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: '://' in entry. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if '://' in entry:
                parsed = LN_src_core_proxy_manager__urlparse(entry)
                protocol = parsed.scheme or 'http'
                # ==============================================================================
                # INICIO: Bloque If de ProxyManager._parse_proxy_string — protocol.lower().startswith('socks')
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: protocol.lower().startswith('socks'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                if protocol.lower().startswith('socks'):
                    self.logger.debug(f'Skipping SOCKS proxy (not supported by aiohttp): {entry}')
                    return None
                # ==============================================================================
                # FIN: Bloque If de ProxyManager._parse_proxy_string — protocol.lower().startswith('socks')
                # ==============================================================================
                host = parsed.hostname
                port = parsed.port
                # ==============================================================================
                # INICIO: Bloque If de ProxyManager._parse_proxy_string — parsed.username
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: parsed.username. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                if parsed.username:
                    auth_url = entry
                # ==============================================================================
                # FIN: Bloque If de ProxyManager._parse_proxy_string — parsed.username
                # ==============================================================================
            # ==============================================================================
            # INICIO: Bloque If de ProxyManager._parse_proxy_string — '@' in entry
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: '@' in entry. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            elif '@' in entry:
                user_part, host_part = entry.rsplit('@', 1)
                # ==============================================================================
                # INICIO: Bloque If de ProxyManager._parse_proxy_string — ':' in host_part
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: ':' in host_part. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                if ':' in host_part:
                    host, port_str = host_part.split(':', 1)
                    host = host.strip()
                    port = int(port_str.strip())
                # ==============================================================================
                # FIN: Bloque If de ProxyManager._parse_proxy_string — ':' in host_part
                # ==============================================================================
                auth_url = f'http://{entry}'
            # ==============================================================================
            # INICIO: Bloque If de ProxyManager._parse_proxy_string — ':' in entry
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: ':' in entry. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            elif ':' in entry:
                host, port_str = entry.split(':', 1)
                host = host.strip()
                port = int(port_str.strip())
            # ==============================================================================
            # FIN: Bloque If de ProxyManager._parse_proxy_string — ':' in entry
            # ==============================================================================
            # ==============================================================================
            # FIN: Bloque If de ProxyManager._parse_proxy_string — '@' in entry
            # ==============================================================================
            # ==============================================================================
            # FIN: Bloque If de ProxyManager._parse_proxy_string — '://' in entry
            # ==============================================================================
            # ==============================================================================
            # INICIO: Bloque If de ProxyManager._parse_proxy_string — host and port and (1 <= port <= 65535)
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: host and port and (1 <= port <= 65535). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if host and port and (1 <= port <= 65535):
                return LN_src_core_proxy_manager__ProxyInfo(host=host, port=port, protocol=protocol, _auth_url=auth_url)
            # ==============================================================================
            # FIN: Bloque If de ProxyManager._parse_proxy_string — host and port and (1 <= port <= 65535)
            # ==============================================================================
        except Exception as e:
            self.logger.debug(f"Invalid proxy entry '{entry}': {e}")
        # ==============================================================================
        # FIN: Bloque Try de ProxyManager._parse_proxy_string — gestión de excepciones
        # ==============================================================================
        return None
