        self._modProgress.connect(self._on_mod_progress)
        LN_src_backend_app_backend__threading.Thread(target=self._setup_google_translator, daemon=True).start()
        self._setup_selected_engine_async(self._selected_engine)
        self._tray_icon: LN_src_backend_app_backend__Optional[LN_src_backend_app_backend__QSystemTrayIcon] = None
