    # INICIO: Acción de soporte AppBackend._engine_ready_or_warn
    # FUNCIÓN: DeepL without a key would fail on every line: say so instead of starting.
    # Implementación directa AppBackend._engine_ready_or_warn. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: resolve → self.logMessage.emit → self._t → str.
    # ==============================================================================
    def _engine_ready_or_warn(self) -> bool:
        """DeepL without a key would fail on every line: say so instead of starting."""
        resolve = LN_src_utils_languages__resolve
        # ==============================================================================
        # INICIO: Bloque Try de AppBackend._engine_ready_or_warn — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            resolve(self.config.translation_settings.target_language)
            resolve(self.config.translation_settings.source_language or 'auto', allow_auto=True)
        except ValueError as exc:
            self.logMessage.emit('error', str(exc))
            return False
        # ==============================================================================
        # FIN: Bloque Try de AppBackend._engine_ready_or_warn — gestión de excepciones
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._engine_ready_or_warn — self._selected_engine == LN_src_backend_app_backend__TranslationEngine.DEEPL and (not self.hasDeeplKey)
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self._selected_engine == LN_src_backend_app_backend__TranslationEngine.DEEPL and (not self.hasDeeplKey). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if self._selected_engine == LN_src_backend_app_backend__TranslationEngine.DEEPL and (not self.hasDeeplKey):
            self.logMessage.emit('error', self._t('pending_need_deepl_key', 'Save a DeepL key first (field below).'))
            return False
        # ==============================================================================
        # FIN: Bloque If de AppBackend._engine_ready_or_warn — self._selected_engine == LN_src_backend_app_backend__TranslationEngine.DEEPL and (not self.hasDeeplKey)
        # ==============================================================================
        return True
    # ==============================================================================
    # FIN: Acción de soporte AppBackend._engine_ready_or_warn
    # ==============================================================================

    # ==============================================================================
    # INICIO: ThemedButton "ThemedButton"
    # FUNCIÓN: Implementación directa AppBackend.startAllTranslations. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: LN_src_backend_app_backend__pyqtSlot → self._translation_job_snapshot → BatchReport → self.batchStateChanged.emit → self.startTranslation → self._engine_ready_or_warn → uuid.uuid4 → list → self._submit_work → dict.
    # ==============================================================================
    @LN_src_backend_app_backend__pyqtSlot()
    def startAllTranslations(self):
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.startAllTranslations — not self._project_path
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not self._project_path. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not self._project_path:
            self.startTranslation()
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend.startAllTranslations — not self._project_path
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.startAllTranslations — not self._engine_ready_or_warn()
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not self._engine_ready_or_warn(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not self._engine_ready_or_warn():
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend.startAllTranslations — not self._engine_ready_or_warn()
        # ==============================================================================
        snapshot = self._translation_job_snapshot()
        import uuid
        BatchReport = LN_src_backend_batch_report__BatchReport
        batch_id = uuid.uuid4().hex
        self._batches[batch_id] = BatchReport(list(LN_src_backend_app_backend__TARGET_LANGUAGE_FOLDERS))
        self.batchStateChanged.emit()
        # ==============================================================================
        # INICIO: Bloque For de AppBackend.startAllTranslations — LN_src_backend_app_backend__TARGET_LANGUAGE_FOLDERS
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_src_backend_app_backend__TARGET_LANGUAGE_FOLDERS. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for language in LN_src_backend_app_backend__TARGET_LANGUAGE_FOLDERS:
            self._submit_work('translation', dict(snapshot, target_language=language, batch_id=batch_id))
        # ==============================================================================
        # FIN: Bloque For de AppBackend.startAllTranslations — LN_src_backend_app_backend__TARGET_LANGUAGE_FOLDERS
        # ==============================================================================
    # ==============================================================================
    # FIN: ThemedButton "ThemedButton"
    # ==============================================================================

