    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._record_batch_result
    # FUNCIÓN: Store one language of a five-language batch. Returns True when the
    # finished translation belonged to a batch (so no per-language window).
    # Implementación directa AppBackend._record_batch_result. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: report.add → self.logMessage.emit → self._batches.get → self._t → self._language_display_name → len.
    # ==============================================================================
    def _record_batch_result(self, success: bool, message: str, stats: LN_src_backend_app_backend__Dict[str, LN_src_backend_app_backend__Any], output_path: str) -> bool:
        """Store one language of a five-language batch. Returns True when the
        finished translation belonged to a batch (so no per-language window)."""
        batch_id = self._active_batch_id
        report = self._batches.get(batch_id) if batch_id else None
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._record_batch_result — report is None
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: report is None. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if report is None:
            return False
        # ==============================================================================
        # FIN: Bloque If de AppBackend._record_batch_result — report is None
        # ==============================================================================
        language = self._target_language
        row = report.add(language, success, message, stats, output_path)
        self.logMessage.emit('info', self._t('batch_language_done', '🌐 {language}: {translated}/{total} lines ({coverage}%). Language {done} of {count}.', language=self._language_display_name(language), translated=row.translated, total=row.total, coverage=f'{row.coverage:.1f}', done=len(report.rows), count=len(report.languages)))
        return True
    # ==============================================================================
    # FIN: Acción de soporte AppBackend._record_batch_result
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._finish_batch_if_complete
    # FUNCIÓN: Implementación directa AppBackend._finish_batch_if_complete. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: self._save_batch_report → self.batchStateChanged.emit → self.batchSummaryReady.emit → report.totals → self.send_desktop_notification → self._batches.get → report.to_json → bool → totals.get.
    # ==============================================================================
    def _finish_batch_if_complete(self) -> None:
        batch_id = self._active_batch_id
        report = self._batches.get(batch_id) if batch_id else None
        self._active_batch_id = None
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._finish_batch_if_complete — report is None or not report.done
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: report is None or not report.done. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if report is None or not report.done:
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend._finish_batch_if_complete — report is None or not report.done
        # ==============================================================================
        del self._batches[batch_id]
        report_path = self._save_batch_report(report)
        self.batchStateChanged.emit()
        self.batchSummaryReady.emit(report.to_json(), report_path)
        totals = report.totals()
        self.send_desktop_notification('desktop_notify_complete_title', 'desktop_notify_complete_msg', is_error=bool(totals.get('failed')))
    # ==============================================================================
    # FIN: Acción de soporte AppBackend._finish_batch_if_complete
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._emit_mod_batch_summary
    # FUNCIÓN: M.O.D. "all five languages": the same single table as the translator.
    # Implementación directa AppBackend._emit_mod_batch_summary. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: BatchReport → self._save_batch_report → self.batchSummaryReady.emit → report.add → report.to_json → row.get.
    # ==============================================================================
    def _emit_mod_batch_summary(self, rows) -> None:
        """M.O.D. "all five languages": the same single table as the translator."""
        BatchReport = LN_src_backend_batch_report__BatchReport
        report = BatchReport([row['language'] for row in rows])
        # ==============================================================================
        # INICIO: Bloque For de AppBackend._emit_mod_batch_summary — rows
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: rows. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for row in rows:
            report.add(row['language'], row['success'], row.get('message', ''), {'total': row['total'], 'translated': row['translated'], 'untranslated': row['untranslated'], 'partial': row['partial']}, row.get('output_path', ''))
        # ==============================================================================
        # FIN: Bloque For de AppBackend._emit_mod_batch_summary — rows
        # ==============================================================================
        path = self._save_batch_report(report, self._mod_project_path, 'linguanova_mod_all_languages.txt')
        self.batchSummaryReady.emit(report.to_json(), path)
    # ==============================================================================
    # FIN: Acción de soporte AppBackend._emit_mod_batch_summary
    # ==============================================================================

