    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._save_batch_report
    # FUNCIÓN: Write the same table as a text file in game/tl/.diagnostics.
    # Implementación directa AppBackend._save_batch_report. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: LN_src_backend_app_backend__os.path.join → LN_src_backend_app_backend__os.makedirs → LN_src_backend_app_backend__os.path.isdir → LN_src_backend_app_backend__os.path.dirname → self._language_display_name → self._t → open → handle.write → self.logger.warning → LN_src_backend_app_backend__os.path.basename(project).lower → report.to_text → LN_src_backend_app_backend__os.path.basename.
    # Interacción con archivos/ejecutables, en orden del código (se respetan las condiciones visibles):
    # Paso 1: open(path, 'w', encoding='utf-8', newline='\n').
    # ==============================================================================
    def _save_batch_report(self, report, project: str=None, filename: str='linguanova_all_languages.txt') -> str:
        """Write the same table as a text file in game/tl/.diagnostics."""
        # ==============================================================================
        # INICIO: Bloque Try de AppBackend._save_batch_report — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            project = project or self._project_path
            game_dir = project if LN_src_backend_app_backend__os.path.basename(project).lower() == 'game' else LN_src_backend_app_backend__os.path.join(project, 'game')
            # ==============================================================================
            # INICIO: Bloque If de AppBackend._save_batch_report — not LN_src_backend_app_backend__os.path.isdir(game_dir)
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not LN_src_backend_app_backend__os.path.isdir(game_dir). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if not LN_src_backend_app_backend__os.path.isdir(game_dir):
                return ''
            # ==============================================================================
            # FIN: Bloque If de AppBackend._save_batch_report — not LN_src_backend_app_backend__os.path.isdir(game_dir)
            # ==============================================================================
            path = LN_src_backend_app_backend__os.path.join(game_dir, 'tl', '.diagnostics', filename)
            LN_src_backend_app_backend__os.makedirs(LN_src_backend_app_backend__os.path.dirname(path), exist_ok=True)
            names = {code: self._language_display_name(code) for code in report.languages}
            labels = {'language': self._t('batch_col_language', 'Language'), 'translated': self._t('batch_col_translated', 'Translated'), 'untranslated': self._t('batch_col_untranslated', 'Untranslated'), 'coverage': self._t('batch_col_coverage', 'Coverage'), 'total': self._t('batch_total', 'Total'), 'skipped': self._t('batch_status_skipped', 'skipped (original language)'), 'failed': self._t('batch_status_failed', 'failed'), 'stopped': self._t('batch_status_stopped', 'stopped')}
            # ==============================================================================
            # INICIO: Bloque With de AppBackend._save_batch_report — open(path, 'w', encoding='utf-8', newline='\n')
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: open(path, 'w', encoding='utf-8', newline='\n'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            with open(path, 'w', encoding='utf-8', newline='\n') as handle:
                handle.write(report.to_text(names, labels))
            # ==============================================================================
            # FIN: Bloque With de AppBackend._save_batch_report — open(path, 'w', encoding='utf-8', newline='\n')
            # ==============================================================================
            return path
        except Exception as exc:
            self.logger.warning('Could not write five-language report: %s', exc)
            return ''
        # ==============================================================================
        # FIN: Bloque Try de AppBackend._save_batch_report — gestión de excepciones
        # ==============================================================================
    # ==============================================================================
    # FIN: Acción de soporte AppBackend._save_batch_report
    # ==============================================================================

