    @staticmethod
    def _engine_from_str(engine_str: str) -> LN_src_backend_app_backend__TranslationEngine:
        """Safely converts a string engine name to TranslationEngine enum."""
        mapping = {'google': LN_src_backend_app_backend__TranslationEngine.GOOGLE, 'deepl': LN_src_backend_app_backend__TranslationEngine.DEEPL, 'openai': LN_src_backend_app_backend__TranslationEngine.OPENAI, 'deepseek': LN_src_backend_app_backend__TranslationEngine.OPENAI, 'gemini': LN_src_backend_app_backend__TranslationEngine.GEMINI, 'bing': LN_src_backend_app_backend__TranslationEngine.BING}
        return mapping.get(engine_str.lower(), LN_src_backend_app_backend__TranslationEngine.GOOGLE)
