    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._replace_translator
    # FUNCIÓN: Register *translator*, best-effort closing the instance it replaces.
    # Implementación directa AppBackend._replace_translator. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: manager.translators.get → manager.add_translator → hasattr → asyncio.get_running_loop → running_loop.is_running → running_loop.create_task → asyncio.new_event_loop → previous.close → temp_loop.run_until_complete → temp_loop.close.
    # ==============================================================================
    def _replace_translator(self, engine: LN_src_backend_app_backend__TranslationEngine, translator, manager: LN_src_backend_app_backend__Optional[LN_src_backend_app_backend__TranslationManager]=None) -> None:
        """Register *translator*, best-effort closing the instance it replaces."""
        manager = manager or self.translation_manager
        previous = manager.translators.get(engine)
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._replace_translator — previous is not None and previous is not translator and hasattr(previous, 'close')
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: previous is not None and previous is not translator and hasattr(previous, 'close'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if previous is not None and previous is not translator and hasattr(previous, 'close'):
            # ==============================================================================
            # INICIO: Bloque Try de AppBackend._replace_translator — gestión de excepciones
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            try:
                import asyncio
                # ==============================================================================
                # INICIO: Bloque Try de AppBackend._replace_translator — gestión de excepciones
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                try:
                    running_loop = asyncio.get_running_loop()
                except RuntimeError:
                    running_loop = None
                # ==============================================================================
                # FIN: Bloque Try de AppBackend._replace_translator — gestión de excepciones
                # ==============================================================================
                # ==============================================================================
                # INICIO: Bloque If de AppBackend._replace_translator — running_loop is not None and running_loop.is_running()
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: running_loop is not None and running_loop.is_running(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                if running_loop is not None and running_loop.is_running():
                    running_loop.create_task(previous.close())
                else:
                    temp_loop = asyncio.new_event_loop()
                    # ==============================================================================
                    # INICIO: Bloque Try de AppBackend._replace_translator — gestión de excepciones
                    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                    # ==============================================================================
                    try:
                        temp_loop.run_until_complete(previous.close())
                    finally:
                        temp_loop.close()
                    # ==============================================================================
                    # FIN: Bloque Try de AppBackend._replace_translator — gestión de excepciones
                    # ==============================================================================
                # ==============================================================================
                # FIN: Bloque If de AppBackend._replace_translator — running_loop is not None and running_loop.is_running()
                # ==============================================================================
            except Exception:
                pass
            # ==============================================================================
            # FIN: Bloque Try de AppBackend._replace_translator — gestión de excepciones
