    # ==============================================================================
    # INICIO: ComboBox "engineComboBox" [id: engineComboBox]
    # FUNCIÓN: Changes the active translation engine and sets it up if needed.
    # Implementación directa AppBackend.setSelectedEngine. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: LN_src_backend_app_backend__pyqtSlot → (engine_str or 'google').lower → self._engine_from_str → self.settings.set_selected_engine → self._setup_selected_engine_async → self.logMessage.emit → self._t.
    # Interacción con archivos/ejecutables, en orden del código (se respetan las condiciones visibles):
    # Paso 1: self.settings.set_selected_engine(clean_str).
    # Paso 2: self._setup_selected_engine_async(new_engine).
    # ==============================================================================
    @LN_src_backend_app_backend__pyqtSlot(str)
    def setSelectedEngine(self, engine_str: str) -> None:
        """Changes the active translation engine and sets it up if needed."""
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.setSelectedEngine — self._is_translating
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self._is_translating. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if self._is_translating:
            self.logMessage.emit('warning', self._t('log_translation_controls_locked', 'Translation is running. Project, language and engine controls are locked until it finishes or is stopped.'))
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend.setSelectedEngine — self._is_translating
        # ==============================================================================
        clean_str = (engine_str or 'google').lower()
        new_engine = self._engine_from_str(clean_str)
        self.settings.set_selected_engine(clean_str)
        self._selected_engine = new_engine
        self._setup_selected_engine_async(new_engine)
    # ==============================================================================
    # FIN: ComboBox "engineComboBox" [id: engineComboBox]
    # ==============================================================================

