    # Secuencia del bloque: LN_src_backend_app_backend__pyqtSlot → LN_src_backend_app_backend___normalize_path → bool → LN_src_backend_app_backend__QDesktopServices.openUrl → LN_src_backend_app_backend__QUrl.fromLocalFile.
    # Interacción con archivos/ejecutables, en orden del código (se respetan las condiciones visibles):
    # Paso 1: LN_src_backend_app_backend__QDesktopServices.openUrl(LN_src_backend_app_backend__QUrl.fromLocalFile(local)).
    # ==============================================================================
    @LN_src_backend_app_backend__pyqtSlot(str, result=bool)
    def openLocalPath(self, path: str) -> bool:
        """Open a local file or folder with the desktop shell."""
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.openLocalPath — not path
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not path. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not path:
            return False
        # ==============================================================================
        # FIN: Bloque If de AppBackend.openLocalPath — not path
        # ==============================================================================
        local = LN_src_backend_app_backend___normalize_path(path)
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.openLocalPath — not local
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not local. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not local:
            return False
        # ==============================================================================
        # FIN: Bloque If de AppBackend.openLocalPath — not local
        # ==============================================================================
        return bool(LN_src_backend_app_backend__QDesktopServices.openUrl(LN_src_backend_app_backend__QUrl.fromLocalFile(local)))
    # ==============================================================================
    # FIN: Button "Abrir carpeta de salida" [id: openFolderBtn] / ThemedButton "ThemedButton"
