    # ==============================================================================
    @LN_src_backend_app_backend__pyqtSlot(str, result=str)
    def get_asset_url(self, relative_path: str) -> str:
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.get_asset_url — relative_path.replace('\\', '/') in LN_RESOURCE_MAP
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: relative_path.replace('\\', '/') in LN_RESOURCE_MAP. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if relative_path.replace('\\', '/') in LN_RESOURCE_MAP:
            return 'qrc:/linguanova/' + relative_path.replace('\\', '/')
        # ==============================================================================
        # FIN: Bloque If de AppBackend.get_asset_url — relative_path.replace('\\', '/') in LN_RESOURCE_MAP
