    # ==============================================================================
    # INICIO: Button "Borrar memoria de traducción"
    # FUNCIÓN: Clear the local and global translation memories (cache) of the selected project.
    # Implementación directa AppBackend.clearTranslationCache. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: LN_src_backend_app_backend__pyqtSlot → self.logMessage.emit → self.translation_manager._cache.clear → LN_src_backend_app_backend__os.path.isfile → get_project_id → LN_src_backend_app_backend__os.path.join → LN_src_backend_app_backend__os.path.exists → self._t → LN_src_backend_app_backend__os.path.dirname → getattr → self.logger.exception → shutil.rmtree → LN_src_backend_app_backend__os.remove → LN_src_backend_app_backend__os.path.basename.
    # Interacción con archivos/ejecutables, en orden del código (se respetan las condiciones visibles):
    # Paso 1: shutil.rmtree(global_project_cache).
    # ==============================================================================
    @LN_src_backend_app_backend__pyqtSlot(result=bool)
    def clearTranslationCache(self) -> bool:
        """Clear the local and global translation memories (cache) of the selected project."""
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.clearTranslationCache — not self._project_path
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not self._project_path. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not self._project_path:
            self.logMessage.emit('warning', self._t('cache_no_project', 'No project selected to clear cache.'))
            return False
        # ==============================================================================
        # FIN: Bloque If de AppBackend.clearTranslationCache — not self._project_path
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque Try de AppBackend.clearTranslationCache — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            self.translation_manager._cache.clear()
            self.translation_manager.cache_hits = 0
            self.translation_manager.cache_misses = 0
            # ==============================================================================
            # INICIO: Bloque If de AppBackend.clearTranslationCache — LN_src_backend_app_backend__os.path.isfile(self._project_path)
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_src_backend_app_backend__os.path.isfile(self._project_path). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if LN_src_backend_app_backend__os.path.isfile(self._project_path):
                project_dir = LN_src_backend_app_backend__os.path.dirname(self._project_path)
                exe_path = self._project_path
            else:
                project_dir = self._project_path
                exe_path = None
            # ==============================================================================
            # FIN: Bloque If de AppBackend.clearTranslationCache — LN_src_backend_app_backend__os.path.isfile(self._project_path)
            # ==============================================================================
            get_project_id = LN_src_utils_path_manager__get_project_id
            project_name = get_project_id(project_dir, exe_path)
            # ==============================================================================
            # INICIO: Bloque If de AppBackend.clearTranslationCache — self._target_language
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self._target_language. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if self._target_language:
                local_cache = LN_src_backend_app_backend__os.path.join(self._project_path, 'game', 'tl', self._target_language, 'translation_cache.json')
                # ==============================================================================
                # INICIO: Bloque If de AppBackend.clearTranslationCache — LN_src_backend_app_backend__os.path.exists(local_cache)
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_src_backend_app_backend__os.path.exists(local_cache). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                if LN_src_backend_app_backend__os.path.exists(local_cache):
                    # ==============================================================================
                    # INICIO: Bloque Try de AppBackend.clearTranslationCache — gestión de excepciones
                    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                    # ==============================================================================
                    try:
                        LN_src_backend_app_backend__os.remove(local_cache)
                        self.logMessage.emit('info', f'Local project cache removed: {LN_src_backend_app_backend__os.path.basename(local_cache)}')
                    except Exception as ex:
                        self.logMessage.emit('warning', f'Could not remove local cache: {ex}')
                    # ==============================================================================
                    # FIN: Bloque Try de AppBackend.clearTranslationCache — gestión de excepciones
                    # ==============================================================================
                # ==============================================================================
                # FIN: Bloque If de AppBackend.clearTranslationCache — LN_src_backend_app_backend__os.path.exists(local_cache)
                # ==============================================================================
            # ==============================================================================
            # FIN: Bloque If de AppBackend.clearTranslationCache — self._target_language
            # ==============================================================================
            base_cache_dir = LN_src_backend_app_backend__os.path.join(self.config.data_dir, getattr(self.config.translation_settings, 'cache_path', 'cache'))
            global_project_cache = LN_src_backend_app_backend__os.path.join(base_cache_dir, project_name)
            # ==============================================================================
            # INICIO: Bloque If de AppBackend.clearTranslationCache — LN_src_backend_app_backend__os.path.exists(global_project_cache)
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_src_backend_app_backend__os.path.exists(global_project_cache). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if LN_src_backend_app_backend__os.path.exists(global_project_cache):
                import shutil
                # ==============================================================================
                # INICIO: Bloque Try de AppBackend.clearTranslationCache — gestión de excepciones
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                try:
                    shutil.rmtree(global_project_cache)
                    self.logMessage.emit('info', f"Global cache for project '{project_name}' removed.")
                except Exception as ex:
                    self.logMessage.emit('warning', f'Could not remove global cache folder: {ex}')
                # ==============================================================================
                # FIN: Bloque Try de AppBackend.clearTranslationCache — gestión de excepciones
                # ==============================================================================
            # ==============================================================================
            # FIN: Bloque If de AppBackend.clearTranslationCache — LN_src_backend_app_backend__os.path.exists(global_project_cache)
            # ==============================================================================
            self.logMessage.emit('info', self._t('log_cache_cleared', 'Translation memory (cache) cleared successfully.'))
            return True
        except Exception as e:
            self.logger.exception('Failed to clear translation cache')
            self.logMessage.emit('error', f'Failed to clear cache: {e}')
            return False
        # ==============================================================================
        # FIN: Bloque Try de AppBackend.clearTranslationCache — gestión de excepciones
        # ==============================================================================
    # ==============================================================================
    # FIN: Button "Borrar memoria de traducción"
    # ==============================================================================

