    # FUNCIÓN: Implementación directa AppBackend.getTextWithDefault. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: LN_src_backend_app_backend__pyqtSlot → self.config.get_ui_text.
    # ==============================================================================
    @LN_src_backend_app_backend__pyqtSlot(str, str, result=str)
    def getTextWithDefault(self, key: str, default: str) -> str:
        return self.config.get_ui_text(key, default)
