    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._get_log_translation_patterns
    # FUNCIÓN: Implementación directa AppBackend._get_log_translation_patterns. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: self._localized_log_patterns.get → self.config.get_ui_translations → locales.get → english.items → patterns.sort → translated.get → patterns.append → list → enumerate → isinstance → LN_src_backend_app_backend__string.Formatter().parse → parts.append → LN_src_backend_app_backend__re.compile → tuple → len → LN_src_backend_app_backend__re.escape → fields.append → ''.join → LN_src_backend_app_backend__string.Formatter.
    # ==============================================================================
    def _get_log_translation_patterns(self, language: str) -> list[tuple[LN_src_backend_app_backend__re.Pattern[str], str, tuple[tuple[str, str], ...]]]:
        cached = self._localized_log_patterns.get(language)
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._get_log_translation_patterns — cached is not None
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: cached is not None. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if cached is not None:
            return cached
        # ==============================================================================
        # FIN: Bloque If de AppBackend._get_log_translation_patterns — cached is not None
        # ==============================================================================
        locales = self.config.get_ui_translations()
        english = locales.get('en', {})
        translated = locales.get(language, {})
        patterns = []
        # ==============================================================================
        # INICIO: Bloque For de AppBackend._get_log_translation_patterns — english.items()
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: english.items(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for key, source in english.items():
            target = translated.get(key)
            # ==============================================================================
            # INICIO: Bloque If de AppBackend._get_log_translation_patterns — not isinstance(source, str) or not isinstance(target, str) or target == source
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not isinstance(source, str) or not isinstance(target, str) or target == source. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if not isinstance(source, str) or not isinstance(target, str) or target == source:
                continue
            # ==============================================================================
            # FIN: Bloque If de AppBackend._get_log_translation_patterns — not isinstance(source, str) or not isinstance(target, str) or target == source
            # ==============================================================================
            parts = []
            fields = []
            # ==============================================================================
            # INICIO: Bloque Try de AppBackend._get_log_translation_patterns — gestión de excepciones
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            try:
                segments = list(LN_src_backend_app_backend__string.Formatter().parse(source))
                # ==============================================================================
                # INICIO: Bloque For de AppBackend._get_log_translation_patterns — enumerate(segments)
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: enumerate(segments). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                for index, (literal, field_name, _format_spec, _conversion) in enumerate(segments):
                    parts.append(LN_src_backend_app_backend__re.escape(literal))
                    # ==============================================================================
                    # INICIO: Bloque If de AppBackend._get_log_translation_patterns — field_name is not None
                    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: field_name is not None. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                    # ==============================================================================
                    if field_name is not None:
                        group = f'value{len(fields)}'
                        quantifier = '.*' if index == len(segments) - 1 else '.*?'
                        parts.append(f'(?P<{group}>{quantifier})')
                        fields.append((field_name, group))
                    # ==============================================================================
                    # FIN: Bloque If de AppBackend._get_log_translation_patterns — field_name is not None
                    # ==============================================================================
                # ==============================================================================
                # FIN: Bloque For de AppBackend._get_log_translation_patterns — enumerate(segments)
                # ==============================================================================
            except ValueError:
                continue
            # ==============================================================================
            # FIN: Bloque Try de AppBackend._get_log_translation_patterns — gestión de excepciones
            # ==============================================================================
            patterns.append((LN_src_backend_app_backend__re.compile(''.join(parts)), target, tuple(fields)))
        # ==============================================================================
        # FIN: Bloque For de AppBackend._get_log_translation_patterns — english.items()
        # ==============================================================================
        patterns.sort(key=lambda item: len(item[0].pattern), reverse=True)
        self._localized_log_patterns[language] = patterns
        return patterns
    # ==============================================================================
    # FIN: Acción de soporte AppBackend._get_log_translation_patterns
    # ==============================================================================

    # ==============================================================================
    # INICIO: Connections "Connections"
    # FUNCIÓN: Localize catalog-backed text embedded in backend log messages.
    # Implementación directa AppBackend.localizeLogMessage. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: LN_src_backend_app_backend__pyqtSlot → self._get_log_translation_patterns → pattern.search → localized.replace → match.group → match.end → match.start.
    # ==============================================================================
    @LN_src_backend_app_backend__pyqtSlot(str, result=str)
    def localizeLogMessage(self, message: str) -> str:
        """Localize catalog-backed text embedded in backend log messages."""
        language = self.config.app_settings.ui_language or 'en'
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.localizeLogMessage — language == 'en'
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: language == 'en'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if language == 'en':
            return message
        # ==============================================================================
        # FIN: Bloque If de AppBackend.localizeLogMessage — language == 'en'
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque For de AppBackend.localizeLogMessage — self._get_log_translation_patterns(language)
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self._get_log_translation_patterns(language). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for pattern, translated, fields in self._get_log_translation_patterns(language):
            match = pattern.search(message)
            # ==============================================================================
            # INICIO: Bloque If de AppBackend.localizeLogMessage — match is None
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: match is None. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if match is None:
                continue
            # ==============================================================================
            # FIN: Bloque If de AppBackend.localizeLogMessage — match is None
            # ==============================================================================
            localized = translated
            # ==============================================================================
            # INICIO: Bloque For de AppBackend.localizeLogMessage — fields
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: fields. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            for field_name, group in fields:
                localized = localized.replace('{' + field_name + '}', match.group(group), 1)
            # ==============================================================================
            # FIN: Bloque For de AppBackend.localizeLogMessage — fields
            # ==============================================================================
            return message[:match.start()] + localized + message[match.end():]
        # ==============================================================================
        # FIN: Bloque For de AppBackend.localizeLogMessage — self._get_log_translation_patterns(language)
        # ==============================================================================
        return message
    # ==============================================================================
    # FIN: Connections "Connections"
    # ==============================================================================

