    # ==============================================================================
    # INICIO: Button "Crear idioma" [id: btnCreateUiLang]
    # FUNCIÓN: Machine-translate en.json into ``renpy_code`` as a user language.
    # Implementación directa AppBackend.createUiLanguage. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: LN_src_backend_app_backend__pyqtSlot → next → str(item.get('api') or '').strip → self._t → self.uiLanguageGenerationFinished.emit → getattr → lang['code'].lower → self._t('ui_lang_builtin', "{lang} is already one of LinguaNova's interface languages.").replace → self.settings.builtin_ui_languages → str → api.lower → api.split('-')[0].lower → self.config.get_all_languages → item.get → x.get → api.split.
    # ==============================================================================
    @LN_src_backend_app_backend__pyqtSlot(str)
    def createUiLanguage(self, renpy_code: str) -> None:
        """Machine-translate en.json into ``renpy_code`` as a user language."""
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.createUiLanguage — self._is_translating or self._mod_running or getattr(self, '_ui_lang_generating', False)
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self._is_translating or self._mod_running or getattr(self, '_ui_lang_generating', False). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if self._is_translating or self._mod_running or getattr(self, '_ui_lang_generating', False):
            msg = self._t('ui_lang_busy', 'Wait until the current task finishes.')
            self.uiLanguageGenerationFinished.emit(False, msg)
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend.createUiLanguage — self._is_translating or self._mod_running or getattr(self, '_ui_lang_generating', False)
        # ==============================================================================
        item = next((x for x in self.config.get_all_languages() if x.get('renpy') == renpy_code), None)
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.createUiLanguage — item is None
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: item is None. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if item is None:
            self.uiLanguageGenerationFinished.emit(False, self._t('ui_lang_unknown', 'Unknown language.'))
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend.createUiLanguage — item is None
        # ==============================================================================
        builtin = {lang['code'].lower() for lang in self.settings.builtin_ui_languages()}
        api = str(item.get('api') or '').strip()
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.createUiLanguage — api.lower() in builtin or api.split('-')[0].lower() in {'en'}
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: api.lower() in builtin or api.split('-')[0].lower() in {'en'}. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if api.lower() in builtin or api.split('-')[0].lower() in {'en'}:
            msg = self._t('ui_lang_builtin', "{lang} is already one of LinguaNova's interface languages.").replace('{lang}', item.get('native') or api)
            self.uiLanguageGenerationFinished.emit(False, msg)
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend.createUiLanguage — api.lower() in builtin or api.split('-')[0].lower() in {'en'}
        # ==============================================================================
        msg = self._t('ui_lang_limited', 'This build supports only English, Spanish, French, Portuguese and Russian as interface languages.')
        self.uiLanguageGenerationFinished.emit(False, msg)
        return
    # ==============================================================================
    # FIN: Button "Crear idioma" [id: btnCreateUiLang]
    # ==============================================================================

