        # ==============================================================================
        if not path:
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend.setProjectPath — not path
        # ==============================================================================
        unwrap_mac_app = LN_src_utils_path_manager__unwrap_mac_app
        app_root = unwrap_mac_app(path)
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.setProjectPath — app_root != path
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: app_root != path. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if app_root != path:
            path = app_root
            self.logMessage.emit('info', self._t('log_mac_app_bundle', '🍎 macOS app package detected — using {path}').format(path=path))
        # ==============================================================================
        # FIN: Bloque If de AppBackend.setProjectPath — app_root != path
        # ==============================================================================
        self._project_path = path
        self.projectChanged.emit(path)
        self._follow_main_project(path)
