        self._tl_source_path = ''
        self.logMessage.emit('info', f'📁 Project path: {path}')
        norm = LN_src_backend_app_backend__os.path.normpath(path)
        path_parts = norm.replace('\\', '/').split('/')
        is_tl_folder = LN_src_backend_app_backend__os.path.basename(norm).lower() == 'tl' or (len(path_parts) >= 2 and path_parts[-2].lower() == 'tl') or (LN_src_backend_app_backend__os.path.isdir(path) and any((f.lower().endswith('.rpy') for _, _, fs in LN_src_backend_app_backend__os.walk(path) for f in fs)) and (not LN_src_backend_app_backend__os.path.isdir(LN_src_backend_app_backend__os.path.join(path, 'game'))) and ('tl' in norm.lower().replace('\\', '/').split('/')))
