        # ==============================================================================
        if is_tl_folder and LN_src_backend_app_backend__os.path.isdir(path):
            self._tl_mode = True
            self._tl_source_path = path
            self.logMessage.emit('info', self._t('log_tl_folder_detected', '🔄 TL folder detected — Retranslation mode active. Only empty translations will be filled, existing translations will be preserved.'))
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend.setProjectPath — is_tl_folder and LN_src_backend_app_backend__os.path.isdir(path)
        # ==============================================================================
