    # INICIO: FileDialog "Seleccionar el archivo del juego Ren'Py" [id: modGameFileDialog] / FolderDialog "Seleccionar la carpeta del juego Ren'Py" [id: modGameFolderDialog]
    # FUNCIÓN: Select the game on the MOD page; it becomes the game of the whole app.
    #
    # One game for every page: choosing it here also selects it for
    # Translation (unless a translation is running), and choosing it there
    # selects it here (``_follow_main_project``).
    # Implementación directa AppBackend.setModProjectPath. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: LN_src_backend_app_backend__pyqtSlot → LN_src_backend_app_backend___normalize_path → self.modProjectPathChanged.emit → self.modTranslationsChanged.emit → self._t → self.modStatusChanged.emit → self.logMessage.emit → unwrap_mac_app → resolve_game_dir → self.setProjectPath.
    # ==============================================================================
    @LN_src_backend_app_backend__pyqtSlot(str, result=bool)
    def setModProjectPath(self, path: str) -> bool:
        """Select the game on the MOD page; it becomes the game of the whole app.

        One game for every page: choosing it here also selects it for
        Translation (unless a translation is running), and choosing it there
        selects it here (``_follow_main_project``).
        """
        path = LN_src_backend_app_backend___normalize_path(path)
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.setModProjectPath — not path
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not path. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not path:
            return False
        # ==============================================================================
        # FIN: Bloque If de AppBackend.setModProjectPath — not path
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque Try de AppBackend.setModProjectPath — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            unwrap_mac_app = LN_src_utils_path_manager__unwrap_mac_app
            resolve_game_dir = LN_src_ui_mod_scanner__resolve_game_dir
            normalized = unwrap_mac_app(path)
            resolve_game_dir(normalized)
        except Exception:
            self._mod_status = self._t('mod_status_invalid_game', "The selected location does not contain a valid Ren'Py game folder.")
            self.modStatusChanged.emit()
            self.logMessage.emit('error', self._mod_status)
            return False
        # ==============================================================================
        # FIN: Bloque Try de AppBackend.setModProjectPath — gestión de excepciones
        # ==============================================================================
        self._mod_project_path = normalized
        self.modProjectPathChanged.emit()
        self.modTranslationsChanged.emit()
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.setModProjectPath — not self._is_translating and LN_src_backend_app_backend___normalize_path(self._project_path or '') != normalized
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not self._is_translating and LN_src_backend_app_backend___normalize_path(self._project_path or '') != normalized. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not self._is_translating and LN_src_backend_app_backend___normalize_path(self._project_path or '') != normalized:
            self.setProjectPath(normalized)
        # ==============================================================================
        # FIN: Bloque If de AppBackend.setModProjectPath — not self._is_translating and LN_src_backend_app_backend___normalize_path(self._project_path or '') != normalized
        # ==============================================================================
        self._mod_status = self._t('mod_status_game_selected', 'Game selected. The route is temporary and will be cleared when LinguaNova closes.')
        self.modStatusChanged.emit()
        self.logMessage.emit('info', self._mod_status)
        return True
