    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._submit_work
    # FUNCIÓN: Submit work without ever stopping the active operation.
    # Implementación directa AppBackend._submit_work. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: self._work_queue.submit → self.workQueueChanged.emit → self.logMessage.emit → self._dispatch_work_item → self._t.
    # ==============================================================================
    def _submit_work(self, kind: str, payload: LN_src_backend_app_backend__Dict[str, LN_src_backend_app_backend__Any]) -> None:
        """Submit work without ever stopping the active operation."""
        item, start_now = self._work_queue.submit(kind, payload)
        self.workQueueChanged.emit()
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._submit_work — start_now
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: start_now. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if start_now:
            self._dispatch_work_item(item)
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend._submit_work — start_now
        # ==============================================================================
        self.logMessage.emit('info', self._t('log_work_queued', '📥 Request queued as #{sequence}. Pending jobs: {count}.', sequence=item.sequence, count=self._work_queue.pending_count))
    # ==============================================================================
    # FIN: Acción de soporte AppBackend._submit_work
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._dispatch_work_item
    # FUNCIÓN: Implementación directa AppBackend._dispatch_work_item. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: self.logMessage.emit → self._complete_active_work → payload.get → bool → self.refreshUI → self.translationStarted.emit → self._start_pipeline_translation → self._start_mod_job.
    # ==============================================================================
    def _dispatch_work_item(self, item: LN_src_backend_app_backend__WorkItem) -> None:
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._dispatch_work_item — self._shutting_down
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self._shutting_down. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if self._shutting_down:
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend._dispatch_work_item — self._shutting_down
        # ==============================================================================
        kind = item.kind
        payload = item.payload
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._dispatch_work_item — kind == 'translation'
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: kind == 'translation'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if kind == 'translation':
            self._active_batch_id = payload.get('batch_id')
            self._project_path = payload.get('project_path', self._project_path)
            self._tl_mode = bool(payload.get('tl_mode', False))
            self._tl_source_path = payload.get('tl_source_path', '')
            self._target_language = payload.get('target_language', self._target_language)
            self.config.translation_settings.target_language = self._target_language
            self.config.translation_settings.source_language = payload.get('source_language', 'auto')
            self._selected_engine = payload.get('engine', self._selected_engine)
            self.refreshUI()
            self._is_translating = True
            self.translationStarted.emit()
            self._start_pipeline_translation()
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend._dispatch_work_item — kind == 'translation'
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._dispatch_work_item — kind in ('mod_analyze', 'mod_generate')
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: kind in ('mod_analyze', 'mod_generate'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if kind in ('mod_analyze', 'mod_generate'):
            self._start_mod_job(kind, payload)
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend._dispatch_work_item — kind in ('mod_analyze', 'mod_generate')
        # ==============================================================================
        self.logMessage.emit('error', f'Unknown queued work item: {kind}')
        self._complete_active_work()
    # ==============================================================================
    # FIN: Acción de soporte AppBackend._dispatch_work_item
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._complete_active_work
    # FUNCIÓN: Implementación directa AppBackend._complete_active_work. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: self._work_queue.complete_active → self.workQueueChanged.emit → self.pipeline_worker.isRunning → LN_src_backend_app_backend__QTimer.singleShot → self.logMessage.emit → self._dispatch_work_item → self._t.
    # ==============================================================================
    def _complete_active_work(self) -> None:
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._complete_active_work — self.pipeline_worker is not None and self.pipeline_worker.isRunning()
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self.pipeline_worker is not None and self.pipeline_worker.isRunning(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if self.pipeline_worker is not None and self.pipeline_worker.isRunning():
            LN_src_backend_app_backend__QTimer.singleShot(25, self._complete_active_work)
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend._complete_active_work — self.pipeline_worker is not None and self.pipeline_worker.isRunning()
        # ==============================================================================
        next_item = self._work_queue.complete_active()
        self.workQueueChanged.emit()
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._complete_active_work — next_item is not None and (not self._shutting_down)
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: next_item is not None and (not self._shutting_down). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if next_item is not None and (not self._shutting_down):
            self.logMessage.emit('info', self._t('log_work_queue_next', '▶ Starting next queued request ({kind}).', kind=next_item.kind))
            self._dispatch_work_item(next_item)
        # ==============================================================================
        # FIN: Bloque If de AppBackend._complete_active_work — next_item is not None and (not self._shutting_down)
        # ==============================================================================
    # ==============================================================================
    # FIN: Acción de soporte AppBackend._complete_active_work
    # ==============================================================================

