    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._start_pipeline_translation
    # FUNCIÓN: Start the pipeline-based translation (normal or TL mode).
    # Implementación directa AppBackend._start_pipeline_translation. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: self._refresh_active_translator → LN_src_backend_app_backend__TranslationPipeline → self.config.normalize_renpy_language_code → self.pipeline.configure → self.pipeline.stage_changed.connect → self.pipeline.progress_updated.connect → self.pipeline.log_message.connect → self.pipeline.finished.connect → self.pipeline.show_warning.connect → self.logMessage.emit → LN_src_backend_app_backend__PipelineWorker → self.pipeline_worker.start → self._t → self.logger.exception → self._record_batch_result → self.translationFinished.emit → self._finish_batch_if_complete → self._complete_active_work → str.
    # ==============================================================================
    def _start_pipeline_translation(self) -> None:
        """Start the pipeline-based translation (normal or TL mode)."""
        # ==============================================================================
        # INICIO: Bloque Try de AppBackend._start_pipeline_translation — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            self._refresh_active_translator()
            self.pipeline = LN_src_backend_app_backend__TranslationPipeline(self.config, self.translation_manager)
            target_path = self._tl_source_path if self._tl_mode else self._project_path
            effective_target = self.config.normalize_renpy_language_code(self.config.translation_settings.target_language or self._target_language or 'english')
            self._target_language = effective_target
            effective_source = self.config.translation_settings.source_language or 'auto'
            self.pipeline.configure(game_exe_path=target_path, target_language=self._target_language, source_language=effective_source, engine=self._selected_engine, auto_unren=self.config.app_settings.unren_auto_download, use_proxy=self.config.proxy_settings.enabled, include_deep_scan=self.config.translation_settings.enable_deep_scan, include_rpyc=self.config.translation_settings.enable_rpyc_reader, is_tl_mode=self._tl_mode)
            self.pipeline.stage_changed.connect(self._on_stage_changed)
            self.pipeline.progress_updated.connect(self._on_progress_updated)
            self.pipeline.log_message.connect(self._on_log_message)
            self.pipeline.finished.connect(self._on_pipeline_finished)
            self.pipeline.show_warning.connect(self._on_show_warning)
            self.logMessage.emit('info', self._t('log_translation_starting', '🚀 Translation starting...'))
            self.pipeline_worker = LN_src_backend_app_backend__PipelineWorker(self.pipeline)
            self.pipeline_worker.start()
        except Exception as exc:
            self.logger.exception('[AppBackend] startTranslation error')
            self.logMessage.emit('error', f'❌ Translation start error: {exc}')
            self._is_translating = False
            self._record_batch_result(False, str(exc), {}, '')
            self.translationFinished.emit(False, str(exc))
            self._finish_batch_if_complete()
            self._complete_active_work()
        # ==============================================================================
        # FIN: Bloque Try de AppBackend._start_pipeline_translation — gestión de excepciones
        # ==============================================================================
    # ==============================================================================
    # FIN: Acción de soporte AppBackend._start_pipeline_translation
