    # Implementación directa AppBackend.stop_translation. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: self.pipeline.stop → self.cancellationChanged.emit → self._work_queue.drop_pending → self.logMessage.emit → getattr → self._batches.get → self.workQueueChanged.emit → self._t → self.pipeline_worker.isRunning → self.pipeline_worker.wait → item.payload.get → report.add.
    # ==============================================================================
    def stop_translation(self, wait_ms=0):
        """Acknowledge once, wake active network awaits, and keep safe worker cleanup."""
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.stop_translation — not self._is_translating or self.pipeline is None
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not self._is_translating or self.pipeline is None. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not self._is_translating or self.pipeline is None:
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend.stop_translation — not self._is_translating or self.pipeline is None
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.stop_translation — getattr(self, '_cancelled_pipeline', None) is self.pipeline
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: getattr(self, '_cancelled_pipeline', None) is self.pipeline. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if getattr(self, '_cancelled_pipeline', None) is self.pipeline:
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend.stop_translation — getattr(self, '_cancelled_pipeline', None) is self.pipeline
        # ==============================================================================
        self._cancelled_pipeline = self.pipeline
        self.pipeline.stop()
        self.cancellationChanged.emit()
        dropped = self._work_queue.drop_pending(lambda item: item.kind == 'translation')
        # ==============================================================================
        # INICIO: Bloque For de AppBackend.stop_translation — dropped
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: dropped. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for item in dropped:
            report = self._batches.get(item.payload.get('batch_id'))
            # ==============================================================================
            # INICIO: Bloque If de AppBackend.stop_translation — report is not None
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: report is not None. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if report is not None:
                report.add(item.payload.get('target_language', ''), False, self._t('trial_stopped', 'Stopped. Progress saved.'), {'stopped': True})
            # ==============================================================================
            # FIN: Bloque If de AppBackend.stop_translation — report is not None
            # ==============================================================================
        # ==============================================================================
        # FIN: Bloque For de AppBackend.stop_translation — dropped
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.stop_translation — dropped
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: dropped. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if dropped:
            self.workQueueChanged.emit()
        # ==============================================================================
        # FIN: Bloque If de AppBackend.stop_translation — dropped
