    # Secuencia del bloque: LN_src_backend_app_backend__pyqtSlot → self.modTranslationsChanged.emit → self.generateMod → self.logMessage.emit → save_interface_mod_corrections → self._t → self.logger.warning → str → self.modStatusChanged.emit.
    # ==============================================================================
    @LN_src_backend_app_backend__pyqtSlot(list, result=bool)
    def saveModCorrections(self, corrections: list) -> bool:
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.saveModCorrections — not self._mod_project_path
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not self._mod_project_path. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not self._mod_project_path:
            self.logMessage.emit('error', self._t('mod_status_select_game', "Select a Ren'Py game from the MOD page first."))
            return False
        # ==============================================================================
        # FIN: Bloque If de AppBackend.saveModCorrections — not self._mod_project_path
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.saveModCorrections — self._mod_running
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self._mod_running. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if self._mod_running:
            self.logMessage.emit('warning', self._t('mod_status_generating', 'Wait until MOD generation is complete.'))
            return False
        # ==============================================================================
        # FIN: Bloque If de AppBackend.saveModCorrections — self._mod_running
        # ==============================================================================
        save_interface_mod_corrections = LN_src_ui_mod_generator__save_interface_mod_corrections
        # ==============================================================================
        # INICIO: Bloque Try de AppBackend.saveModCorrections — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            save_interface_mod_corrections(self._mod_project_path, self.config.translation_settings.mod_target_language, corrections)
        except (OSError, ValueError) as exc:
            self.logger.warning('[#MOD] Could not save manual corrections: %s', exc)
            self.logMessage.emit('error', str(exc))
            self._mod_status = str(exc)
            self.modStatusChanged.emit()
            return False
        # ==============================================================================
        # FIN: Bloque Try de AppBackend.saveModCorrections — gestión de excepciones
        # ==============================================================================
        self.modTranslationsChanged.emit()
        self.generateMod()
        return True
    # ==============================================================================
    # FIN: Button "Guardar y regenerar"
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._start_mod_job
    # FUNCIÓN: Implementación directa AppBackend._start_mod_job. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: self.modRunningChanged.emit → self.statsCleared.emit → self.modOutputPathChanged.emit → self._t → self.modStatusChanged.emit → LN_src_backend_app_backend__threading.Thread(target=_worker, daemon=True).start → payload.get → self._modWorkerFinished.emit → LN_src_backend_app_backend__threading.Thread → analyze_interface_mod → str(payload.get('engine', 'google') or 'google').lower → self._engine_from_str → self._ensure_mod_translator → self.logger.exception → self._modProgress.emit → generate_interface_mod_languages → generate_interface_mod → getattr → self._install_mod_language_menu → SimpleNamespace → str → LN_src_backend_app_backend__os.path.dirname.
    # ==============================================================================
    def _start_mod_job(self, kind: str, payload: LN_src_backend_app_backend__Dict[str, LN_src_backend_app_backend__Any]) -> None:
        self._mod_running = True
        self.modRunningChanged.emit()
        self.statsCleared.emit()
        self._mod_output_path = ''
        self.modOutputPathChanged.emit()
        self._mod_status = self._t('mod_status_analyzing' if kind == 'mod_analyze' else 'mod_status_generating', 'Analyzing interface...' if kind == 'mod_analyze' else 'Generating every interface language...' if kind == 'mod_generate_all' else 'Generating interface MOD...')
        self.modStatusChanged.emit()

        # ==============================================================================
        # INICIO: Acción de soporte AppBackend._start_mod_job._worker
        # FUNCIÓN: Implementación directa AppBackend._start_mod_job._worker. Origen trazable: src/backend/app_backend.py.
        # Secuencia del bloque: payload.get → self._modWorkerFinished.emit → analyze_interface_mod → str(payload.get('engine', 'google') or 'google').lower → self._engine_from_str → self._ensure_mod_translator → self.logger.exception → self._modProgress.emit → generate_interface_mod_languages → generate_interface_mod → getattr → self._install_mod_language_menu → SimpleNamespace → str → LN_src_backend_app_backend__os.path.dirname.
        # ==============================================================================
        def _worker() -> None:
            # ==============================================================================
            # INICIO: Bloque Try de AppBackend._start_mod_job._worker — gestión de excepciones
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            try:
                project_path = payload.get('project_path', '')
                analyze_interface_mod = LN_src_ui_mod_generator__analyze_interface_mod
                generate_interface_mod = LN_src_ui_mod_generator__generate_interface_mod
                generate_interface_mod_languages = LN_src_ui_mod_generator__generate_interface_mod_languages
                # ==============================================================================
                # INICIO: Bloque If de AppBackend._start_mod_job._worker — kind == 'mod_analyze'
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: kind == 'mod_analyze'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                if kind == 'mod_analyze':
                    result = analyze_interface_mod(project_path, ui_text=self._t)
                else:
                    engine_name = str(payload.get('engine', 'google') or 'google').lower()
                    engine = self._engine_from_str(engine_name)
                    self._ensure_mod_translator(engine, engine_name)
                    progress = lambda current, total, text: self._modProgress.emit(current, total, text)
                    # ==============================================================================
                    # INICIO: Bloque If de AppBackend._start_mod_job._worker — kind == 'mod_generate_all'
                    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: kind == 'mod_generate_all'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                    # ==============================================================================
                    if kind == 'mod_generate_all':
                        result = generate_interface_mod_languages(project_path=project_path, source_language='auto', target_languages=payload.get('target_languages', LN_src_backend_app_backend__TARGET_LANGUAGE_FOLDERS), engine=engine, translation_manager=self._mod_translation_manager, progress=progress, ui_text=self._t)
                    else:
                        result = generate_interface_mod(project_path=project_path, source_language='auto', target_language=payload.get('target_language', self._target_language), engine=engine, translation_manager=self._mod_translation_manager, progress=progress, ui_text=self._t, allow_identity_language=True)
                    # ==============================================================================
                    # FIN: Bloque If de AppBackend._start_mod_job._worker — kind == 'mod_generate_all'
                    # ==============================================================================
                    # ==============================================================================
                    # INICIO: Bloque If de AppBackend._start_mod_job._worker — getattr(result, 'success', False) and getattr(result, 'output_path', '')
                    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: getattr(result, 'success', False) and getattr(result, 'output_path', ''). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                    # ==============================================================================
                    if getattr(result, 'success', False) and getattr(result, 'output_path', ''):
                        self._install_mod_language_menu(LN_src_backend_app_backend__os.path.dirname(result.output_path))
                    # ==============================================================================
                    # FIN: Bloque If de AppBackend._start_mod_job._worker — getattr(result, 'success', False) and getattr(result, 'output_path', '')
                    # ==============================================================================
                # ==============================================================================
                # FIN: Bloque If de AppBackend._start_mod_job._worker — kind == 'mod_analyze'
                # ==============================================================================
                self._modWorkerFinished.emit(result)
            except Exception as exc:
                self.logger.exception('[#MOD] MOD job failed')
                from types import SimpleNamespace
                self._modWorkerFinished.emit(SimpleNamespace(success=False, message=str(exc), candidates=0, translated=0, rejected=0, coverage=0.0, output_path=''))
            # ==============================================================================
            # FIN: Bloque Try de AppBackend._start_mod_job._worker — gestión de excepciones
            # ==============================================================================
        # ==============================================================================
        # FIN: Acción de soporte AppBackend._start_mod_job._worker
        # ==============================================================================
        LN_src_backend_app_backend__threading.Thread(target=_worker, daemon=True).start()
    # ==============================================================================
    # FIN: Acción de soporte AppBackend._start_mod_job
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._install_mod_language_menu
    # FUNCIÓN: The MOD's languages are chosen in the game's own language menu.
    #
    # The MOD has no chooser of its own; LinguaNova's language script
    # (game/zz_linguanova/linguanova.rpy) lists every language Ren'Py knows,
    # the MOD's included, in the game's menu or its Preferences.
    # Implementación directa AppBackend._install_mod_language_menu. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: install → self.logger.warning → self.logMessage.emit → self._t → str.
    # ==============================================================================
    def _install_mod_language_menu(self, game_dir: str) -> None:
        """The MOD's languages are chosen in the game's own language menu.

        The MOD has no chooser of its own; LinguaNova's language script
        (game/zz_linguanova/linguanova.rpy) lists every language Ren'Py knows,
        the MOD's included, in the game's menu or its Preferences.
        """
        # ==============================================================================
        # INICIO: Bloque Try de AppBackend._install_mod_language_menu — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            install = LN_src_core_delivery__install
            install(game_dir, self.config)
        except Exception as exc:
            self.logger.warning('[#MOD] language menu not installed: %s', exc)
            self.logMessage.emit('warning', self._t('mod_language_menu_failed', "The MOD is ready, but its languages could not be added to the game's menu: {error}", error=str(exc)[:200]))
        # ==============================================================================
        # FIN: Bloque Try de AppBackend._install_mod_language_menu — gestión de excepciones
        # ==============================================================================
    # ==============================================================================
    # FIN: Acción de soporte AppBackend._install_mod_language_menu
    # ==============================================================================

