    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._on_mod_worker_finished
    # FUNCIÓN: Implementación directa AppBackend._on_mod_worker_finished. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: self.modRunningChanged.emit → int → float → bool → self.modStatusChanged.emit → self.modStatsChanged.emit → self.modOutputPathChanged.emit → self.logMessage.emit → self._complete_active_work → getattr → len → self._emit_mod_batch_summary → self.progressChanged.emit → self.statsDetailReady.emit → self._t → max.
    # ==============================================================================
    def _on_mod_worker_finished(self, result: object) -> None:
        self._mod_running = False
        self.modRunningChanged.emit()
        raw_message = getattr(result, 'message', '') or ''
        self._mod_candidate_count = int(getattr(result, 'candidates', 0) or 0)
        self._mod_translated_count = int(getattr(result, 'translated', 0) or 0)
        self._mod_rejected_count = int(getattr(result, 'rejected', 0) or 0)
        self._mod_unchanged_count = int(getattr(result, 'unchanged', 0) or 0)
        self._mod_excluded_count = int(getattr(result, 'excluded', 0) or 0)
        self._mod_coverage = float(getattr(result, 'coverage', 0.0) or 0.0)
        self._mod_output_path = getattr(result, 'output_path', '') or ''
        ok = bool(getattr(result, 'success', False))
        pending = int(getattr(result, 'pending', 0) or 0)
        self._mod_partial = bool(ok and self._mod_output_path and (getattr(result, 'partial', False) or pending > 0))
        languages_total = int(getattr(result, 'languages_total', 0) or 0)
        languages_generated = int(getattr(result, 'languages_generated', 0) or 0)
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._on_mod_worker_finished — ok and self._mod_output_path and languages_total
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: ok and self._mod_output_path and languages_total. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if ok and self._mod_output_path and languages_total:
            # ==============================================================================
            # INICIO: Bloque If de AppBackend._on_mod_worker_finished — self._mod_partial
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self._mod_partial. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if self._mod_partial:
                self._mod_status = self._t('mod_status_multi_partial', 'MOD ready for {generated}/{total} languages. {translated} translated, {unchanged} unchanged and {pending} pending. See the log for failed languages.', generated=languages_generated, total=languages_total, translated=self._mod_translated_count, unchanged=self._mod_unchanged_count, pending=pending)
            else:
                self._mod_status = self._t('mod_status_multi_done', 'All {total} languages are in the same in-game selector. {translated} translated, {unchanged} unchanged ({coverage}% coverage).', total=languages_total, translated=self._mod_translated_count, unchanged=self._mod_unchanged_count, coverage=f'{self._mod_coverage:.1f}')
            # ==============================================================================
            # FIN: Bloque If de AppBackend._on_mod_worker_finished — self._mod_partial
            # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._on_mod_worker_finished — self._mod_partial
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self._mod_partial. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        elif self._mod_partial:
            self._mod_status = self._t('mod_status_generated_partial', 'MOD incomplete: {translated} of {count} texts translated ({coverage}%). {pending} could not be translated and stay pending; {unchanged} need no change; {excluded} code strings were excluded. Details: {report}', translated=self._mod_translated_count, count=self._mod_candidate_count, coverage=f'{self._mod_coverage:.1f}', pending=pending, unchanged=int(getattr(result, 'unchanged', 0) or 0), excluded=int(getattr(result, 'excluded', 0) or 0), report='linguanova_mod_report.json')
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._on_mod_worker_finished — ok and self._mod_output_path
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: ok and self._mod_output_path. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        elif ok and self._mod_output_path:
            self._mod_status = self._t('mod_status_generated_done', 'MOD generated: {translated}/{count} interface texts ({coverage}%).', translated=self._mod_translated_count, count=self._mod_candidate_count, coverage=f'{self._mod_coverage:.1f}')
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._on_mod_worker_finished — ok
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: ok. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        elif ok:
            self._mod_status = self._t('mod_status_analysis_done', 'MOD analysis complete: {count} interface texts detected.', count=self._mod_candidate_count)
        else:
            self._mod_status = self._t('mod_status_failed', 'MOD operation failed: {error}', error=raw_message or 'unknown error')
        # ==============================================================================
        # FIN: Bloque If de AppBackend._on_mod_worker_finished — ok
        # ==============================================================================
        # ==============================================================================
        # FIN: Bloque If de AppBackend._on_mod_worker_finished — ok and self._mod_output_path
        # ==============================================================================
        # ==============================================================================
        # FIN: Bloque If de AppBackend._on_mod_worker_finished — self._mod_partial
        # ==============================================================================
        # ==============================================================================
        # FIN: Bloque If de AppBackend._on_mod_worker_finished — ok and self._mod_output_path and languages_total
        # ==============================================================================
        self.modStatusChanged.emit()
        self.modStatsChanged.emit()
        self.modOutputPathChanged.emit()
        rows = getattr(result, 'language_results', None) or []
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._on_mod_worker_finished — len(rows) > 1
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: len(rows) > 1. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if len(rows) > 1:
            self._emit_mod_batch_summary(rows)
        # ==============================================================================
        # FIN: Bloque If de AppBackend._on_mod_worker_finished — len(rows) > 1
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._on_mod_worker_finished — ok and self._mod_output_path
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: ok and self._mod_output_path. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if ok and self._mod_output_path:
            self.progressChanged.emit(self._mod_candidate_count, max(self._mod_candidate_count, 1), self._mod_status)
            self.statsDetailReady.emit('mod', self._mod_candidate_count, self._mod_translated_count, self._mod_unchanged_count, pending, self._mod_partial)
        # ==============================================================================
        # FIN: Bloque If de AppBackend._on_mod_worker_finished — ok and self._mod_output_path
        # ==============================================================================
        self.logMessage.emit('error' if not ok else 'warning' if self._mod_partial else 'success', self._mod_status)
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._on_mod_worker_finished — ok and raw_message and (raw_message != self._mod_status)
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: ok and raw_message and (raw_message != self._mod_status). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if ok and raw_message and (raw_message != self._mod_status):
            self.logMessage.emit('warning' if self._mod_partial else 'info', raw_message)
        # ==============================================================================
        # FIN: Bloque If de AppBackend._on_mod_worker_finished — ok and raw_message and (raw_message != self._mod_status)
        # ==============================================================================
        self._complete_active_work()
    # ==============================================================================
    # FIN: Acción de soporte AppBackend._on_mod_worker_finished
    # ==============================================================================

