    # ==============================================================================
    # INICIO: AppBackend._on_pipeline_finished
    # FUNCIÓN: Publica la cobertura real y mantiene el resumen de líneas pendientes.

    def _on_pipeline_finished(self, result):
        """One truthful final state; pending, cancellation and failure are distinct."""
        self._is_translating = False
        stats = dict(getattr(result, 'stats', None) or {})
        success = bool(getattr(result, 'success', False))
        partial = bool(stats.get('partial'))
        message = str(getattr(result, 'message', '') or self._t('trial_failed', 'The game could not be prepared.'))
        output = str(getattr(result, 'output_path', '') or '')
        total = int(stats.get('translatable', stats.get('total', 0)) or 0)
        scope = 'translation' if success or 'translatable' in stats else 'translation_incomplete'
        translated = int(stats.get('translated', 0) or 0)
        pending = int(stats.get('pending', 0) or 0) + int(stats.get('empty', 0) or 0) + int(stats.get('interface_pending', 0) or 0)
        self.statsReady.emit(total, translated, max(0, total - translated))
        self.statsDetailReady.emit(scope, total, translated, int(stats.get('same_as_source', 0) or 0), pending, partial)
        in_batch = self._record_batch_result(success, message, stats, output)
        self.logMessage.emit('success' if success and (not partial) else 'warning' if stats.get('stopped') or success else 'error', message)
        if getattr(result, 'error', ''):
            self.logger.error('Trial diagnostic: %s', result.error)
        if not in_batch:
            title = self._t('trial_prepared_title', 'Game prepared') if stats.get('prepared') else self._t('trial_attention_title', 'Attention required')
            self.completionSummary.emit(title, message, output if stats.get('prepared') else '', str(stats.get('operation_record', '')), pending)
        self.translationFinished.emit(success, message)
        self._finish_batch_if_complete()
        self._complete_active_work()

    # FIN: AppBackend._on_pipeline_finished
    # ==============================================================================
