    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._auto_update_thread
    # FUNCIÓN: Implementación directa AppBackend._auto_update_thread. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: LN_src_utils_auto_updater__download_update → self.logMessage.emit → self.updateDownloadFinished.emit → self.updateInstallerLaunched.emit → int → self.updateDownloadProgress.emit → getattr → LN_src_utils_auto_updater__launch_portable_update → LN_src_utils_auto_updater__launch_installer → self._t → str → self.logger.warning → self.autoUpdateChanged.emit → self._t('update_failed', 'Automatic update failed: {error}').replace.
    # Interacción con archivos/ejecutables, en orden del código (se respetan las condiciones visibles):
    # Paso 1: LN_src_utils_auto_updater__download_update(plan, progress, self._update_cancel).
    # ==============================================================================
    def _auto_update_thread(self, plan) -> None:
        pass
        last = [-1]

        # ==============================================================================
        # INICIO: Acción de soporte AppBackend._auto_update_thread.progress
        # FUNCIÓN: Implementación directa AppBackend._auto_update_thread.progress. Origen trazable: src/backend/app_backend.py.
        # Secuencia del bloque: int → self.updateDownloadProgress.emit.
        # ==============================================================================
        def progress(done: int, total: int) -> None:
            percent = int(done * 100 / total) if total else 0
            # ==============================================================================
            # INICIO: Bloque If de AppBackend._auto_update_thread.progress — percent != last[0]
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: percent != last[0]. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if percent != last[0]:
                last[0] = percent
                self.updateDownloadProgress.emit(percent)
            # ==============================================================================
            # FIN: Bloque If de AppBackend._auto_update_thread.progress — percent != last[0]
            # ==============================================================================
        # ==============================================================================
        # FIN: Acción de soporte AppBackend._auto_update_thread.progress
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque Try de AppBackend._auto_update_thread — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            installer = LN_src_utils_auto_updater__download_update(plan, progress, self._update_cancel)
            self.logMessage.emit('success', '✅ ' + self._t('update_verified', 'Update downloaded and verified (SHA-256). Installing...'))
            # ==============================================================================
            # INICIO: Bloque If de AppBackend._auto_update_thread — getattr(plan, 'kind', 'installer') == 'portable'
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: getattr(plan, 'kind', 'installer') == 'portable'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if getattr(plan, 'kind', 'installer') == 'portable':
                LN_src_utils_auto_updater__launch_portable_update(installer, plan.install_dir)
            else:
                LN_src_utils_auto_updater__launch_installer(installer, plan.install_dir)
            # ==============================================================================
            # FIN: Bloque If de AppBackend._auto_update_thread — getattr(plan, 'kind', 'installer') == 'portable'
            # ==============================================================================
            self.updateDownloadFinished.emit(True, self._t('update_installing', 'Installing the update. LinguaNova will reopen by itself.'))
            self.updateInstallerLaunched.emit()
        except Exception as exc:
            reason = str(exc)
            # ==============================================================================
            # INICIO: Bloque If de AppBackend._auto_update_thread — reason == 'cancelled'
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: reason == 'cancelled'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if reason == 'cancelled':
                msg = self._t('update_cancelled', 'Update cancelled.')
                level = 'info'
            else:
                msg = self._t('update_failed', 'Automatic update failed: {error}').replace('{error}', reason)
                level = 'warning'
            # ==============================================================================
            # FIN: Bloque If de AppBackend._auto_update_thread — reason == 'cancelled'
            # ==============================================================================
            self.logger.warning('[AppBackend] Automatic update: %s', reason)
            # ==============================================================================
            # INICIO: Bloque Try de AppBackend._auto_update_thread — gestión de excepciones
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            try:
                self.logMessage.emit(level, msg)
                self.updateDownloadFinished.emit(False, msg)
            except RuntimeError:
                pass
            # ==============================================================================
            # FIN: Bloque Try de AppBackend._auto_update_thread — gestión de excepciones
            # ==============================================================================
        finally:
            self._update_downloading = False
            # ==============================================================================
            # INICIO: Bloque Try de AppBackend._auto_update_thread — gestión de excepciones
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            try:
                self.autoUpdateChanged.emit()
            except RuntimeError:
                pass
            # ==============================================================================
            # FIN: Bloque Try de AppBackend._auto_update_thread — gestión de excepciones
            # ==============================================================================
        # ==============================================================================
        # FIN: Bloque Try de AppBackend._auto_update_thread — gestión de excepciones
        # ==============================================================================
    # ==============================================================================
    # FIN: Acción de soporte AppBackend._auto_update_thread
    # ==============================================================================

