    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._run_font_helper_thread
    # FUNCIÓN: Implementación directa AppBackend._run_font_helper_thread. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: getattr → check_font_for_project → summary.get → self._tool_game_dir → '; '.join → self.logMessage.emit → ', '.join → list → missing.items.
    # ==============================================================================
    def _run_font_helper_thread(self) -> None:
        # ==============================================================================
        # INICIO: Bloque Try de AppBackend._run_font_helper_thread — gestión de excepciones
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        try:
            check_font_for_project = LN_src_tools_font_helper__check_font_for_project
            target_lang = getattr(self.config.translation_settings, 'target_language', 'english')
            summary = check_font_for_project(self._tool_game_dir(), target_lang)
            total = summary.get('fonts_checked', 0)
            compat = summary.get('compatible_fonts', 0)
            incompat = summary.get('incompatible_fonts', 0)
            suggestions = summary.get('suggestions', [])
            sug_str = f" Recommended: {', '.join(suggestions[:3])}" if suggestions else ''
            basis = 'the characters your translation uses' if summary.get('basis') == 'translation' else f"a '{target_lang}' sample (no translation yet)"
            # ==============================================================================
            # INICIO: Bloque If de AppBackend._run_font_helper_thread — incompat > 0
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: incompat > 0. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if incompat > 0:
                missing = summary.get('missing_by_font', {})
                details = '; '.join((f'{name}: {chars}' for name, chars in list(missing.items())[:3]))
                self.logMessage.emit('warning', f"⚠️ Font check against {basis}: {total} font(s) scanned — {incompat} cannot show all characters (missing → {details}).{sug_str} Use 'Inject' to add a matching font.")
            # ==============================================================================
            # INICIO: Bloque If de AppBackend._run_font_helper_thread — total > 0
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: total > 0. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            elif total > 0:
                self.logMessage.emit('success', f"✅ Font check against {basis}: all {compat} font(s) can show '{target_lang}'.")
            else:
                self.logMessage.emit('info', f"ℹ️ No custom fonts found in game folder. Ren'Py will use its default font.{sug_str}")
            # ==============================================================================
            # FIN: Bloque If de AppBackend._run_font_helper_thread — total > 0
            # ==============================================================================
            # ==============================================================================
            # FIN: Bloque If de AppBackend._run_font_helper_thread — incompat > 0
            # ==============================================================================
        except Exception as e:
            self.logMessage.emit('error', f'❌ Font helper error: {e}')
        # ==============================================================================
        # FIN: Bloque Try de AppBackend._run_font_helper_thread — gestión de excepciones
        # ==============================================================================
    # ==============================================================================
    # FIN: Acción de soporte AppBackend._run_font_helper_thread
    # ==============================================================================

