        # ==============================================================================
        if LN_src_backend_app_backend__os.path.isfile(path):
            path = LN_src_backend_app_backend__os.path.dirname(path)
        # ==============================================================================
        # FIN: Bloque If de AppBackend._tool_game_dir — LN_src_backend_app_backend__os.path.isfile(path)
        # ==============================================================================
        parts = LN_src_backend_app_backend__os.path.normpath(path).split(LN_src_backend_app_backend__os.sep)
        lowered = [p.lower() for p in parts]
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._tool_game_dir — 'tl' in lowered
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: 'tl' in lowered. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if 'tl' in lowered:
            idx = len(lowered) - 1 - lowered[::-1].index('tl')
            path = LN_src_backend_app_backend__os.sep.join(parts[:idx]) or path
        # ==============================================================================
        # FIN: Bloque If de AppBackend._tool_game_dir — 'tl' in lowered
        # ==============================================================================
        candidate = LN_src_backend_app_backend__os.path.join(path, 'game')
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._tool_game_dir — LN_src_backend_app_backend__os.path.isdir(candidate)
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_src_backend_app_backend__os.path.isdir(candidate). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if LN_src_backend_app_backend__os.path.isdir(candidate):
            return candidate
        # ==============================================================================
        # FIN: Bloque If de AppBackend._tool_game_dir — LN_src_backend_app_backend__os.path.isdir(candidate)
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de AppBackend._tool_game_dir — LN_src_backend_app_backend__os.path.basename(LN_src_backend_app_backend__os.path.normpath(path)).lower() == 'game' and LN_src_backend_app_backend__os.path.isdir(path)
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_src_backend_app_backend__os.path.basename(LN_src_backend_app_backend__os.path.normpath(path)).lower() == 'game' and LN_src_backend_app_backend__os.path.isdir(path). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if LN_src_backend_app_backend__os.path.basename(LN_src_backend_app_backend__os.path.normpath(path)).lower() == 'game' and LN_src_backend_app_backend__os.path.isdir(path):
            return path
        # ==============================================================================
        # FIN: Bloque If de AppBackend._tool_game_dir — LN_src_backend_app_backend__os.path.basename(LN_src_backend_app_backend__os.path.normpath(path)).lower() == 'game' and LN_src_backend_app_backend__os.path.isdir(path)
        # ==============================================================================
        return None
