    # ==============================================================================
    # INICIO: Button "Integrar en el menú del juego"
    # FUNCIÓN: Integrate a tl/<language> translation into the game's native selector.
    # Implementación directa AppBackend.runToolActivateLanguage. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: LN_src_backend_app_backend__pyqtSlot → self._tool_game_dir → (language or '').strip → create_language_init_file → (result or {}).get → self.logMessage.emit → self._t → self._t('log_lang_activated', "✅ Language integrated into the game's native selector: {lang}").replace.
    # Interacción con archivos/ejecutables, en orden del código (se respetan las condiciones visibles):
    # Paso 1: self._t('log_lang_activated', "✅ Language integrated into the game's native selector: {lang}").replace('{lang}', language).
    # ==============================================================================
    @LN_src_backend_app_backend__pyqtSlot(str)
    def runToolActivateLanguage(self, language: str) -> None:
        """Integrate a tl/<language> translation into the game's native selector."""
        game_dir = self._tool_game_dir()
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.runToolActivateLanguage — not game_dir
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not game_dir. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not game_dir:
            self.logMessage.emit('error', self._t('log_select_game', '❌ Please select a game folder or EXE first.'))
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend.runToolActivateLanguage — not game_dir
        # ==============================================================================
        language = (language or '').strip()
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.runToolActivateLanguage — not language
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not language. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not language:
            self.logMessage.emit('warning', self._t('tool_lang_no_tl', 'No translation folders found in game/tl. Translate the game first.'))
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend.runToolActivateLanguage — not language
        # ==============================================================================
        create_language_init_file = LN_src_core_pipeline_saving__create_language_init_file
        result = create_language_init_file(game_dir, language, self.config, self.logMessage.emit, force=True)
        status = (result or {}).get('status', '')
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.runToolActivateLanguage — status == 'installed'
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: status == 'installed'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if status == 'installed':
            self.logMessage.emit('success', self._t('log_lang_activated', "✅ Language integrated into the game's native selector: {lang}").replace('{lang}', language))
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.runToolActivateLanguage — status == 'missing_tl'
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: status == 'missing_tl'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        elif status == 'missing_tl':
            self.logMessage.emit('warning', self._t('tool_lang_no_tl', 'No translation folders found in game/tl. Translate the game first.'))
        # ==============================================================================
        # FIN: Bloque If de AppBackend.runToolActivateLanguage — status == 'missing_tl'
        # ==============================================================================
        # ==============================================================================
        # FIN: Bloque If de AppBackend.runToolActivateLanguage — status == 'installed'
        # ==============================================================================
    # ==============================================================================
    # FIN: Button "Integrar en el menú del juego"
    # ==============================================================================

