    # Secuencia del bloque: LN_src_backend_app_backend__pyqtSlot → self.logMessage.emit → LN_src_backend_app_backend__threading.Thread(target=self._run_glossary_extractor_thread, daemon=True).start → self._require_tool_game_dir → self._t → LN_src_backend_app_backend__threading.Thread.
    # ==============================================================================
    @LN_src_backend_app_backend__pyqtSlot()
    def runToolGlossaryExtractor(self) -> None:
        """Extract glossary terms from project."""
        # ==============================================================================
        # INICIO: Bloque If de AppBackend.runToolGlossaryExtractor — not self._require_tool_game_dir()
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not self._require_tool_game_dir(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not self._require_tool_game_dir():
            return
        # ==============================================================================
        # FIN: Bloque If de AppBackend.runToolGlossaryExtractor — not self._require_tool_game_dir()
        # ==============================================================================
        self.logMessage.emit('info', self._t('log_glossary_extracting', '📚 Extracting glossary terms...'))
        LN_src_backend_app_backend__threading.Thread(target=self._run_glossary_extractor_thread, daemon=True).start()
    # ==============================================================================
    # FIN: Button "Extraer glosario"
    # ==============================================================================

    # ==============================================================================
    # INICIO: Acción de soporte AppBackend._run_glossary_extractor_thread
    # FUNCIÓN: Implementación directa AppBackend._run_glossary_extractor_thread. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: GlossaryExtractor → extractor.extract_from_directory → terms.items → self.config.save_glossary → self.glossaryChanged.emit → self.logMessage.emit → self._tool_game_dir → self._t('log_glossary_extracted', '✅ {found} terms found, {added} new ones added to the glossary (Glossary tab).').replace('{found}', str(len(terms))).replace → str → self._t('log_glossary_extracted', '✅ {found} terms found, {added} new ones added to the glossary (Glossary tab).').replace → self._t → len.
    # ==============================================================================
    def _run_glossary_extractor_thread(self) -> None:
        try:
            self._sync_glossary_scope(emit=False)
            if not self.config.glossary_scope()[0]:
                self.logMessage.emit('warning', self._t('glossary_scope_none', 'Select a game: each game and each target language has its own glossary.'))
                return
            result = LN_src_core_project_glossary__analyze(getattr(self, '_project_path', '') or self._tool_game_dir())
            terms = {name: name for name in result.names}
            terms.update({word: '' for word, _count in result.terms if word not in terms})
            added = 0
            for term, target in terms.items():
                if term not in self.config.glossary:
                    self.config.glossary[term] = target
                    added += 1
            self.config.save_glossary()
            self.glossaryChanged.emit()
            self.logMessage.emit('success', self._t('log_glossary_extracted', '✅ {found} terms found, {added} new ones added to the glossary (Glossary tab).').replace('{found}', str(len(terms))).replace('{added}', str(added)))
        except Exception as e:
            self.logMessage.emit('error', f'❌ Glossary extractor error: {e}')

    # ==============================================================================
    # INICIO: Item "pageGlossary" [id: pageGlossary] / Label "términos cargados."
    # FUNCIÓN: Implementación directa AppBackend.glossaryList. Origen trazable: src/backend/app_backend.py.
    # Secuencia del bloque: LN_src_backend_app_backend__pyqtProperty → self.settings.get_glossary_list.
    # ==============================================================================
    @LN_src_backend_app_backend__pyqtProperty(list, notify=glossaryChanged)
    def glossaryList(self) -> list:
        self._sync_glossary_scope(emit=False)
        return self.settings.get_glossary_list()

    def _sync_glossary_scope(self, emit: bool=True) -> None:
        """Follow the selected game and target language; analyse a newly chosen game."""
        project = getattr(self, '_project_path', '') or ''
        try:
            language = self.settings.get_target_language()
        except Exception:
            language = ''
        if self.config.set_glossary_scope(project, language) and emit:
            self.glossaryChanged.emit()
        game = LN_src_core_project_glossary__game_dir_of(project)
        key = str(game) if game is not None else ''
        if key and key != getattr(self, '_glossary_analysis_game', ''):
            self._glossary_analysis_game = key
            LN_src_backend_app_backend__threading.Thread(target=self._analyze_game_thread, args=(project,), daemon=True, name='glossary-analysis').start()

    def _analyze_game_thread(self, project: str) -> None:
        try:
            result = LN_src_core_project_glossary__analyze(project)
        except Exception as exc:
            self.logger.warning('Game analysis failed: %s', exc)
            return
        files = result.script_files + result.archive_files + result.compiled_files
        self.logMessage.emit('info', self._t('log_game_analysis_done', 'Game analysed (kept in memory only): {files} script files, {names} character names and {terms} recurring terms.', files=files, names=len(result.names), terms=len(result.terms)))

    @LN_src_backend_app_backend__pyqtProperty(str, notify=glossaryChanged)
    def glossaryScopeText(self) -> str:
        """"Game · Language" of the glossary being edited, or a hint to choose a game."""
        self._sync_glossary_scope(emit=False)
        game, language = self.config.glossary_scope()
        if not game:
            return self._t('glossary_scope_none', 'Select a game: each game and each target language has its own glossary.')
        name = LN_src_utils_languages__display_name(language, self.config.app_settings.ui_language or 'en')
        return self._t('glossary_scope_label', 'Glossary of {game} · {language}', game=LN_src_backend_app_backend__os.path.basename(LN_src_backend_app_backend__os.path.dirname(game)), language=name)
