    def totals(self) -> LN_src_backend_batch_report__Dict[str, LN_src_backend_batch_report__Any]:
        counted = [r for r in self.rows if r.status != LN_src_backend_batch_report__STATUS_SKIPPED]
        total = sum((r.total for r in counted))
        translated = sum((r.translated for r in counted))
        untranslated = sum((r.untranslated for r in counted))
        coverage = round(translated * 100.0 / total, 1) if total else 0.0
        return {'total': total, 'translated': translated, 'untranslated': untranslated, 'coverage': coverage, 'missing': round(100.0 - coverage, 1) if total else 0.0, 'languages': len(counted), 'failed': sum((1 for r in self.rows if r.status in (LN_src_backend_batch_report__STATUS_FAILED, LN_src_backend_batch_report__STATUS_STOPPED)))}
