    # Secuencia del bloque: lb.update → self.ordered_rows → self.totals → lines.append → names.get → {LN_src_backend_batch_report__STATUS_FAILED: f"  ({lb['failed']})", LN_src_backend_batch_report__STATUS_STOPPED: f"  ({lb['stopped']})"}.get → '\n'.join → r.language.capitalize.
