            # ==============================================================================
            note = {LN_src_backend_batch_report__STATUS_FAILED: f"  ({lb['failed']})", LN_src_backend_batch_report__STATUS_STOPPED: f"  ({lb['stopped']})"}.get(r.status, '')
            lines.append(f'{name:<14}{r.translated:>12}{r.untranslated:>14}{r.coverage:>10.1f}%{note}')
