        # FIN: Bloque For de BatchReport.to_text — self.ordered_rows()
        # ==============================================================================
        t = self.totals()
        lines.append(f"{lb['total']:<14}{t['translated']:>12}{t['untranslated']:>14}{t['coverage']:>10.1f}%")
        return '\n'.join(lines) + '\n'
