# ==============================================================================
def LN_src_utils_recent_projects___key(path: str) -> str:
    return LN_src_utils_recent_projects__os.path.normcase(LN_src_utils_recent_projects__os.path.normpath(path))
# ==============================================================================
# FIN: Acción de soporte _key
# ==============================================================================

