# ==============================================================================
def LN_src_utils_recent_projects__remove_recent(current: LN_src_utils_recent_projects__Iterable[str], path: str) -> LN_src_utils_recent_projects__List[str]:
    wanted = LN_src_utils_recent_projects___key(path or '')
