    # ==============================================================================
    # INICIO: Item "page" [id: page]
    # FUNCIÓN: The configured target language if it has a tl folder, else the first one.
    # Implementación directa EditorBackend.preferredLanguage. Origen trazable: src/backend/editor_backend.py.
    # Secuencia del bloque: LN_src_backend_editor_backend__pyqtSlot → (self.app.config.translation_settings.target_language or '').lower → name.lower.
    # ==============================================================================
    @LN_src_backend_editor_backend__pyqtSlot(result=str)
    def preferredLanguage(self) -> str:
        """The configured target language if it has a tl folder, else the first one."""
        # ==============================================================================
        # INICIO: Bloque If de EditorBackend.preferredLanguage — self._language and self._language in self._languages
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self._language and self._language in self._languages. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if self._language and self._language in self._languages:
            return self._language
        # ==============================================================================
        # FIN: Bloque If de EditorBackend.preferredLanguage — self._language and self._language in self._languages
        # ==============================================================================
        target = (self.app.config.translation_settings.target_language or '').lower()
        # ==============================================================================
        # INICIO: Bloque For de EditorBackend.preferredLanguage — self._languages
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self._languages. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for name in self._languages:
            # ==============================================================================
            # INICIO: Bloque If de EditorBackend.preferredLanguage — name.lower() == target
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: name.lower() == target. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if name.lower() == target:
                return name
            # ==============================================================================
            # FIN: Bloque If de EditorBackend.preferredLanguage — name.lower() == target
            # ==============================================================================
        # ==============================================================================
        # FIN: Bloque For de EditorBackend.preferredLanguage — self._languages
        # ==============================================================================
        return self._languages[0] if self._languages else ''
    # ==============================================================================
    # FIN: Item "page" [id: page]
    # ==============================================================================

    # ==============================================================================
    # INICIO: Button "Button" / Item "page" [id: page]
    # FUNCIÓN: Implementación directa EditorBackend.loadLanguage. Origen trazable: src/backend/editor_backend.py.
    # Secuencia del bloque: LN_src_backend_editor_backend__pyqtSlot → self._run → self.app._tool_game_dir → self.store.load → self._refresh_page → self.notify.emit → self._t → LN_src_backend_editor_backend__load_language → len.
    # ==============================================================================
    @LN_src_backend_editor_backend__pyqtSlot(str)
    def loadLanguage(self, language: str) -> None:
        game_dir = self.app._tool_game_dir() or ''
        # ==============================================================================
        # INICIO: Bloque If de EditorBackend.loadLanguage — not game_dir or not language or self._busy
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not game_dir or not language or self._busy. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not game_dir or not language or self._busy:
            # ==============================================================================
            # INICIO: Bloque If de EditorBackend.loadLanguage — not game_dir
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not game_dir. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if not game_dir:
                self.notify.emit('error', self._t('log_select_game', '❌ Please select a game folder or EXE first.'))
            # ==============================================================================
            # FIN: Bloque If de EditorBackend.loadLanguage — not game_dir
            # ==============================================================================
            return
        # ==============================================================================
        # FIN: Bloque If de EditorBackend.loadLanguage — not game_dir or not language or self._busy
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de EditorBackend.loadLanguage — game_dir != self._game_dir or language != self._language
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: game_dir != self._game_dir or language != self._language. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if game_dir != self._game_dir or language != self._language:
            self.store.load([])
            self._selected = {}
        # ==============================================================================
        # FIN: Bloque If de EditorBackend.loadLanguage — game_dir != self._game_dir or language != self._language
        # ==============================================================================
        self._game_dir, self._language = (game_dir, language)

        # ==============================================================================
        # INICIO: Acción de soporte EditorBackend.loadLanguage.done
        # FUNCIÓN: Implementación directa EditorBackend.loadLanguage.done. Origen trazable: src/backend/editor_backend.py.
        # Secuencia del bloque: self.store.load → self._refresh_page → self.notify.emit → self._t → len.
        # ==============================================================================
        def done(loaded: LoadedLanguage) -> None:
            self._loaded = loaded
            self.store.load(loaded.rows)
            self._page = 1
            self._refresh_page()
            self.notify.emit('info', self._t('editor_loaded', '{count} lines loaded.', count=len(loaded.rows)))
        # ==============================================================================
        # FIN: Acción de soporte EditorBackend.loadLanguage.done
        # ==============================================================================
        self._run(lambda: LN_src_backend_editor_backend__load_language(game_dir, language), done)
    # ==============================================================================
    # FIN: Button "Button" / Item "page" [id: page]
    # ==============================================================================

