    def _target_codes(self) -> LN_src_backend_editor_backend__List[str]:
        RENPY_TO_API_LANG = LN_src_core_pipeline_constants__RENPY_TO_API_LANG
        language = self._language
        codes = [language, RENPY_TO_API_LANG.get(language.lower(), '')]
        # ==============================================================================
        # INICIO: Bloque If de EditorBackend._target_codes — language.lower() == (self.app.config.translation_settings.target_language or '').lower()
