    # ==============================================================================
    @LN_src_backend_editor_backend__pyqtSlot()
    def save(self) -> None:
        # ==============================================================================
        # INICIO: Bloque If de EditorBackend.save — self._locked or not self._loaded or self._busy
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self._locked or not self._loaded or self._busy. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if self._locked or not self._loaded or self._busy:
            return
        # ==============================================================================
        # FIN: Bloque If de EditorBackend.save — self._locked or not self._loaded or self._busy
        # ==============================================================================
        edits = self.store.modified_by_file()
        # ==============================================================================
        # INICIO: Bloque If de EditorBackend.save — not edits
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not edits. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not edits:
            self.notify.emit('info', self._t('editor_nothing_to_save', 'No changes to save.'))
            return
        # ==============================================================================
        # FIN: Bloque If de EditorBackend.save — not edits
        # ==============================================================================
        get_diagnostics_dir = LN_src_core_pipeline_saving__get_diagnostics_dir
        resolve_project_root = LN_src_utils_path_manager__resolve_project_root
        translation_cache_file = LN_src_utils_path_manager__translation_cache_file
        lang_dir = LN_src_backend_editor_backend__os.path.join(self._game_dir, 'tl', self._language)
        backup_dir = LN_src_backend_editor_backend__os.path.join(get_diagnostics_dir(lang_dir, self._language), 'editor_backup', self._session_stamp)
        snapshots = self._loaded.snapshots
        project_root = resolve_project_root(self._game_dir)
        cache_file = translation_cache_file(self.app.config, project_root, self.app._project_path, self._language)
        codes = self._target_codes()

        # ==============================================================================
        # INICIO: Acción de soporte EditorBackend.save.job
        # FUNCIÓN: Implementación directa EditorBackend.save.job. Origen trazable: src/backend/editor_backend.py.
        # Secuencia del bloque: LN_src_backend_editor_backend__save_edits → set → LN_src_backend_editor_backend__sync_strings_json → LN_src_backend_editor_backend__sync_translation_cache → edits.values → self.logger.warning.
        # ==============================================================================
        def job() -> Any:
            result = LN_src_backend_editor_backend__save_edits(edits, snapshots, backup_dir)
            saved = set(result.saved_ids)
            changes = {r['original']: r['translated'] for rows in edits.values() for r in rows if r['id'] in saved and r['status'] == 'translated' and (not r['problem'])}
            strings = {r['original']: r['translated'] for rows in edits.values() for r in rows if r['id'] in saved and r['kind'] == 'string' and (r['status'] == 'translated')}
            # ==============================================================================
            # INICIO: Bloque Try de EditorBackend.save.job — gestión de excepciones
