            # ==============================================================================
            try:
                LN_src_backend_editor_backend__sync_strings_json(lang_dir, strings)
                LN_src_backend_editor_backend__sync_translation_cache(cache_file, codes, changes)
            except Exception as exc:
                self.logger.warning('[Editor] cache/strings.json sync failed: %s', exc)
            # ==============================================================================
            # FIN: Bloque Try de EditorBackend.save.job — gestión de excepciones
