        # ==============================================================================
        def done(result: Any) -> None:
            self.store.mark_saved(result.saved_ids)
            self._refresh_page()
            # ==============================================================================
            # INICIO: Bloque If de EditorBackend.save.done — result.saved_ids
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: result.saved_ids. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if result.saved_ids:
                self.notify.emit('success', self._t('editor_saved', '{count} lines saved to {files} files.', count=len(result.saved_ids), files=len(result.saved_files)))
            # ==============================================================================
            # FIN: Bloque If de EditorBackend.save.done — result.saved_ids
            # ==============================================================================
            # ==============================================================================
            # INICIO: Bloque If de EditorBackend.save.done — result.conflicts
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: result.conflicts. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if result.conflicts:
                self.notify.emit('warning', self._t('editor_conflict', '{files} files changed on disk after loading and were not saved. Reload, then save again.', files=len(result.conflicts)))
            # ==============================================================================
            # FIN: Bloque If de EditorBackend.save.done — result.conflicts
            # ==============================================================================
            # ==============================================================================
            # INICIO: Bloque If de EditorBackend.save.done — result.failed_ids
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: result.failed_ids. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if result.failed_ids:
                self.notify.emit('warning', self._t('editor_failed_lines', '{count} lines were not found where they were loaded and were not saved. Reload the editor.', count=len(result.failed_ids)))
            # ==============================================================================
            # FIN: Bloque If de EditorBackend.save.done — result.failed_ids
            # ==============================================================================
            # ==============================================================================
            # INICIO: Bloque If de EditorBackend.save.done — result.errors
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: result.errors. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if result.errors:
                self.notify.emit('error', self._t('editor_write_error', '{files} files could not be written.', files=len(result.errors)))
            # ==============================================================================
            # FIN: Bloque If de EditorBackend.save.done — result.errors
            # ==============================================================================
        # ==============================================================================
        # FIN: Acción de soporte EditorBackend.save.done
        # ==============================================================================
        self._run(job, done)
