    # INICIO: ActionButton "🤖 "
    # FUNCIÓN: Translate the selected line with the selected engine; the result is put in the editor, not saved.
    # Implementación directa EditorBackend.suggest. Origen trazable: src/backend/editor_backend.py.
    # Secuencia del bloque: LN_src_backend_editor_backend__pyqtSlot → self.store.get → app._refresh_active_translator → self._run → LN_src_backend_editor_backend__os.path.dirname → TranslationPipeline → pipeline.configure → TranslationEntry → self._replace_row → app._tool_game_dir → app.translation_manager.bypass_cache → pipeline._translate_entries([entry]).get → self.notify.emit → self.store.update → self._t → pipeline._translate_entries.
    # ==============================================================================
    @LN_src_backend_editor_backend__pyqtSlot()
    def suggest(self) -> None:
        """Translate the selected line with the selected engine; the result is put in the editor, not saved."""
        # ==============================================================================
        # INICIO: Bloque If de EditorBackend.suggest — self._locked or not self._selected or self._busy
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: self._locked or not self._selected or self._busy. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if self._locked or not self._selected or self._busy:
            return
        # ==============================================================================
        # FIN: Bloque If de EditorBackend.suggest — self._locked or not self._selected or self._busy
        # ==============================================================================
        row = self.store.get(self._selected['id'])
        # ==============================================================================
        # INICIO: Bloque If de EditorBackend.suggest — not row
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not row. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not row:
            return
        # ==============================================================================
        # FIN: Bloque If de EditorBackend.suggest — not row
        # ==============================================================================
        app = self.app
        app._refresh_active_translator()
        exe_path = app._project_path if app._tool_game_dir() == self._game_dir else LN_src_backend_editor_backend__os.path.dirname(self._game_dir)
        language = self._language

        # ==============================================================================
        # INICIO: Acción de soporte EditorBackend.suggest.job
        # FUNCIÓN: Implementación directa EditorBackend.suggest.job. Origen trazable: src/backend/editor_backend.py.
        # Secuencia del bloque: TranslationPipeline → pipeline.configure → TranslationEntry → app.translation_manager.bypass_cache → pipeline._translate_entries([entry]).get → pipeline._translate_entries.
        # ==============================================================================
        def job() -> Any:
            TranslationPipeline = LN_src_core_pipeline__TranslationPipeline
            TranslationEntry = LN_src_core_tl_parser__TranslationEntry
            pipeline = TranslationPipeline(app.config, app.translation_manager)
            pipeline.configure(game_exe_path=exe_path, target_language=language, source_language=app.config.translation_settings.source_language or 'auto', engine=app._selected_engine, use_proxy=app.config.proxy_settings.enabled)
            entry = TranslationEntry(original_text=row['original'], translated_text='', file_path=row['file_path'], line_number=row['line'], entry_type=row['kind'], translation_id='editor_suggestion')
            # ==============================================================================
            # INICIO: Bloque With de EditorBackend.suggest.job — app.translation_manager.bypass_cache()
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: app.translation_manager.bypass_cache(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            with app.translation_manager.bypass_cache():
                return pipeline._translate_entries([entry]).get('editor_suggestion', '')
            # ==============================================================================
            # FIN: Bloque With de EditorBackend.suggest.job — app.translation_manager.bypass_cache()
            # ==============================================================================
        # ==============================================================================
        # FIN: Acción de soporte EditorBackend.suggest.job
        # ==============================================================================
        entry_id = row['id']

        # ==============================================================================
        # INICIO: Acción de soporte EditorBackend.suggest.done
        # FUNCIÓN: Implementación directa EditorBackend.suggest.done. Origen trazable: src/backend/editor_backend.py.
        # Secuencia del bloque: self.store.get → self._replace_row → self.notify.emit → self.store.update → self._t.
        # ==============================================================================
        def done(text: Any) -> None:
            # ==============================================================================
            # INICIO: Bloque If de EditorBackend.suggest.done — not text or text == row['original']
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not text or text == row['original']. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if not text or text == row['original']:
                self.notify.emit('warning', self._t('editor_suggest_failed', 'No suggestion was returned.'))
                return
            # ==============================================================================
            # FIN: Bloque If de EditorBackend.suggest.done — not text or text == row['original']
            # ==============================================================================
            current = self.store.get(entry_id)
            # ==============================================================================
            # INICIO: Bloque If de EditorBackend.suggest.done — current and text == current['translated']
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: current and text == current['translated']. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if current and text == current['translated']:
                self.notify.emit('info', self._t('editor_suggest_same', 'The engine suggests the current translation.'))
                return
            # ==============================================================================
            # FIN: Bloque If de EditorBackend.suggest.done — current and text == current['translated']
            # ==============================================================================
            self._replace_row(self.store.update(entry_id, text))
        # ==============================================================================
        # FIN: Acción de soporte EditorBackend.suggest.done
        # ==============================================================================
        self._run(job, done)
