    @LN_src_backend_editor_backend__pyqtSlot(str, result=str)
    def pendingEngineProblem(self, engine: str) -> str:
        """Why *engine* cannot run now (missing key), or ""."""
        keys = self.app.config.api_keys
        # ==============================================================================
        # INICIO: Bloque If de EditorBackend.pendingEngineProblem — engine == 'deepl' and (not (getattr(keys, 'deepl_api_key', '') or '').strip())
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: engine == 'deepl' and (not (getattr(keys, 'deepl_api_key', '') or '').strip()). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if engine == 'deepl' and (not (getattr(keys, 'deepl_api_key', '') or '').strip()):
            return self._t('pending_need_deepl_key', 'Save a DeepL key first (field below).')
        # ==============================================================================
        # FIN: Bloque If de EditorBackend.pendingEngineProblem — engine == 'deepl' and (not (getattr(keys, 'deepl_api_key', '') or '').strip())
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de EditorBackend.pendingEngineProblem — engine == 'gemini' and (not (keys.gemini_api_key or '').strip())
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: engine == 'gemini' and (not (keys.gemini_api_key or '').strip()). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if engine == 'gemini' and (not (keys.gemini_api_key or '').strip()):
            return self._t('pending_need_gemini_key', 'Gemini needs an API key (Settings).')
        # ==============================================================================
        # FIN: Bloque If de EditorBackend.pendingEngineProblem — engine == 'gemini' and (not (keys.gemini_api_key or '').strip())
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de EditorBackend.pendingEngineProblem — engine == 'ai'
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: engine == 'ai'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if engine == 'ai':
            base = (getattr(self.app.config.translation_settings, 'openai_base_url', '') or '').lower()
            local = base.startswith('http://localhost') or base.startswith('http://127.')
            # ==============================================================================
            # INICIO: Bloque If de EditorBackend.pendingEngineProblem — not local and (not ((getattr(keys, 'deepseek_api_key', '') or '') or keys.openai_api_key))
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not local and (not ((getattr(keys, 'deepseek_api_key', '') or '') or keys.openai_api_key)). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if not local and (not ((getattr(keys, 'deepseek_api_key', '') or '') or keys.openai_api_key)):
                return self._t('pending_need_ai_key', 'OpenAI / DeepSeek needs an API key (Settings).')
            # ==============================================================================
            # FIN: Bloque If de EditorBackend.pendingEngineProblem — not local and (not ((getattr(keys, 'deepseek_api_key', '') or '') or keys.openai_api_key))
            # ==============================================================================
        # ==============================================================================
        # FIN: Bloque If de EditorBackend.pendingEngineProblem — engine == 'ai'
        # ==============================================================================
        return ''
