    def suggestedPackageUrl(self) -> str:
        """Ready-made destination next to the game: ``<game>_LinguaNova_<languages>.zip``."""
        import re
        from PyQt6.QtCore import QUrl
        project = getattr(self.app, '_project_path', '')
        if not project:
            return ''
        try:
            game = LN_src_core_sharing_translation_package__find_game_dir(project)
            languages, _other = LN_src_core_sharing_translation_package__language_folders(game / 'tl')
        except Exception:
            return ''
        root = game.parent
        stem = re.sub('[^\\w.-]+', '_', root.name).strip('._') or 'juego'
        name = '{}_LinguaNova_{}.zip'.format(stem, '_'.join(languages) or 'traducciones')
        return QUrl.fromLocalFile(str(root / name)).toString()
