# ==============================================================================
# INICIO: Acción de soporte setup_engines
# FUNCIÓN: Setup translation engines (Google always as fallback).
# Implementación directa setup_engines. Origen trazable: src/cli_main.py.
# Secuencia del bloque: LN_src_cli_main__ProxyManager → proxy_manager.configure_from_settings → LN_src_cli_main__TranslationManager → GoogleTranslator → translation_manager.add_translator → LN_src_cli_main__ENGINE_MAP.get → GeminiTranslator → t.set_fallback_translator → LN_src_cli_main__print_warning → getattr → DeepSeekTranslator → OpenAITranslator → BingTranslator → base_url.lower.
# ==============================================================================
def LN_src_cli_main__setup_engines(config: LN_src_cli_main__ConfigManager, engine_id: str):
    """Setup translation engines (Google always as fallback)."""
    proxy_manager = LN_src_cli_main__ProxyManager()
    proxy_manager.configure_from_settings(config.proxy_settings)
    translation_manager = LN_src_cli_main__TranslationManager(proxy_manager, config)
    GoogleTranslator = LN_src_core_translator__GoogleTranslator
    google = GoogleTranslator(proxy_manager=proxy_manager, config_manager=config)
    translation_manager.add_translator(LN_src_cli_main__TranslationEngine.GOOGLE, google)
    engine = LN_src_cli_main__ENGINE_MAP.get(engine_id, LN_src_cli_main__TranslationEngine.GOOGLE)
    # ==============================================================================
    # INICIO: Bloque If de setup_engines — engine == LN_src_cli_main__TranslationEngine.GOOGLE
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: engine == LN_src_cli_main__TranslationEngine.GOOGLE. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if engine == LN_src_cli_main__TranslationEngine.GOOGLE:
        return (config, translation_manager)
    # ==============================================================================
    # FIN: Bloque If de setup_engines — engine == LN_src_cli_main__TranslationEngine.GOOGLE
    # ==============================================================================
    # ==============================================================================
    # INICIO: Bloque Try de setup_engines — gestión de excepciones
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    try:
        # ==============================================================================
        # INICIO: Bloque If de setup_engines — engine == LN_src_cli_main__TranslationEngine.GEMINI
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: engine == LN_src_cli_main__TranslationEngine.GEMINI. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if engine == LN_src_cli_main__TranslationEngine.GEMINI:
            GeminiTranslator = LN_src_core_ai_translator__GeminiTranslator
            t = GeminiTranslator(api_key=config.api_keys.gemini_api_key or '', proxy_manager=proxy_manager, config_manager=config)
            t.set_fallback_translator(google)
            translation_manager.add_translator(LN_src_cli_main__TranslationEngine.GEMINI, t)
        # ==============================================================================
        # INICIO: Bloque If de setup_engines — engine == LN_src_cli_main__TranslationEngine.OPENAI
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: engine == LN_src_cli_main__TranslationEngine.OPENAI. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        elif engine == LN_src_cli_main__TranslationEngine.OPENAI:
            OpenAITranslator = LN_src_core_ai_translator__OpenAITranslator
            DeepSeekTranslator = LN_src_core_ai_translator__DeepSeekTranslator
            api_key = config.api_keys.openai_api_key or ''
            base_url = getattr(config.translation_settings, 'openai_base_url', '') or ''
            # ==============================================================================
            # INICIO: Bloque If de setup_engines — engine_id == 'deepseek' or 'deepseek' in base_url.lower()
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: engine_id == 'deepseek' or 'deepseek' in base_url.lower(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if engine_id == 'deepseek' or 'deepseek' in base_url.lower():
                t = DeepSeekTranslator(api_key=api_key, proxy_manager=proxy_manager, config_manager=config)
            else:
                t = OpenAITranslator(api_key=api_key, proxy_manager=proxy_manager, config_manager=config)
            # ==============================================================================
            # FIN: Bloque If de setup_engines — engine_id == 'deepseek' or 'deepseek' in base_url.lower()
            # ==============================================================================
            translation_manager.add_translator(LN_src_cli_main__TranslationEngine.OPENAI, t)
        # ==============================================================================
        # INICIO: Bloque If de setup_engines — engine == LN_src_cli_main__TranslationEngine.BING
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: engine == LN_src_cli_main__TranslationEngine.BING. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        elif engine == LN_src_cli_main__TranslationEngine.BING:
            BingTranslator = LN_src_core_translator__BingTranslator
            t = BingTranslator(proxy_manager=proxy_manager, config_manager=config)
            t.set_fallback_translator(google)
            translation_manager.add_translator(LN_src_cli_main__TranslationEngine.BING, t)
        # ==============================================================================
        # FIN: Bloque If de setup_engines — engine == LN_src_cli_main__TranslationEngine.BING
        # ==============================================================================
        # ==============================================================================
        # FIN: Bloque If de setup_engines — engine == LN_src_cli_main__TranslationEngine.OPENAI
        # ==============================================================================
        # ==============================================================================
        # FIN: Bloque If de setup_engines — engine == LN_src_cli_main__TranslationEngine.GEMINI
        # ==============================================================================
    except Exception as e:
        LN_src_cli_main__print_warning(f'Engine {engine_id} setup failed, using Google fallback: {e}')
    # ==============================================================================
    # FIN: Bloque Try de setup_engines — gestión de excepciones
    # ==============================================================================
    return (config, translation_manager)
# ==============================================================================
# FIN: Acción de soporte setup_engines
# ==============================================================================

# ==============================================================================
# INICIO: Acción de soporte run_translate_command
# FUNCIÓN: Run translation pipeline.
# Implementación directa run_translate_command. Origen trazable: src/cli_main.py.
# Secuencia del bloque: LN_src_cli_main__print_banner → unwrap_mac_app → LN_src_cli_main__ConfigManager → getattr → LN_src_cli_main___apply_ai_overrides → config.normalize_renpy_language_code → LN_src_cli_main___flag_or → bool → LN_src_cli_main__print_section_header → LN_src_cli_main__print_key_value → LN_src_cli_main__setup_engines → LN_src_cli_main__console.print → LN_src_cli_main__ENGINE_MAP.get → LN_src_cli_main__TranslationPipeline → LN_src_cli_main__CliHandler → pipeline.configure → PipelineWorker → worker.start → app.exec → worker.wait → LN_src_cli_main__os.path.abspath → LN_src_cli_main__print_error → LN_src_cli_main__load_config_override → override.items → LN_src_cli_main__print_warning → LN_src_cli_main___looks_like_tl_folder → LN_src_cli_main__QCoreApplication.instance → LN_src_cli_main__QCoreApplication → LN_src_cli_main__os.path.exists → config.get_ui_text → hasattr → isinstance → values.items → setattr.
# ==============================================================================
def LN_src_cli_main__run_translate_command(args) -> int:
    """Run translation pipeline."""
    LN_src_cli_main__print_banner()
    input_path = LN_src_cli_main__os.path.abspath(args.input_path) if args.input_path else None
    # ==============================================================================
    # INICIO: Bloque If de run_translate_command — not input_path or not LN_src_cli_main__os.path.exists(input_path)
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not input_path or not LN_src_cli_main__os.path.exists(input_path). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if not input_path or not LN_src_cli_main__os.path.exists(input_path):
        LN_src_cli_main__print_error(f'Path not found: {input_path}')
        return 1
    # ==============================================================================
    # FIN: Bloque If de run_translate_command — not input_path or not LN_src_cli_main__os.path.exists(input_path)
    # ==============================================================================
    unwrap_mac_app = LN_src_utils_path_manager__unwrap_mac_app
    input_path = unwrap_mac_app(input_path)
    config = LN_src_cli_main__ConfigManager()
    config_path = getattr(args, 'config', None)
    # ==============================================================================
    # INICIO: Bloque If de run_translate_command — config_path
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: config_path. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if config_path:
        # ==============================================================================
        # INICIO: Bloque If de run_translate_command — not LN_src_cli_main__os.path.exists(config_path)
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not LN_src_cli_main__os.path.exists(config_path). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not LN_src_cli_main__os.path.exists(config_path):
            LN_src_cli_main__print_error(f'Config file not found: {config_path}')
            return 1
        # ==============================================================================
        # FIN: Bloque If de run_translate_command — not LN_src_cli_main__os.path.exists(config_path)
        # ==============================================================================
        override = LN_src_cli_main__load_config_override(config_path)
        # ==============================================================================
        # INICIO: Bloque For de run_translate_command — override.items()
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: override.items(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for section, values in override.items():
            # ==============================================================================
            # INICIO: Bloque If de run_translate_command — hasattr(config, section) and isinstance(values, dict)
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: hasattr(config, section) and isinstance(values, dict). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if hasattr(config, section) and isinstance(values, dict):
                # ==============================================================================
                # INICIO: Bloque For de run_translate_command — values.items()
                # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: values.items(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
                # ==============================================================================
                for key, val in values.items():
                    setattr(getattr(config, section), key, val)
                # ==============================================================================
                # FIN: Bloque For de run_translate_command — values.items()
                # ==============================================================================
            # ==============================================================================
            # FIN: Bloque If de run_translate_command — hasattr(config, section) and isinstance(values, dict)
            # ==============================================================================
        # ==============================================================================
        # FIN: Bloque For de run_translate_command — override.items()
        # ==============================================================================
    # ==============================================================================
    # FIN: Bloque If de run_translate_command — config_path
    # ==============================================================================
    engine_id = args.engine
    ts = config.translation_settings
    LN_src_cli_main___apply_ai_overrides(config, engine_id, args)
    target_lang = config.normalize_renpy_language_code(args.target_lang)
    source_lang = args.source_lang or 'auto'
    # ==============================================================================
    # ==============================================================================
    ts.target_language = target_lang
    ts.source_language = source_lang
    ts.selected_engine = engine_id
    auto_unren = LN_src_cli_main___flag_or(args, 'extract_rpa', getattr(config.app_settings, 'unren_auto_download', True))
    include_rpyc = LN_src_cli_main___flag_or(args, 'rpyc', getattr(ts, 'enable_rpyc_reader', True))
    include_deep_scan = bool(getattr(args, 'deep_scan', False)) or bool(getattr(ts, 'enable_deep_scan', False))
    # ==============================================================================
    # INICIO: Bloque If de run_translate_command — include_deep_scan
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: include_deep_scan. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if include_deep_scan:
        ts.enable_deep_scan = True
    # ==============================================================================
    # FIN: Bloque If de run_translate_command — include_deep_scan
    # ==============================================================================
    use_proxy = bool(getattr(config.proxy_settings, 'enabled', False))
    ts.activate_language_on_launch = LN_src_cli_main___flag_or(args, 'language_init', getattr(ts, 'activate_language_on_launch', True))
    is_tl_mode = bool(getattr(args, 'tl', False)) or LN_src_cli_main___looks_like_tl_folder(input_path)
    LN_src_cli_main__print_section_header('Translation Settings', '⚙')
    LN_src_cli_main__print_key_value('Input', input_path, '📁')
    LN_src_cli_main__print_key_value('Mode', 'existing tl/ folder' if is_tl_mode else 'full game', '🧭')
    LN_src_cli_main__print_key_value('Engine', engine_id, '⚡')
    LN_src_cli_main__print_key_value('Source', source_lang, '🌍')
    LN_src_cli_main__print_key_value('Target', target_lang, '🌍')
    # ==============================================================================
    # INICIO: Bloque If de run_translate_command — not is_tl_mode
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not is_tl_mode. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if not is_tl_mode:
        LN_src_cli_main__print_key_value('Extract .rpa', 'on' if auto_unren else 'off', '📦')
        LN_src_cli_main__print_key_value('Read .rpyc', 'on' if include_rpyc else 'off', '🧩')
    # ==============================================================================
    # FIN: Bloque If de run_translate_command — not is_tl_mode
    # ==============================================================================
    LN_src_cli_main__print_key_value('Integrate language into game menu', 'on' if ts.activate_language_on_launch else 'off (tl/ files only)', '🏳')
    # ==============================================================================
    # INICIO: Bloque If de run_translate_command — include_deep_scan
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: include_deep_scan. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if include_deep_scan:
        LN_src_cli_main__print_key_value('Deep scan', 'on', '🔍')
    # ==============================================================================
    # FIN: Bloque If de run_translate_command — include_deep_scan
    # ==============================================================================
    config, translation_manager = LN_src_cli_main__setup_engines(config, engine_id)
    LN_src_cli_main__print_section_header('Running Translation', '🚀')
    LN_src_cli_main__console.print()
    engine = LN_src_cli_main__ENGINE_MAP.get(engine_id, LN_src_cli_main__TranslationEngine.GOOGLE)
    pipeline = LN_src_cli_main__TranslationPipeline(config, translation_manager)
    handler = LN_src_cli_main__CliHandler(pipeline, verbose=getattr(args, 'verbose', False))
    pipeline.configure(game_exe_path=input_path, target_language=target_lang, source_language=source_lang, engine=engine, auto_unren=auto_unren, use_proxy=use_proxy, include_deep_scan=include_deep_scan, include_rpyc=include_rpyc, is_tl_mode=is_tl_mode)
    PipelineWorker = LN_src_core_pipeline__PipelineWorker
    worker = PipelineWorker(pipeline)
    worker.start()
    app = LN_src_cli_main__QCoreApplication.instance() or LN_src_cli_main__QCoreApplication(LN_src_cli_main__sys.argv)
    app.exec()
    worker.wait(5000)
    return 0 if handler.succeeded else 1
# ==============================================================================
# FIN: Acción de soporte run_translate_command
# ==============================================================================

