# ==============================================================================
# INICIO: Acción de soporte _looks_like_tl_folder
# FUNCIÓN: A tl/ or tl/<language> folder (TL mode), not a game folder.
# Implementación directa _looks_like_tl_folder. Origen trazable: src/cli_main.py.
# Secuencia del bloque: LN_src_cli_main__os.path.isdir → p.lower → LN_src_cli_main__os.path.normpath(path).split → len → LN_src_cli_main__os.path.normpath.
# ==============================================================================
def LN_src_cli_main___looks_like_tl_folder(path: str) -> bool:
    """A tl/ or tl/<language> folder (TL mode), not a game folder."""
    # ==============================================================================
    # INICIO: Bloque If de _looks_like_tl_folder — not LN_src_cli_main__os.path.isdir(path)
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not LN_src_cli_main__os.path.isdir(path). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if not LN_src_cli_main__os.path.isdir(path):
        return False
    # ==============================================================================
    # FIN: Bloque If de _looks_like_tl_folder — not LN_src_cli_main__os.path.isdir(path)
    # ==============================================================================
    parts = [p.lower() for p in LN_src_cli_main__os.path.normpath(path).split(LN_src_cli_main__os.sep)]
    # ==============================================================================
    # INICIO: Bloque If de _looks_like_tl_folder — parts[-1] == 'tl'
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: parts[-1] == 'tl'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if parts[-1] == 'tl':
        return True
    # ==============================================================================
    # FIN: Bloque If de _looks_like_tl_folder — parts[-1] == 'tl'
    # ==============================================================================
    return len(parts) >= 2 and parts[-2] == 'tl'
# ==============================================================================
# FIN: Acción de soporte _looks_like_tl_folder
# ==============================================================================

# ==============================================================================
# INICIO: Acción de soporte _apply_ai_overrides
# FUNCIÓN: --api-key / --model / --base-url, plus the usual *_API_KEY variables.
# Implementación directa _apply_ai_overrides. Origen trazable: src/cli_main.py.
# Secuencia del bloque: getattr → LN_src_cli_main__os.environ.get.
# ==============================================================================
def LN_src_cli_main___apply_ai_overrides(config: LN_src_cli_main__ConfigManager, engine_id: str, args) -> None:
    """--api-key / --model / --base-url, plus the usual *_API_KEY variables."""
    ts, keys = (config.translation_settings, config.api_keys)
    api_key = getattr(args, 'api_key', None)
    model = getattr(args, 'model', None)
    base_url = getattr(args, 'base_url', None)
    # ==============================================================================
    # INICIO: Bloque If de _apply_ai_overrides — engine_id == 'gemini'
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: engine_id == 'gemini'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if engine_id == 'gemini':
        keys.gemini_api_key = api_key or keys.gemini_api_key or LN_src_cli_main__os.environ.get('GEMINI_API_KEY', '')
        # ==============================================================================
        # INICIO: Bloque If de _apply_ai_overrides — model
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: model. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if model:
            ts.gemini_model = model
        # ==============================================================================
        # FIN: Bloque If de _apply_ai_overrides — model
        # ==============================================================================
    # ==============================================================================
    # INICIO: Bloque If de _apply_ai_overrides — engine_id in ('openai', 'deepseek')
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: engine_id in ('openai', 'deepseek'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    elif engine_id in ('openai', 'deepseek'):
        env_name = 'DEEPSEEK_API_KEY' if engine_id == 'deepseek' else 'OPENAI_API_KEY'
        keys.openai_api_key = api_key or keys.openai_api_key or LN_src_cli_main__os.environ.get(env_name, '')
        # ==============================================================================
        # INICIO: Bloque If de _apply_ai_overrides — model
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: model. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if model:
            ts.openai_model = model
        # ==============================================================================
        # FIN: Bloque If de _apply_ai_overrides — model
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque If de _apply_ai_overrides — base_url
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: base_url. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if base_url:
            ts.openai_base_url = base_url
        # ==============================================================================
        # FIN: Bloque If de _apply_ai_overrides — base_url
        # ==============================================================================
    # ==============================================================================
    # FIN: Bloque If de _apply_ai_overrides — engine_id in ('openai', 'deepseek')
    # ==============================================================================
    # ==============================================================================
    # FIN: Bloque If de _apply_ai_overrides — engine_id == 'gemini'
    # ==============================================================================
# ==============================================================================
# FIN: Acción de soporte _apply_ai_overrides
# ==============================================================================

# ==============================================================================
# INICIO: Acción de soporte select_engine
# FUNCIÓN: Implementación directa select_engine. Origen trazable: src/cli_main.py.
# Secuencia del bloque: LN_src_cli_main__print_menu → icons.append → options.append.
# ==============================================================================
def LN_src_cli_main__select_engine() -> str:
    options, icons = ([], [])
    # ==============================================================================
    # INICIO: Bloque For de select_engine — LN_src_cli_main__ENGINES
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_src_cli_main__ENGINES. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    for code, name, icon, desc in LN_src_cli_main__ENGINES:
        # ==============================================================================
        # INICIO: Bloque If de select_engine — LN_src_cli_main__RICH_AVAILABLE
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_src_cli_main__RICH_AVAILABLE. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if LN_src_cli_main__RICH_AVAILABLE:
            options.append(f'{name}  [{LN_src_cli_main__BRAND_DIM}]{desc}[/]')
        else:
            options.append(f'{name} — {desc}')
        # ==============================================================================
        # FIN: Bloque If de select_engine — LN_src_cli_main__RICH_AVAILABLE
        # ==============================================================================
        icons.append(icon)
    # ==============================================================================
    # FIN: Bloque For de select_engine — LN_src_cli_main__ENGINES
    # ==============================================================================
    choice = LN_src_cli_main__print_menu('Select Translation Engine', options, show_back=True, icons=icons)
    # ==============================================================================
    # INICIO: Bloque If de select_engine — choice == 0
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: choice == 0. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if choice == 0:
        return ''
    # ==============================================================================
    # FIN: Bloque If de select_engine — choice == 0
    # ==============================================================================
    return LN_src_cli_main__ENGINES[choice - 1][0]
# ==============================================================================
# FIN: Acción de soporte select_engine
# ==============================================================================

# ==============================================================================
# INICIO: Acción de soporte select_language
# FUNCIÓN: Implementación directa select_language. Origen trazable: src/cli_main.py.
# Secuencia del bloque: options.append → icons.append → LN_src_cli_main__print_menu → LN_src_cli_main__get_user_input → len.
# ==============================================================================
def LN_src_cli_main__select_language(title: str='Select Target Language') -> str:
    options, icons = ([], [])
    # ==============================================================================
    # INICIO: Bloque For de select_language — LN_src_cli_main__LANGUAGES
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_src_cli_main__LANGUAGES. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    for code, name, icon in LN_src_cli_main__LANGUAGES:
        options.append(f'{name} ({code})')
        icons.append(icon)
    # ==============================================================================
    # FIN: Bloque For de select_language — LN_src_cli_main__LANGUAGES
    # ==============================================================================
    options.append('Other (enter manually)')
    icons.append('⌨')
    choice = LN_src_cli_main__print_menu(title, options, show_back=True, icons=icons)
    # ==============================================================================
    # INICIO: Bloque If de select_language — choice == 0
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: choice == 0. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if choice == 0:
        return ''
    # ==============================================================================
    # FIN: Bloque If de select_language — choice == 0
    # ==============================================================================
    # ==============================================================================
    # INICIO: Bloque If de select_language — choice <= len(LN_src_cli_main__LANGUAGES)
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: choice <= len(LN_src_cli_main__LANGUAGES). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if choice <= len(LN_src_cli_main__LANGUAGES):
        return LN_src_cli_main__LANGUAGES[choice - 1][0]
    # ==============================================================================
    # FIN: Bloque If de select_language — choice <= len(LN_src_cli_main__LANGUAGES)
    # ==============================================================================
    return LN_src_cli_main__get_user_input('Language code', 'es')
# ==============================================================================
# FIN: Acción de soporte select_language
# ==============================================================================

