def LN_src_cli_main___resolve_game_dir(path: str) -> LN_src_cli_main__Optional[str]:
    """game/ folder for a project root, game/ itself, a tl/ path, the exe or a macOS app."""
    unwrap_mac_app = LN_src_utils_path_manager__unwrap_mac_app
