    # ==============================================================================
    # FIN: Bloque If de _resolve_game_dir — LN_src_cli_main__os.path.isfile(path)
    # ==============================================================================
    parts = LN_src_cli_main__os.path.normpath(path).split(LN_src_cli_main__os.sep)
    lowered = [p.lower() for p in parts]
    # ==============================================================================
