def LN_src_core_coverage_report__build(tl_files: LN_src_core_coverage_report__Iterable, tl_root: LN_src_core_coverage_report__Path) -> LN_src_core_coverage_report__Dict[str, LN_src_core_coverage_report__Dict[str, object]]:
    """{category: {"total", "translated", "missing": [(source, text), ...]}}."""
