# ==============================================================================
def LN_src_core_coverage_report__render(report: LN_src_core_coverage_report__Dict[str, LN_src_core_coverage_report__Dict[str, object]], language: str, ui: str='en') -> str:
    text = LN_src_core_coverage_report__TEXT.get(ui, LN_src_core_coverage_report__TEXT['en'])
    lines = [text['title'], '{}: {}'.format(text['language'], language), '']
    done = total = 0
    # ==============================================================================
    # INICIO: Bloque For de render — LN_src_core_coverage_report__CATEGORIES
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_src_core_coverage_report__CATEGORIES. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    for name in LN_src_core_coverage_report__CATEGORIES:
        row = report[name]
        # ==============================================================================
        # INICIO: Bloque If de render — not row['total']
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not row['total']. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not row['total']:
            continue
        # ==============================================================================
        # FIN: Bloque If de render — not row['total']
        # ==============================================================================
        done += row['translated']
        total += row['total']
        lines.append(text['header'].format(name=text[name], done=row['translated'], total=row['total'], pct=LN_src_core_coverage_report___pct(row['translated'], row['total'])))
    # ==============================================================================
    # FIN: Bloque For de render — LN_src_core_coverage_report__CATEGORIES
    # ==============================================================================
    lines.append(text['header'].format(name=text['total'], done=done, total=total, pct=LN_src_core_coverage_report___pct(done, total)))
    # ==============================================================================
    # INICIO: Bloque For de render — LN_src_core_coverage_report__CATEGORIES
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_src_core_coverage_report__CATEGORIES. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    for name in LN_src_core_coverage_report__CATEGORIES:
        missing = report[name]['missing']
        # ==============================================================================
        # INICIO: Bloque If de render — missing
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: missing. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if missing:
            lines += ['', '{} - {}:'.format(text[name], text['missing'])]
            lines += ['  {}: {}'.format(source, original.replace('\n', ' ')[:160]) for source, original in missing]
        # ==============================================================================
        # FIN: Bloque If de render — missing
        # ==============================================================================
    # ==============================================================================
    # FIN: Bloque For de render — LN_src_core_coverage_report__CATEGORIES
    # ==============================================================================
    return '\n'.join(lines) + '\n'
