# Secuencia del bloque: template.replace → LN_src_core_delivery_resources__json.dumps → sorted.
# ==============================================================================
def LN_src_core_delivery_resources__render_resource_filter() -> str:
    template = '# SPDX-License-Identifier: GPL-3.0-or-later\n# LinguaNova: keeps its font folders out of the game\'s language list.\n# Font files, paths and translate-python font blocks remain available.\n\ninit -999 python:\n    # Python\'s own functions, kept apart from the game\'s names\n    # (a game may call a character or variable "set" or "getattr").\n    import sys as _lntl_sys\n    _lntl_builtins = _lntl_sys.modules.get("__builtin__") or _lntl_sys.modules["builtins"]\n    _lntl_getattr = _lntl_builtins.getattr\n    _lntl_set = _lntl_builtins.set\n    _lntl_resource_folders = _lntl_set(__LNTL_RESOURCES__)\n    if not _lntl_getattr(renpy.known_languages, \'_lntl_resource_filter\', False):\n        _lntl_original_known_languages = renpy.known_languages\n\n        def _lntl_known_languages():\n            return _lntl_set(code for code in _lntl_original_known_languages()\n                       if code and not code.startswith(\'.\') and code.lower() not in _lntl_resource_folders)\n\n        _lntl_known_languages._lntl_resource_filter = True\n        renpy.known_languages = _lntl_known_languages\n'
    return template.replace('__LNTL_RESOURCES__', LN_src_core_delivery_resources__json.dumps(sorted(LN_src_core_delivery_resources__RESOURCE_FOLDERS)))
# ==============================================================================
# FIN: Acción de soporte render_resource_filter
