# ==============================================================================
def LN_src_core_delivery_package__plan_fonts(game_dir: str, languages) -> LN_src_core_delivery_package__Dict[str, list]:
    """{tl folder: [game font file names to swap while it is active]}."""
    pass
    game_fonts = LN_src_core_delivery_fonts__game_fonts(LN_src_core_delivery_package__Path(game_dir))
    # ==============================================================================
    # INICIO: Bloque If de plan_fonts — not game_fonts
