    # ==============================================================================
    if not game_fonts:
        return {}
    # ==============================================================================
    # FIN: Bloque If de plan_fonts — not game_fonts
    # ==============================================================================
    covered = LN_src_core_delivery_fonts__coverage(game_fonts)
    needed = {folder: LN_src_core_delivery_fonts__language_letters(LN_src_core_delivery_package__Path(game_dir) / 'tl' / folder) for folder in languages}
    return LN_src_core_delivery_fonts__font_gaps(covered, needed)
