# ==============================================================================
# INICIO: Acción de soporte write_language_files
# FUNCIÓN: Escribe game/zz_linguanova/languages/<carpeta>.json para cada idioma instalado
# (nombre propio y fuentes del juego que no pueden dibujarlo) y borra los de idiomas que
# ya no están. El script del juego los lee al arrancar, así que los paquetes se suman.
# Origen trazable: src/core/delivery/package.py.
# ==============================================================================
LN_src_core_delivery_package__LANGUAGES_DIR = LN_src_core_delivery_package__DELIVERY_DIR + '/languages'


def LN_src_core_delivery_package___menu_name(game_dir: str, folder: str) -> str:
    """Name shown in the game's language menu: the language in itself ("Español").

    A folder with an unusual name ("traduccion_fan") is named after the language
    its translation is written in, so the menu never shows the folder name.
    """
    if LN_src_utils_languages__find(folder) is None:
        try:
            game = LN_src_core_delivery_package__Path(game_dir)
            for language in LN_src_utils_languages__LANGUAGES:
                if any((p.name == folder for p in LN_src_ui_mod_scanner__matching_tl_folders(game, language.folder))):
                    return language.native
        except Exception as exc:
            LN_src_core_delivery_package__logger.debug('Language of tl/%s not detected: %s', folder, exc)
    return LN_src_core_delivery_package___own_name(folder)

def LN_src_core_delivery_package__write_language_files(game_dir: str, languages, gaps) -> int:
    """One small JSON per installed language; returns how many files changed."""
    import json
    save_text_safely = LN_src_utils_encoding__save_text_safely
    folder = LN_src_core_delivery_package__Path(game_dir) / LN_src_core_delivery_package__LANGUAGES_DIR
    folder.mkdir(parents=True, exist_ok=True)
    changed = 0
    for language in languages:
        data = {'folder': language, 'label': LN_src_core_delivery_package___menu_name(game_dir, language), 'font_gaps': sorted(gaps.get(language, []))}
        content = json.dumps(data, ensure_ascii=False, indent=2, sort_keys=True) + '\n'
        path = folder / (language + '.json')
        try:
            previous = path.read_text(encoding='utf-8')
        except (FileNotFoundError, UnicodeDecodeError):
            previous = None
        if previous != content:
            if not save_text_safely(path, content, encoding='utf-8', newline='\n'):
                raise OSError('Could not write ' + str(path))
            changed += 1
    for path in folder.glob('*.json'):
        if path.stem not in languages:
            path.unlink()
            changed += 1
    return changed
# ==============================================================================
# FIN: Acción de soporte write_language_files
# ==============================================================================

