def LN_src_core_delivery_package__install(game_dir: str, config=None) -> LN_src_core_delivery_package__Dict[str, object]:
    """Write game/zz_linguanova/ for every language installed in tl/."""
    save_text_safely = LN_src_utils_encoding__save_text_safely
    pass
