    validate = LN_src_core_delivery_validate__validate
    sdk_path = str(getattr(getattr(config, 'app_settings', None), 'renpy_sdk_path', '') or '')
    check = validate(content, LN_src_core_delivery_package__SCRIPT_FILE, required=('screen _lntl_preferences_row():',), sdk_path=sdk_path)
    path = root / LN_src_core_delivery_package__SCRIPT_FILE
