def LN_src_core_marked_strings__scan_source(source: str, first_line: int=1) -> LN_src_core_marked_strings__Iterator[LN_src_core_marked_strings__Tuple[str, int, bool]]:
    """Yield (text, line number, is_character_name) for every marked string."""
