def LN_src_core_marked_strings__worth_translating(text: str) -> bool:
    """False only where a translation cannot help (no letters, date formats,
    identifiers, paths). Everything else the author marked is translated."""
    core = LN_src_core_marked_strings___TAG_OR_VAR_RE.sub('', text or '').strip()
    # ==============================================================================
    # INICIO: Bloque If de worth_translating — not any((ch.isalpha() for ch in core))
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not any((ch.isalpha() for ch in core)). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if not any((ch.isalpha() for ch in core)):
        return False
    # ==============================================================================
    # FIN: Bloque If de worth_translating — not any((ch.isalpha() for ch in core))
    # ==============================================================================
    # ==============================================================================
    # INICIO: Bloque If de worth_translating — len(LN_src_core_marked_strings___STRFTIME_RE.findall(text)) >= 2
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: len(LN_src_core_marked_strings___STRFTIME_RE.findall(text)) >= 2. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if len(LN_src_core_marked_strings___STRFTIME_RE.findall(text)) >= 2:
        return False
    # ==============================================================================
    # FIN: Bloque If de worth_translating — len(LN_src_core_marked_strings___STRFTIME_RE.findall(text)) >= 2
    # ==============================================================================
    # ==============================================================================
    # INICIO: Bloque If de worth_translating — LN_src_core_marked_strings___IDENTIFIER_RE.match(core) or LN_src_core_marked_strings___PATH_OR_URL_RE.match(core)
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_src_core_marked_strings___IDENTIFIER_RE.match(core) or LN_src_core_marked_strings___PATH_OR_URL_RE.match(core). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if LN_src_core_marked_strings___IDENTIFIER_RE.match(core) or LN_src_core_marked_strings___PATH_OR_URL_RE.match(core):
        return False
    # ==============================================================================
    # FIN: Bloque If de worth_translating — LN_src_core_marked_strings___IDENTIFIER_RE.match(core) or LN_src_core_marked_strings___PATH_OR_URL_RE.match(core)
    # ==============================================================================
    return True
