def LN_src_core_sharing_translation_package__find_game_dir(project: str) -> LN_src_core_sharing_translation_package__Path:
    """``game/`` folder for a project folder, launcher, ``game/`` itself or ``tl/``."""
    path = LN_src_core_sharing_translation_package__Path(project).expanduser()
    # ==============================================================================
    # INICIO: Bloque If de find_game_dir — path.is_file()
