# ==============================================================================
# INICIO: Acción de soporte _translated_by_linguanova
# FUNCIÓN: True si LinguaNova tradujo esta carpeta (archivos con su marca, manifiestos de salida o
# informe de cobertura) o si la carpeta no tiene traducción de nadie más; False cuando la
# traducción es ajena y LinguaNova solo dejó ahí los datos del MOD.
# ==============================================================================
def LN_src_core_sharing_translation_package___translated_by_linguanova(tl: LN_src_core_sharing_translation_package__Path, folder: LN_src_core_sharing_translation_package__Path) -> bool:
    manifests = folder / '.linguanova'
    if manifests.is_dir() and any(manifests.glob('linguanova_output_*.json')):
        return True
    if (tl / '.diagnostics' / folder.name / 'coverage_by_category.json').is_file():
        return True
    scripts = [p for p in folder.rglob('*.rpy') if p.is_file() and (not p.name.lower().startswith('linguanova_'))]
    if any((LN_src_core_bounded_output__is_owned(p) for p in scripts)):
        return True
    return not scripts
