# FIN: Acción de soporte _translated_by_linguanova
# ==============================================================================

# ==============================================================================
# INICIO: Acción de soporte inventory
# FUNCIÓN: Archivos que tendrá el paquete, con tamaño y SHA-256: cada idioma hecho con
# LinguaNova completo (incluidos los archivos de Ren'Py de ese idioma) y los scripts y
# carpetas de fuentes que LinguaNova añade a game/. Las rutas son las del juego.
# Origen trazable: src/core/sharing/translation_package.py.
# ==============================================================================
def LN_src_core_sharing_translation_package__inventory(project: str, cancelled: LN_src_core_sharing_translation_package__Optional[LN_src_core_sharing_translation_package__Cancelled]=None) -> LN_src_core_sharing_translation_package__Dict[str, object]:
    """Files the package would contain, with size and SHA-256."""
    game = LN_src_core_sharing_translation_package__find_game_dir(project)
    tl = game / 'tl'
    if not tl.is_dir():
        raise LN_src_core_sharing_translation_package__PackageError('El juego no tiene carpeta game/tl con traducciones.')
    languages, other = LN_src_core_sharing_translation_package__language_folders(tl)
    mod_root = game / LN_src_core_constants__DELIVERY_DIR / 'mod'
    mod_languages = sorted((p.name for p in mod_root.iterdir() if (p / 'linguanova_mod_hook_data.json').is_file())) if mod_root.is_dir() else []
    if not languages and (not mod_languages):
        raise LN_src_core_sharing_translation_package__PackageError('game/tl no contiene traducciones hechas con LinguaNova.')
    candidates = []
    for language in languages:
        folder = tl / language
        files_here = sorted((p for p in folder.rglob('*') if p.is_file()))
        if not LN_src_core_sharing_translation_package___translated_by_linguanova(tl, folder):
            # The translation in this folder was made by someone else; LinguaNova
            # only added its MOD data. Share only what LinguaNova wrote.
            files_here = [p for p in files_here if p.name.lower().startswith('linguanova_') or '.linguanova' in p.relative_to(folder).parts]
        candidates += files_here
    candidates += sorted((p for p in game.glob('*.rpy') if LN_src_core_sharing_translation_package__is_linguanova_generated_script(p.name) or p.name.startswith('linguanova_mod_')))
    for folder in LN_src_core_sharing_translation_package___EXTRA_FOLDERS:
        if (game / folder).is_dir():
            candidates += sorted((p for p in (game / folder).rglob('*') if p.is_file()))
    files = []
    seen = set()
    for path in candidates:
        LN_src_core_sharing_translation_package___check_cancel(cancelled)
        relative = path.relative_to(game)
        if LN_src_core_sharing_translation_package___skip(relative):
            continue
        if path.is_symlink():
            raise LN_src_core_sharing_translation_package__PackageError(f'El paquete no admite enlaces simbólicos: {relative.as_posix()}')
        name = 'game/' + relative.as_posix()
        folded = name.casefold()
        if folded in seen:
            raise LN_src_core_sharing_translation_package__PackageError(f'Dos archivos solo se diferencian en mayúsculas: {name}')
        seen.add(folded)
        files.append({'path': name, 'size': path.stat().st_size, 'sha256': LN_src_core_sharing_translation_package___sha256(path)})
    skipped = [name for name in other if name.lower() != 'none' and name not in mod_languages]
    return {'game_dir': str(game), 'files': files, 'languages': sorted(set(languages) | set(mod_languages)), 'skipped_languages': skipped}
