# ==============================================================================
def LN_src_core_trial_workflow__prepared_record(config, project, language, verify=True):
    """Launch gate: require this game's current-language validated operation."""
    _, path, lock = LN_src_core_trial_workflow__operation_paths(config.data_dir, project, language)
    data = LN_src_core_trial_workflow__load_record(path)
    # ==============================================================================
    # INICIO: Bloque If de prepared_record — data.get('status') not in {'ready', 'partial'} or not data.get('stats', {}).get('prepared') or lock.exists()
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: data.get('status') not in {'ready', 'partial'} or not data.get('stats', {}).get('prepared') or lock.exists(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if data.get('status') not in {'ready', 'partial'} or not data.get('stats', {}).get('prepared') or lock.exists():
        return {}
    # ==============================================================================
    # FIN: Bloque If de prepared_record — data.get('status') not in {'ready', 'partial'} or not data.get('stats', {}).get('prepared') or lock.exists()
    # ==============================================================================
    # ==============================================================================
