    block = f'''\ninit -999 python:\n    # LinguaNova: Python's own functions, kept apart from the game's names\n    # (a game may call a character or variable "min", "max", "len"...).\n    import sys as _lnfi_sys\n    _lnfi_builtins = _lnfi_sys.modules.get("__builtin__") or _lnfi_sys.modules["builtins"]\n    _lnfi_getattr = _lnfi_builtins.getattr\n    _lnfi_hasattr = _lnfi_builtins.hasattr\n    _lnfi_setattr = _lnfi_builtins.setattr\n    if not _lnfi_hasattr(renpy.store, "linguanova_fonts"):\n        renpy.store.linguanova_fonts = {{}}\n    if not _lnfi_hasattr(renpy.store, "orig_get_font"):\n        renpy.store.orig_get_font = renpy.text.font.get_font\n        def linguanova_get_font_hook(*args, **kwargs):\n            if not args:\n                return renpy.store.orig_get_font(*args, **kwargs)\n            current_lang = _preferences.language\n            fs = renpy.store.linguanova_fonts\n            if current_lang in fs and args[0] != fs[current_lang].get("Default", ""):\n                args = (fs[current_lang]["Default"],) + args[1:]\n            return renpy.store.orig_get_font(*args, **kwargs)\n        renpy.text.font.get_font = linguanova_get_font_hook\n\ntranslate {lang_code} python:\n    if not _lnfi_hasattr(renpy.store, "linguanova_fonts"):\n        renpy.store.linguanova_fonts = {{}}\n    renpy.store.linguanova_fonts["{lang_code}"] = {{"Default": "{font_rel}"}}\n    for _f in {list(LN_src_tools_font_injector__GUI_FONT_FIELDS)}:\n        try:\n            if _lnfi_hasattr(gui, _f): _lnfi_setattr(gui, _f, "{font_rel}")\n        except Exception: pass\n    for _s in {list(LN_src_tools_font_injector__STYLE_FONT_NAMES)}:\n        try:\n            _st = _lnfi_getattr(style, _s, None)\n            if _st: _st.font = "{font_rel}"\n        except Exception: pass\n{rtl_snippet}    try:\n        if _lnfi_hasattr(renpy.text.font, "font_cache"): renpy.text.font.font_cache.clear()\n        if _lnfi_hasattr(renpy.text.font, "font_names"): renpy.text.font.font_names.clear()\n    except Exception: pass\n    style.rebuild()\n    try: renpy.restart_interaction()\n    except Exception: pass\n'''
