# ==============================================================================
def LN_src_ui_mod_quality__validate_translation(source_text: str, translated: str, target: LN_src_ui_mod_quality__ModLanguage, source: LN_src_ui_mod_quality__Optional[LN_src_ui_mod_quality__ModLanguage]=None) -> LN_src_ui_mod_quality__QualityVerdict:
    """Apply the MOD acceptance policy; never raises for odd input."""
    evidence = {'target': target.api, 'source': source.api if source else 'auto'}

    # ==============================================================================
    # INICIO: Acción de soporte validate_translation.decision
    # FUNCIÓN: Implementación directa validate_translation.decision. Origen trazable: src/ui_mod/quality.py.
