def LN_src_ui_mod_generator__load_interface_mod_translations(project_path: str, target_language: str) -> LN_src_ui_mod_generator__List[LN_src_ui_mod_generator__Dict[str, str]]:
    """Load generated MOD text and its optional manual edits for the in-app editor."""
    target = LN_src_ui_mod_generator__resolve_language(target_language)
    # ==============================================================================
    # INICIO: Bloque If de load_interface_mod_translations — target is None
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: target is None. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if target is None:
        raise ValueError(f'Unsupported MOD target language: {target_language}')
    # ==============================================================================
    # FIN: Bloque If de load_interface_mod_translations — target is None
    # ==============================================================================
    scanner = LN_src_ui_mod_generator__ModProjectScanner()
    game_dir = LN_src_ui_mod_generator__resolve_game_dir(project_path)
    language_id = scanner.language_id(project_path, target.renpy)
    data_dir = LN_src_ui_mod_generator__mod_data_dir(game_dir, language_id)
    payload = LN_src_ui_mod_generator___read_json(data_dir / LN_src_ui_mod_generator__DATA_FILE)
    # ==============================================================================
    # INICIO: Bloque If de load_interface_mod_translations — payload is None
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: payload is None. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if payload is None:
        return []
    # ==============================================================================
    # FIN: Bloque If de load_interface_mod_translations — payload is None
    # ==============================================================================
    mapping = payload.get('mapping')
    # ==============================================================================
    # INICIO: Bloque If de load_interface_mod_translations — not isinstance(mapping, dict)
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not isinstance(mapping, dict). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if not isinstance(mapping, dict):
        raise ValueError(f'MOD data does not contain a valid translation mapping: {data_dir / LN_src_ui_mod_generator__DATA_FILE}')
    # ==============================================================================
    # FIN: Bloque If de load_interface_mod_translations — not isinstance(mapping, dict)
    # ==============================================================================
    manual, _legacy = LN_src_ui_mod_generator___load_manual(data_dir / LN_src_ui_mod_generator__MANUAL_FILE)
    return [{'source': source, 'target': manual.get(source, translated)} for source, translated in sorted(mapping.items()) if isinstance(source, str) and isinstance(translated, str)]
