# ==============================================================================
# INICIO: Acción de soporte _publish
# FUNCIÓN: Stage every file, back up the previous versions and replace them together.
#
# On failure every replaced file is restored from its backup and new files are
# removed, so the game never keeps a half-written MOD.
# Implementación directa _publish. Origen trazable: src/ui_mod/generator.py.
# Secuencia del bloque: files.items → staged.values → target.parent.mkdir → LN_src_ui_mod_generator__tempfile.mkstemp → LN_src_ui_mod_generator__Path → backup_root.mkdir → staged.items → str → temp.exists → LN_src_ui_mod_generator__os.fdopen → stream.write → t.exists → LN_src_ui_mod_generator__shutil.copy2 → LN_src_ui_mod_generator__os.replace → replaced.append → backups.values → temp.unlink → target.unlink.
# Interacción con archivos/ejecutables, en orden del código (se respetan las condiciones visibles):
# Paso 1: target.parent.mkdir(parents=True, exist_ok=True).
# Paso 2: LN_src_ui_mod_generator__os.fdopen(fd, 'w', encoding='utf-8', newline='\n').
# Paso 3: backup_root.mkdir(parents=True, exist_ok=True).
# Paso 4: LN_src_ui_mod_generator__shutil.copy2(target, backup).
# Paso 5: LN_src_ui_mod_generator__shutil.copy2(backups[target], target).
# Paso 6: target.unlink(missing_ok=True).
# Paso 7: temp.unlink().
# ==============================================================================
def LN_src_ui_mod_generator___obsolete_hooks(game_dir, output_path):
    """Retire only positively identified generated hooks and their bytecode."""
    import struct
    import zlib
    game_dir = LN_src_ui_mod_generator__Path(game_dir)
    owned_sources = set()
    retired = set()
    for path in game_dir.glob('linguanova_mod_*_multilang.rpy'):
        if path.is_symlink():
            continue
        with path.open('rb') as stream:
            header = stream.read(4096).decode('utf-8-sig', errors='replace')
        if header.startswith('# LinguaNova MOD') and '# Archivo generado por LinguaNova.' in header:
            owned_sources.add(path)
            if path != output_path:
                retired.add(path)
    for path in game_dir.glob('linguanova_mod_*_multilang.rpyc'):
        if path.is_symlink():
            continue
        if path.with_suffix('.rpy') in owned_sources:
            retired.add(path)
            continue
        # Old compiled-only files are identified without unpickling game data.
        raw = path.read_bytes()
        chunks = []
        if raw.startswith(b'RENPY RPC2'):
            position = 10
            while position + 12 <= len(raw):
                slot, start, length = struct.unpack('<III', raw[position:position+12])
                position += 12
                if not slot:
                    break
                if start + length <= len(raw):
                    chunks.append(raw[start:start+length])
        else:
            chunks.append(raw)
        markers = (b'_lnmod_replace_text', b'_lnmod_previous_replace_text', b'_lnmod_embedded')
        for chunk in chunks:
            try:
                data = zlib.decompressobj().decompress(chunk, 128 * 1024 * 1024)
            except zlib.error:
                continue
            if all(marker in data for marker in markers):
                retired.add(path)
                break
    return sorted(retired, key=lambda path: path.name)

def LN_src_ui_mod_generator___publish(files, backup_root, *, retire=()):
    """Publish atomically and back up obsolete owned hooks before retiring them."""
    staged = {}
    backups = {}
    replaced = []
    removed = []
    retirement = [path for path in retire if path not in files and path.exists()]
    try:
        for target, content in files.items():
            target.parent.mkdir(parents=True, exist_ok=True)
            fd, temp_name = LN_src_ui_mod_generator__tempfile.mkstemp(prefix=target.name + '.', suffix='.tmp', dir=str(target.parent))
            with LN_src_ui_mod_generator__os.fdopen(fd, 'w', encoding='utf-8', newline='\n') as stream:
                stream.write(content)
            staged[target] = LN_src_ui_mod_generator__Path(temp_name)
        existing = [path for path in files if path.exists()] + retirement
        if existing:
            backup_root.mkdir(parents=True, exist_ok=True)
            for target in existing:
                backup = backup_root / (target.parent.name + '__' + target.name + '.bak')
                LN_src_ui_mod_generator__shutil.copy2(target, backup)
                backups[target] = backup
        try:
            for target, temp in staged.items():
                LN_src_ui_mod_generator__os.replace(temp, target)
                replaced.append(target)
            for target in retirement:
                target.unlink()
                removed.append(target)
        except Exception:
            for target in reversed(replaced + removed):
                if target in backups:
                    LN_src_ui_mod_generator__shutil.copy2(backups[target], target)
                else:
                    target.unlink(missing_ok=True)
            raise
        return [str(path) for path in backups.values()]
    finally:
        for temp in staged.values():
            if temp.exists():
                temp.unlink()
            # ==============================================================================
            # FIN: Bloque If de _publish — temp.exists()
            # ==============================================================================
        # ==============================================================================
        # FIN: Bloque For de _publish — staged.values()
        # ==============================================================================
    # ==============================================================================
    # FIN: Bloque Try de _publish — gestión de excepciones
    # ==============================================================================
# ==============================================================================
# FIN: Acción de soporte _publish
# ==============================================================================

# ==============================================================================
# INICIO: Acción de soporte mod_data_dir
# FUNCIÓN: Carpeta de datos del MOD para un idioma: game/zz_linguanova/mod/<idioma>/. Nunca dentro
# de game/tl/: allí cada carpeta es un idioma para Ren'Py y las traducciones de otros (o del propio
# desarrollador) no se tocan. Con migrate=True traslada los datos que versiones anteriores dejaron en
# game/tl/<idioma>/ y borra esa carpeta si queda vacía (solo si la creó el MOD).
# ==============================================================================
LN_src_ui_mod_generator__MOD_DATA_ROOT = LN_src_core_constants__DELIVERY_DIR + '/mod'


def LN_src_ui_mod_generator__mod_data_dir(game_dir, language_id: str, migrate: bool=False):
    """Return the MOD data folder of ``language_id`` (see the comment above)."""
    game_dir = LN_src_ui_mod_generator__Path(game_dir)
    new = game_dir / LN_src_ui_mod_generator__MOD_DATA_ROOT / language_id
    legacy = game_dir / 'tl' / language_id
    own = [p for p in legacy.iterdir() if p.name.lower().startswith('linguanova_mod_')] if legacy.is_dir() else []
    if not migrate:
        return new if new.is_dir() or not own else legacy
    if own:
        new.mkdir(parents=True, exist_ok=True)
        for item in own:
            destination = new / item.name
            if destination.exists():
                if item.is_dir():
                    LN_src_ui_mod_generator__shutil.copytree(str(item), str(destination), dirs_exist_ok=True)
                    LN_src_ui_mod_generator__shutil.rmtree(str(item), ignore_errors=True)
                else:
                    item.unlink()
            else:
                LN_src_ui_mod_generator__shutil.move(str(item), str(destination))
        try:
            if not any(legacy.iterdir()):
                legacy.rmdir()
        except OSError:
            pass
    return new
# ==============================================================================
# FIN: Acción de soporte mod_data_dir
# ==============================================================================

# ==============================================================================
# INICIO: Acción de soporte _discover_other_languages
# FUNCIÓN: Implementación directa _discover_other_languages. Origen trazable: src/ui_mod/generator.py.
# Secuencia del bloque: sorted → tl_root.is_dir → data.is_file → folder.name.casefold → current_folder.casefold → tl_root.iterdir → p.is_dir.
# ==============================================================================
def LN_src_ui_mod_generator___discover_other_languages(game_dir: LN_src_ui_mod_generator__Path, current_folder: str, skip=()) -> LN_src_ui_mod_generator__Dict[str, LN_src_ui_mod_generator__Path]:
    out: Dict[str, Path] = {}
    legacy_root = game_dir / 'tl'
    if legacy_root.is_dir():
        for folder in sorted((p for p in legacy_root.iterdir() if p.is_dir())):
            if folder.name.casefold() != current_folder.casefold() and folder.name not in skip and (folder / LN_src_ui_mod_generator__DATA_FILE).is_file():
                LN_src_ui_mod_generator__mod_data_dir(game_dir, folder.name, migrate=True)
    root = game_dir / LN_src_ui_mod_generator__MOD_DATA_ROOT
    if not root.is_dir():
        return out
    for folder in sorted((p for p in root.iterdir() if p.is_dir())):
        if folder.name.casefold() == current_folder.casefold() or folder.name in skip:
            continue
        data = folder / LN_src_ui_mod_generator__DATA_FILE
        if data.is_file():
            out[folder.name] = data
    return out
# ==============================================================================
# FIN: Acción de soporte _discover_other_languages
# ==============================================================================

# ==============================================================================
# INICIO: Acción de soporte _game_tl_languages
# FUNCIÓN: tl/ folders the game itself ships (not MOD languages): fonts are reset for them.
# Implementación directa _game_tl_languages. Origen trazable: src/ui_mod/generator.py.
# Secuencia del bloque: sorted → tl_root.is_dir → lang.casefold → tl_root.iterdir → path.is_dir → path.name.casefold → path.name.startswith.
# ==============================================================================
def LN_src_ui_mod_generator___game_tl_languages(game_dir: LN_src_ui_mod_generator__Path, mod_languages) -> LN_src_ui_mod_generator__List[str]:
    """tl/ folders the game itself ships (not MOD languages): fonts are reset for them."""
    RESOURCE_FOLDERS = LN_src_core_delivery__RESOURCE_FOLDERS
