# ==============================================================================
def LN_src_utils_auto_updater__launch_installer(installer: LN_src_utils_auto_updater__Path, install_dir: LN_src_utils_auto_updater__Path) -> None:
    """Start the installer detached; the caller must quit LinguaNova next."""
    flags = 0
    # ==============================================================================
    # INICIO: Bloque If de launch_installer — LN_src_utils_auto_updater__sys.platform == 'win32'
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_src_utils_auto_updater__sys.platform == 'win32'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if LN_src_utils_auto_updater__sys.platform == 'win32':
        flags = getattr(LN_src_utils_auto_updater__subprocess, 'DETACHED_PROCESS', 0) | getattr(LN_src_utils_auto_updater__subprocess, 'CREATE_NEW_PROCESS_GROUP', 0)
    # ==============================================================================
    # FIN: Bloque If de launch_installer — LN_src_utils_auto_updater__sys.platform == 'win32'
    # ==============================================================================
    LN_src_utils_auto_updater__subprocess.Popen([str(installer), *LN_src_utils_auto_updater__installer_arguments(install_dir)], cwd=str(installer.parent), creationflags=flags, close_fds=True)
# ==============================================================================
# FIN: Acción de soporte launch_installer
