def LN_scripts_comprobar_volumen__execute(entries: int, source_mib: float, workspace: LN_scripts_comprobar_volumen__Path, sdk: str='') -> dict:
    from PyQt6.QtCore import QCoreApplication
    ConfigManager = LN_src_utils_config__ConfigManager
    TranslationManager = LN_src_core_translator__TranslationManager
    TranslationEngine = LN_src_core_translator__TranslationEngine
    TranslationResult = LN_src_core_translator__TranslationResult
    BaseTranslator = LN_src_core_translators_base__BaseTranslator
    TranslationPipeline = LN_src_core_pipeline_orchestrator__TranslationPipeline
    TLParser = LN_src_core_tl_parser__TLParser
    OutputPolicy = LN_src_core_bounded_output__OutputPolicy

    # ==============================================================================
    # INICIO: Clase execute.CorpusTranslator
    # FUNCIÓN: Implementación directa execute.CorpusTranslator. Origen trazable: scripts/comprobar_volumen.py.
    # Secuencia del bloque: request.text.replace(LN_scripts_comprobar_volumen__ENGLISH, LN_scripts_comprobar_volumen__SPANISH).replace → restore_renpy_syntax → TranslationResult → AssertionError → request.metadata.get → request.text.replace → dict → self.translate_single.
    # ==============================================================================
    class CorpusTranslator(BaseTranslator):

        # ==============================================================================
        # INICIO: Acción de soporte execute.CorpusTranslator.translate_single
        # FUNCIÓN: Implementación directa execute.CorpusTranslator.translate_single. Origen trazable: scripts/comprobar_volumen.py.
        # Secuencia del bloque: request.text.replace(LN_scripts_comprobar_volumen__ENGLISH, LN_scripts_comprobar_volumen__SPANISH).replace → restore_renpy_syntax → TranslationResult → AssertionError → request.metadata.get → request.text.replace → dict.
        # ==============================================================================
        async def translate_single(self, request):
            text = request.text.replace(LN_scripts_comprobar_volumen__ENGLISH, LN_scripts_comprobar_volumen__SPANISH).replace('Line ', 'Línea ')
            # ==============================================================================
            # INICIO: Bloque If de execute.CorpusTranslator.translate_single — text == request.text
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: text == request.text. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if text == request.text:
                raise AssertionError('The test provider received an unexpected source segment')
            # ==============================================================================
            # FIN: Bloque If de execute.CorpusTranslator.translate_single — text == request.text
            # ==============================================================================
            restore_renpy_syntax = LN_src_core_syntax_guard__restore_renpy_syntax
            text = restore_renpy_syntax(text, request.metadata.get('placeholders', {}))
            return TranslationResult(request.text, text, request.source_lang, request.target_lang, request.engine, True, metadata=dict(request.metadata))
        # ==============================================================================
        # FIN: Acción de soporte execute.CorpusTranslator.translate_single
        # ==============================================================================

        # ==============================================================================
        # INICIO: Acción de soporte execute.CorpusTranslator.translate_batch
        # FUNCIÓN: Implementación directa execute.CorpusTranslator.translate_batch. Origen trazable: scripts/comprobar_volumen.py.
        # Secuencia del bloque: self.translate_single.
        # ==============================================================================
        async def translate_batch(self, requests, *args, **kwargs):
            return [await self.translate_single(request) for request in requests]
        # ==============================================================================
        # FIN: Acción de soporte execute.CorpusTranslator.translate_batch
        # ==============================================================================

        # ==============================================================================
        # INICIO: Acción de soporte execute.CorpusTranslator.get_supported_languages
        # FUNCIÓN: Implementación directa execute.CorpusTranslator.get_supported_languages. Origen trazable: scripts/comprobar_volumen.py.
        # Secuencia del bloque: evalúa y devuelve los datos definidos en el cuerpo.
        # ==============================================================================
        def get_supported_languages(self):
            return {'en': 'English', 'es': 'Spanish'}
        # ==============================================================================
        # FIN: Acción de soporte execute.CorpusTranslator.get_supported_languages
        # ==============================================================================
    # ==============================================================================
    # FIN: Clase execute.CorpusTranslator
    # ==============================================================================
    application = QCoreApplication.instance() or QCoreApplication([])
    game = workspace / 'game'
    # ==============================================================================
    # INICIO: Bloque If de execute — game.exists() and any(game.iterdir())
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: game.exists() and any(game.iterdir()). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if game.exists() and any(game.iterdir()):
        existing_source = game / 'gallery_scenes2.rpy'
        # ==============================================================================
        # INICIO: Bloque If de execute — not existing_source.is_file() or not existing_source.open(encoding='utf-8').readline().startswith('define config.name = "LinguaNova volume test"')
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not existing_source.is_file() or not existing_source.open(encoding='utf-8').readline().startswith('define config.name = "LinguaNova volume test"'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if not existing_source.is_file() or not existing_source.open(encoding='utf-8').readline().startswith('define config.name = "LinguaNova volume test"'):
            raise ValueError('Use an empty test workspace, never an existing game installation')
        # ==============================================================================
        # FIN: Bloque If de execute — not existing_source.is_file() or not existing_source.open(encoding='utf-8').readline().startswith('define config.name = "LinguaNova volume test"')
        # ==============================================================================
    # ==============================================================================
    # FIN: Bloque If de execute — game.exists() and any(game.iterdir())
    # ==============================================================================
    game.mkdir(parents=True, exist_ok=True)
    source = game / 'gallery_scenes2.rpy'
    target_per_line = int(source_mib * 1048576 / entries)
    repeats = max(1, (target_per_line - 50 + len(LN_scripts_comprobar_volumen__ENGLISH)) // (len(LN_scripts_comprobar_volumen__ENGLISH) + 1))
    paragraph = ' '.join([LN_scripts_comprobar_volumen__ENGLISH] * repeats)
    # ==============================================================================
    # INICIO: Bloque With de execute — source.open('w', encoding='utf-8', newline='\n')
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: source.open('w', encoding='utf-8', newline='\n'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    with source.open('w', encoding='utf-8', newline='\n') as stream:
        stream.write('define config.name = "LinguaNova volume test"\ndefine config.save_directory = None\ndefine e = Character("Eva")\ndefault player_name = "Alex"\nlabel start:\n')
        # ==============================================================================
        # INICIO: Bloque For de execute — range(entries)
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: range(entries). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for number in range(entries):
            stream.write('    e "Line {:06d}: {} [player_name] {{i}}safe{{/i}}."\n'.format(number, paragraph))
        # ==============================================================================
        # FIN: Bloque For de execute — range(entries)
        # ==============================================================================
        stream.write('    return\n')
    # ==============================================================================
    # FIN: Bloque With de execute — source.open('w', encoding='utf-8', newline='\n')
    # ==============================================================================
    source_hash = LN_scripts_comprobar_volumen__hashlib.sha256(source.read_bytes()).hexdigest()
    report = {'entries_requested': entries, 'source_bytes': source.stat().st_size, 'source_sha256': source_hash, 'provider': 'deterministic_fixture_no_network', 'phases': {}}
    print('Source: {} bytes / {} dialogue lines'.format(report['source_bytes'], entries), flush=True)
    config = ConfigManager(config_file='volume-test.json')
    config.data_dir = workspace / 'data'
    config.data_dir.mkdir(exist_ok=True)
    settings = config.translation_settings
    settings.source_language, settings.target_language = ('english', 'spanish')
    settings.use_cache, settings.use_global_cache = (False, False)
    settings.request_delay, settings.max_batch_size = (0, 100)
    settings.enable_runtime_hook = False
    manager = TranslationManager(config_manager=config)
    manager.add_translator(TranslationEngine.GOOGLE, CorpusTranslator(config_manager=config))
    pipeline = TranslationPipeline(config, manager)
    pipeline.project_path, pipeline.game_exe_path = (str(workspace), str(workspace / 'VolumeTest.exe'))
    pipeline.source_language, pipeline.target_language = ('english', 'spanish')
    pipeline.engine = TranslationEngine.GOOGLE
    pipeline.include_rpyc, pipeline.include_deep_scan = (False, False)
    errors = []
    pipeline.log_message.connect(lambda level, message: errors.append(message) if level == 'error' else None)

    # ==============================================================================
    # INICIO: Acción de soporte execute.phase
    # FUNCIÓN: Implementación directa execute.phase. Origen trazable: scripts/comprobar_volumen.py.
    # Secuencia del bloque: print → LN_scripts_comprobar_volumen__time.monotonic → operation → round → 'Finished {} in {} s'.format.
    # ==============================================================================
    def phase(name, operation):
        print('Starting ' + name, flush=True)
        start = LN_scripts_comprobar_volumen__time.monotonic()
        value = operation()
        report['phases'][name] = round(LN_scripts_comprobar_volumen__time.monotonic() - start, 3)
        print('Finished {} in {} s'.format(name, report['phases'][name]), flush=True)
        return value
    # ==============================================================================
    # FIN: Acción de soporte execute.phase
    # ==============================================================================
    # ==============================================================================
    # INICIO: Bloque If de execute — not phase('extract_and_generate', lambda: pipeline._run_translate_command(str(workspace)))
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not phase('extract_and_generate', lambda: pipeline._run_translate_command(str(workspace))). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if not phase('extract_and_generate', lambda: pipeline._run_translate_command(str(workspace))):
        raise AssertionError(errors)
    # ==============================================================================
    # FIN: Bloque If de execute — not phase('extract_and_generate', lambda: pipeline._run_translate_command(str(workspace)))
    # ==============================================================================
    tl = game / 'tl/spanish'
    files = phase('parse_generated', lambda: TLParser().parse_directory(str(game / 'tl'), 'spanish'))
    all_candidates = [entry for file in files for entry in file.entries]
    report['all_extracted_entries'] = len(all_candidates)
    candidates = [entry for entry in all_candidates if entry.original_text.startswith('Line ')]
    del all_candidates
    assert len(candidates) == entries, (len(candidates), entries)
    translations = phase('translate_fixture', lambda: pipeline._translate_entries(candidates))
    saved, failed = phase('save_and_rebalance', lambda: pipeline._save_tl_files(files, translations))
    assert not failed and (not errors), (failed, errors)
    parsed = phase('verify_output', lambda: TLParser().parse_directory(str(game / 'tl'), 'spanish'))
    seen, total, translated = (set(), 0, 0)
    # ==============================================================================
    # INICIO: Bloque For de execute — parsed
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: parsed. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    for file in parsed:
        # ==============================================================================
        # INICIO: Bloque For de execute — file.entries
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: file.entries. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for entry in file.entries:
            # ==============================================================================
            # INICIO: Bloque If de execute — not entry.original_text.startswith('Line ')
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: not entry.original_text.startswith('Line '). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if not entry.original_text.startswith('Line '):
                continue
            # ==============================================================================
            # FIN: Bloque If de execute — not entry.original_text.startswith('Line ')
            # ==============================================================================
            assert entry.original_text not in seen
            seen.add(entry.original_text)
            assert '[player_name]' in entry.translated_text and '{/i}' in entry.translated_text
            assert LN_scripts_comprobar_volumen__SPANISH in entry.translated_text
            total += 1
            translated += not entry.needs_translation() and (not entry.is_source_copy())
        # ==============================================================================
        # FIN: Bloque For de execute — file.entries
        # ==============================================================================
    # ==============================================================================
    # FIN: Bloque For de execute — parsed
    # ==============================================================================
    assert total == translated == entries
    outputs = list(tl.rglob('*.rpy'))
    policy = OutputPolicy.from_config(config)
    assert all((path.stat().st_size <= policy.max_bytes for path in outputs))
    assert LN_scripts_comprobar_volumen__hashlib.sha256(source.read_bytes()).hexdigest() == source_hash
    report.update(entries_written=total, translated=translated, files=len(outputs), largest_output_bytes=max((path.stat().st_size for path in outputs)), total_output_bytes=sum((path.stat().st_size for path in outputs)), source_unchanged=True, counts=dict(pipeline._run_counts), policy=vars(policy))
    del translations, candidates, parsed, files, seen, pipeline, manager
    import gc
    gc.collect()
    # ==============================================================================
    # INICIO: Bloque If de execute — sdk
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: sdk. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if sdk:
        launcher = LN_scripts_comprobar_volumen__Path(sdk) / ('renpy.exe' if LN_scripts_comprobar_volumen__sys.platform == 'win32' else 'renpy.sh')
        (game / 'volume_start.rpy').write_text('define config.gl_enable = False\ndefine config.performance_test = False\nlabel main_menu:\n    $ renpy.change_language("spanish")\n    $ renpy.quit(status=0, save=False)\n', encoding='utf-8')
        env = dict(LN_scripts_comprobar_volumen__os.environ, SDL_AUDIODRIVER='dummy', RENPY_RENDERER='gl2', RENPY_DISABLE_SOUND='1')
        # ==============================================================================
        # INICIO: Bloque If de execute — LN_scripts_comprobar_volumen__sys.platform != 'win32'
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_scripts_comprobar_volumen__sys.platform != 'win32'. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        if LN_scripts_comprobar_volumen__sys.platform != 'win32':
            env['SDL_VIDEODRIVER'] = 'x11' if env.get('DISPLAY') else 'dummy'
        # ==============================================================================
        # FIN: Bloque If de execute — LN_scripts_comprobar_volumen__sys.platform != 'win32'
        # ==============================================================================
        # ==============================================================================
        # INICIO: Bloque For de execute — ('errors.txt', 'traceback.txt')
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: ('errors.txt', 'traceback.txt'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        for filename in ('errors.txt', 'traceback.txt'):
            previous = workspace / filename
            # ==============================================================================
            # INICIO: Bloque If de execute — previous.exists()
            # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: previous.exists(). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
            # ==============================================================================
            if previous.exists():
                previous.replace(workspace / ('previous_' + filename))
            # ==============================================================================
            # FIN: Bloque If de execute — previous.exists()
            # ==============================================================================
        # ==============================================================================
        # FIN: Bloque For de execute — ('errors.txt', 'traceback.txt')
        # ==============================================================================
        start = LN_scripts_comprobar_volumen__time.monotonic()
        # ==============================================================================
        # INICIO: Bloque With de execute — (workspace / 'engine.log').open('w')
        # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: (workspace / 'engine.log').open('w'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
        # ==============================================================================
        with (workspace / 'engine.log').open('w') as log:
            result = LN_scripts_comprobar_volumen__subprocess.run([str(launcher), str(workspace)], stdout=log, stderr=log, env=env, timeout=600)
        # ==============================================================================
        # FIN: Bloque With de execute — (workspace / 'engine.log').open('w')
        # ==============================================================================
        output = (workspace / 'engine.log').read_text(errors='replace')
        assert result.returncode == 0, output[-3000:]
        assert not (workspace / 'errors.txt').exists(), output[-3000:]
        assert not (workspace / 'traceback.txt').exists(), output[-3000:]
        report['engine'] = {'sdk': launcher.parent.name, 'status': 'passed', 'seconds': round(LN_scripts_comprobar_volumen__time.monotonic() - start, 3)}
    # ==============================================================================
    # FIN: Bloque If de execute — sdk
    # ==============================================================================
    # ==============================================================================
    # INICIO: Bloque Try de execute — gestión de excepciones
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: gestión de excepciones. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    try:
        import resource
        report['pipeline_peak_rss_kib'] = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
        report['engine_peak_rss_kib'] = resource.getrusage(resource.RUSAGE_CHILDREN).ru_maxrss
    except ImportError:
        pass
    # ==============================================================================
    # FIN: Bloque Try de execute — gestión de excepciones
    # ==============================================================================
    return report
# ==============================================================================
# FIN: Acción de soporte execute
