# ==============================================================================
def LN_scripts_comprobar_volumen__main():
    parser = LN_scripts_comprobar_volumen__argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--entries', type=int, default=200000)
    parser.add_argument('--source-mib', type=float, default=50)
    parser.add_argument('--workspace', type=LN_scripts_comprobar_volumen__Path)
    parser.add_argument('--sdk', default='')
    parser.add_argument('--report', type=LN_scripts_comprobar_volumen__Path)
    args = parser.parse_args()
    # ==============================================================================
    # INICIO: Bloque If de main — args.entries < 1 or args.source_mib <= 0
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: args.entries < 1 or args.source_mib <= 0. Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    if args.entries < 1 or args.source_mib <= 0:
        parser.error('entries and source-mib must be positive')
    # ==============================================================================
    # FIN: Bloque If de main — args.entries < 1 or args.source_mib <= 0
    # ==============================================================================
    # ==============================================================================
    # INICIO: Bloque With de main — LN_scripts_comprobar_volumen__tempfile.TemporaryDirectory(prefix='linguanova-volume-')
    # FUNCIÓN: Ejecuta íntegramente esta rama del flujo. Condición/recurso/iteración exacta: LN_scripts_comprobar_volumen__tempfile.TemporaryDirectory(prefix='linguanova-volume-'). Conserva todos los subniveles, ramas alternativas y manejo de errores que figuran debajo.
    # ==============================================================================
    with LN_scripts_comprobar_volumen__tempfile.TemporaryDirectory(prefix='linguanova-volume-') as directory:
        report = LN_scripts_comprobar_volumen__execute(args.entries, args.source_mib, args.workspace or LN_scripts_comprobar_volumen__Path(directory), args.sdk)
    # ==============================================================================
    # FIN: Bloque With de main — LN_scripts_comprobar_volumen__tempfile.TemporaryDirectory(prefix='linguanova-volume-')
    # ==============================================================================
    text = LN_scripts_comprobar_volumen__json.dumps(report, ensure_ascii=False, indent=2)
    # ==============================================================================
    # INICIO: Bloque If de main — args.report
