# INICIO: Módulo src/core/project_glossary.py
# FUNCIÓN: Glosario de cada juego y cada idioma de destino, guardado dentro del juego en
# game/zz_linguanova/glossary/<idioma>.json (el mismo archivo que usa el MOD), y análisis
# del juego completo (.rpy, .rpyc y .rpa) que solo vive en memoria mientras el programa
# está abierto.
# ==============================================================================
"""Glossary of one game and one target language, plus a whole-game analysis.

Where the glossary lives
    ``game/zz_linguanova/glossary/<language folder>.json``. One file per game and
    per target language, so a Spanish translation never receives French terms and
    one game's terms never reach another game. It is kept out of ``game/tl/``
    because Ren'Py lists every folder there as a language. The file travels in the
    share package. The translator and the interface MOD read the same file.
    Format: ``{"schema": 1, "help": "...", "terms": {"original": "translation"}}``.
    A term equal on both sides is kept as is; an empty translation is pending and
    is not applied.

What is never written
    ``analyze()`` reads every script the game has (visible ``.rpy``, scripts and
    compiled ``.rpyc`` inside ``.rpa`` archives, and compiled files without
    source) and returns character names and recurring proper nouns. The result
    stays in memory for this session only; translations keep names untranslated
    from it without storing anything.
"""
import collections as LN_src_core_project_glossary__collections
import json as LN_src_core_project_glossary__json
import os as LN_src_core_project_glossary__os
import re as LN_src_core_project_glossary__re
import tempfile as LN_src_core_project_glossary__tempfile
import threading as LN_src_core_project_glossary__threading
import time as LN_src_core_project_glossary__time
from dataclasses import dataclass as LN_src_core_project_glossary__dataclass, field as LN_src_core_project_glossary__field
from pathlib import Path as LN_src_core_project_glossary__Path
LN_src_core_project_glossary__FILE_NAME = 'linguanova_glossary.json'
LN_src_core_project_glossary__LEGACY_MOD_FILE = 'linguanova_mod_glossary.json'
LN_src_core_project_glossary__SCHEMA = 1
LN_src_core_project_glossary__HELP = 'Términos que deben traducirse siempre igual en este idioma: "original": "traducción". Un término igual en ambos lados no se traduce. Uno vacío queda pendiente y no se aplica.'
LN_src_core_project_glossary___SKIP_DIRS = {'tl', 'cache', 'saves', '__pycache__', 'zz_linguanova', 'linguanova_fonts', 'linguanova_mod_fonts'}
LN_src_core_project_glossary___QUOTED_RE = LN_src_core_project_glossary__re.compile('"((?:[^"\\\n]|\\.)*)"|\'((?:[^\'\\\n]|\\.)*)\'')
LN_src_core_project_glossary___MARKUP_RE = LN_src_core_project_glossary__re.compile('\\{[^{}]*\\}|\\[[^\\[\\]]*\\]')
LN_src_core_project_glossary___WORD_RE = LN_src_core_project_glossary__re.compile('[^\\W\\d_]{3,}')
LN_src_core_project_glossary___SENTENCE_START = '.!?"“«:—-…'
LN_src_core_project_glossary___SESSION = {}
LN_src_core_project_glossary___LOCK = LN_src_core_project_glossary__threading.Lock()


def LN_src_core_project_glossary__game_dir_of(project_path):
    """The game's ``game/`` folder, or None when the path is not a game."""
    if not project_path:
        return None
    try:
        return LN_src_core_sharing_translation_package__find_game_dir(str(project_path))
    except Exception:
        return None


def LN_src_core_project_glossary__glossary_path(project_path, language_folder):
    """``game/zz_linguanova/glossary/<folder>.json`` or None.

    Never under ``game/tl/``: Ren'Py turns every folder there into a language of
    the game's menu, even one holding a single JSON file.
    """
    game = LN_src_core_project_glossary__game_dir_of(project_path)
    folder = str(language_folder or '').strip()
    if game is None or not folder or not folder.isidentifier() or folder.casefold() == 'none':
        return None
    return game / LN_src_core_constants__DELIVERY_DIR / 'glossary' / (folder + '.json')


def LN_src_core_project_glossary__load(path):
    """Terms of one glossary file (the MOD's older file name is read too)."""
    if path is None:
        return {}
    path = LN_src_core_project_glossary__Path(path)
    source = path if path.is_file() else LN_src_core_project_glossary__legacy_source(path)
    if source is None:
        return {}
    try:
        payload = LN_src_core_project_glossary__json.loads(source.read_text(encoding='utf-8-sig'))
    except (OSError, ValueError):
        return {}
    if isinstance(payload, dict) and isinstance(payload.get('terms'), dict):
        payload = payload['terms']
    return LN_src_core_glossary_manager__sanitize_glossary(payload)


def LN_src_core_project_glossary___legacy_files(path):
    """Older places of this glossary: tl/<folder>/linguanova_glossary.json (5 Nov 2026)
    and the MOD's tl/<folder>/linguanova_mod_glossary.json."""
    path = LN_src_core_project_glossary__Path(path)
    folder = path.stem
    game = path.parent.parent.parent
    return [game / 'tl' / folder / LN_src_core_project_glossary__FILE_NAME, game / 'tl' / folder / LN_src_core_project_glossary__LEGACY_MOD_FILE]


def LN_src_core_project_glossary__legacy_source(path):
    """The first older glossary file that exists, or None."""
    return next((p for p in LN_src_core_project_glossary___legacy_files(path) if p.is_file()), None)


def LN_src_core_project_glossary__retire_legacy(path):
    """Remove tl/<folder>/linguanova_glossary.json (a glossary written there would
    make Ren'Py list the folder as a language) and the folder if it is left empty."""
    old = LN_src_core_project_glossary___legacy_files(path)[0]
    try:
        if old.is_file():
            old.unlink()
        folder = old.parent
        if folder.is_dir() and not any(folder.iterdir()):
            folder.rmdir()
    except OSError:
        pass


def LN_src_core_project_glossary__save(path, terms, language_folder=''):
    """Write the glossary next to its language; True when it was saved."""
    if path is None:
        return False
    path = LN_src_core_project_glossary__Path(path)
    path.parent.mkdir(parents=True, exist_ok=True)
    clean = LN_src_core_glossary_manager__sanitize_glossary(terms)
    payload = {'schema': LN_src_core_project_glossary__SCHEMA, 'help': LN_src_core_project_glossary__HELP, 'language': language_folder or path.parent.name, 'terms': dict(sorted(clean.items(), key=lambda kv: kv[0].casefold()))}
    content = LN_src_core_project_glossary__json.dumps(payload, ensure_ascii=False, indent=2) + '\n'
    saved = bool(LN_src_utils_encoding__save_text_safely(path, content, encoding='utf-8', newline='\n'))
    if saved:
        LN_src_core_project_glossary__retire_legacy(path)
    return saved


@LN_src_core_project_glossary__dataclass
class LN_src_core_project_glossary__GameAnalysis:
    """Everything worth protecting that the game contains (memory only)."""
    game_dir: str = ''
    names: list = LN_src_core_project_glossary__field(default_factory=list)
    terms: list = LN_src_core_project_glossary__field(default_factory=list)
    script_files: int = 0
    archive_files: int = 0
    compiled_files: int = 0
    unreadable: int = 0
    seconds: float = 0.0
LN_src_core_project_glossary__GameAnalysis.__name__ = 'GameAnalysis'


def LN_src_core_project_glossary___visible(game, suffixes):
    out = []
    for base, dirs, names in LN_src_core_project_glossary__os.walk(game):
        rel_base = LN_src_core_project_glossary__Path(base).relative_to(game)
        dirs[:] = [d for d in dirs if d.lower() not in LN_src_core_project_glossary___SKIP_DIRS and (not d.startswith('.'))]
        for name in names:
            low = name.lower()
            if low.endswith(suffixes) and (not LN_src_core_constants__is_linguanova_generated_script(str(rel_base / name))) and (not low.startswith(('linguanova_mod_', 'zz_linguanova_', 'zzz_linguanova_'))):
                out.append(LN_src_core_project_glossary__Path(base) / name)
    return sorted(out)


def LN_src_core_project_glossary___signature(game):
    """Cheap fingerprint of the game's scripts and archives."""
    items = []
    for path in LN_src_core_project_glossary___visible(game, ('.rpy', '.rpym', '.rpyc', '.rpymc', '.rpa')):
        try:
            stat = path.stat()
            items.append((str(path), stat.st_size, int(stat.st_mtime)))
        except OSError:
            continue
    return tuple(items)


def LN_src_core_project_glossary___names_in(value, names):
    for regex in (LN_src_core_parser___CHARACTER_NAME_ARG_RE, LN_src_ui_mod_scanner___CHARACTER_RE):
        for match in regex.finditer(value or ''):
            name = (match.group('name') or '').strip()
            if name and LN_src_core_parser___PLAIN_NAME_RE.match(name) and (not any((ch in name for ch in '[]{}%'))):
                names.add(name)


def LN_src_core_project_glossary___count_words(value, counter):
    plain = LN_src_core_project_glossary___MARKUP_RE.sub(' ', value or '')
    if len(plain.split()) < 3:
        return  # prose only: labels, file names and code values are not story terms
    for match in LN_src_core_project_glossary___WORD_RE.finditer(plain):
        word = match.group(0)
        if not (word[0].isupper() and word[1:].islower()):
            continue
        before = plain[:match.start()].rstrip()
        if not before or before[-1] in LN_src_core_project_glossary___SENTENCE_START:
            continue
        counter[word] += 1


def LN_src_core_project_glossary___strings_of_source(source):
    for match in LN_src_core_project_glossary___QUOTED_RE.finditer(source):
        yield match.group(1) if match.group(1) is not None else match.group(2)


def LN_src_core_project_glossary__analyze(project_path, min_count=3, max_terms=100):
    """Read the whole game once per session; later calls reuse the result."""
    game = LN_src_core_project_glossary__game_dir_of(project_path)
    if game is None:
        return LN_src_core_project_glossary__GameAnalysis()
    key = LN_src_core_project_glossary__os.path.normcase(str(game))
    signature = LN_src_core_project_glossary___signature(game)
    with LN_src_core_project_glossary___LOCK:
        cached = LN_src_core_project_glossary___SESSION.get(key)
        if cached and cached[0] == signature:
            return cached[1]
    started = LN_src_core_project_glossary__time.monotonic()
    result = LN_src_core_project_glossary__GameAnalysis(game_dir=str(game))
    names, counter = set(), LN_src_core_project_glossary__collections.Counter()
    sources, compiled = {}, {}
    for path in LN_src_core_project_glossary___visible(game, ('.rpy', '.rpym')):
        try:
            sources[path.relative_to(game).as_posix().lower()] = path.read_text(encoding='utf-8-sig', errors='replace')
            result.script_files += 1
        except OSError:
            result.unreadable += 1
    for rpa in LN_src_core_project_glossary___visible(game, ('.rpa',)):
        try:
            members = LN_src_ui_mod_scanner__read_archive_members(rpa, ('.rpy', '.rpym', '.rpyc', '.rpymc'))
        except Exception:
            result.unreadable += 1
            continue
        for rel, data in members:
            rel = rel.replace('\\', '/').lower()
            if rel.startswith('tl/') or rel.startswith('renpy/'):
                continue
            if rel.endswith(('.rpyc', '.rpymc')):
                compiled.setdefault(rel[:-1], ('data', data))
            elif rel not in sources:
                sources[rel] = LN_src_ui_mod_scanner___decode_source(data)
                result.archive_files += 1
    for path in LN_src_core_project_glossary___visible(game, ('.rpyc', '.rpymc')):
        compiled[path.relative_to(game).as_posix().lower()[:-1]] = ('path', path)
    for source in sources.values():
        LN_src_core_project_glossary___names_in(source, names)
        for value in LN_src_core_project_glossary___strings_of_source(source):
            LN_src_core_project_glossary___count_words(value, counter)
    orphans = [item for rel, item in sorted(compiled.items()) if rel not in sources]
    if orphans:
        with LN_src_core_project_glossary__tempfile.TemporaryDirectory(prefix='linguanova_glossary_') as tmp:
            for index, (kind, value) in enumerate(orphans):
                path = value
                if kind == 'data':
                    path = LN_src_core_project_glossary__Path(tmp) / f'{index}.rpyc'
                    path.write_bytes(value)
                try:
                    extracted = LN_src_core_rpyc_reader__ASTTextExtractor(None).extract_from_file(path)
                    nodes = LN_src_core_rpyc_reader__read_rpyc_file(path)
                except Exception:
                    result.unreadable += 1
                    continue
                result.compiled_files += 1
                for item in extracted or []:
                    LN_src_core_project_glossary___count_words(getattr(item, 'text', '') or '', counter)
                for string in LN_src_ui_mod_scanner___strings_in(nodes):
                    if 'Character' in string:
                        LN_src_core_project_glossary___names_in(string, names)
    stop = set(LN_src_core_glossary_manager__COMMON_ENGLISH_STOPWORDS) | {'true', 'false', 'none'}
    name_words = {part.casefold() for name in names for part in name.split()}
    result.names = sorted(names, key=str.casefold)
    result.terms = [(word, count) for word, count in counter.most_common() if count >= min_count and word.casefold() not in stop and word.casefold() not in name_words][:max_terms]
    result.seconds = round(LN_src_core_project_glossary__time.monotonic() - started, 2)
    with LN_src_core_project_glossary___LOCK:
        LN_src_core_project_glossary___SESSION[key] = (signature, result)
    return result


def LN_src_core_project_glossary__forget(project_path=None):
    """Drop the in-memory analysis (one game, or all of them)."""
    with LN_src_core_project_glossary___LOCK:
        if project_path is None:
            LN_src_core_project_glossary___SESSION.clear()
            return
        game = LN_src_core_project_glossary__game_dir_of(project_path)
        if game is not None:
            LN_src_core_project_glossary___SESSION.pop(LN_src_core_project_glossary__os.path.normcase(str(game)), None)
# ==============================================================================
# FIN: Módulo src/core/project_glossary.py
