LN_src_tools_game_optimizer__EXT_VIDEO = {'.webm', '.mp4', '.mkv', '.ogv', '.avi', '.m4v', '.mov'}
LN_src_tools_game_optimizer__ROOT_JUNK = {'log.txt', 'errors.txt', 'traceback.txt', 'output.txt'}
LN_src_tools_game_optimizer__GAME_JUNK = {'saves', 'cache'}            # only directly inside game/
LN_src_tools_game_optimizer__ROOT_SKIP = {'.linguanova_backups'}       # LinguaNova backups stay with the original
